// Runtime texture atlas. Every texture the engine samples comes from an atlas
// WE packed (procgen canvases, rasterized text, generated art) — so bleed
// prevention is the PACKER's job, never the game's: 2px transparent gutters
// between frames plus a half-texel UV inset applied to every stored rect.
//
// Module load is DOM-free; canvas work happens inside build()/rasterText().

/** One packed frame: half-texel-inset UVs + the frame's pixel size. */
export interface Frame {
  u0: number; v0: number; u1: number; v1: number;
  /** Source pixel size — the natural draw size for sprite(). */
  w: number; h: number;
}

export interface PackedBox { x: number; y: number }

/**
 * Pure shelf-packing: place `cells` (in order) into rows that wrap at `maxW`.
 * Returns each cell's position plus the finished sheet size. Exported for
 * headless tests; Atlas.build() drives it.
 */
export function packShelves(
  cells: ReadonlyArray<{ w: number; h: number }>,
  maxW = 1024,
  pad = 2,
): { boxes: PackedBox[]; width: number; height: number } {
  const boxes: PackedBox[] = [];
  let x = pad, y = pad, rowH = 0, width = 0;
  for (const c of cells) {
    if (x + c.w + pad > maxW && x > pad) { x = pad; y += rowH + pad; rowH = 0; }
    boxes.push({ x, y });
    x += c.w + pad;
    rowH = Math.max(rowH, c.h);
    width = Math.max(width, x);
  }
  return { boxes, width: Math.max(width, pad * 2 + 1), height: y + rowH + pad };
}

interface Cell { src: HTMLCanvasElement; sx: number; w: number; h: number }

/**
 * The engine's frame store. `add()` canvases (a horizontal strip slices into
 * frames via `frameW`) and get back the first frame's index; `build()` packs
 * everything into one canvas + UV table. Frame 0 is always a built-in white
 * square — the tintable solid, and the texture the shape verbs ride on.
 */
export class Atlas {
  private cells: Cell[] = [];
  /** True when frames were added since the last build() — build() repacks. */
  dirty = true;
  /**
   * Monotonic build counter — bumped on every build(). The GPU owner uploads
   * whenever this differs from what it last uploaded, so a repack that clears
   * `dirty` WITHOUT going through the owner (e.g. frameSize() calling build()
   * to measure) can't leave the uploaded texture stale against the new UVs.
   */
  generation = 0;
  frames: Frame[] = [];
  canvas: HTMLCanvasElement | null = null;

  constructor(private maxW = 1024, private pad = 2) {}

  /** Register a canvas (or strip of square-ish frames). Returns the first frame index. */
  add(src: HTMLCanvasElement, frameW?: number): number {
    const first = this.cells.length + 1; // +1: frame 0 is the built-in white
    const fw = frameW ?? src.width;
    for (let sx = 0; sx + 1 <= src.width; sx += fw) {
      this.cells.push({ src, sx, w: Math.min(fw, src.width - sx), h: src.height });
    }
    this.dirty = true;
    return first;
  }

  /** Number of frames a strip of width `srcW` sliced at `frameW` yields. */
  static count(srcW: number, frameW: number): number {
    return Math.max(1, Math.ceil(srcW / frameW));
  }

  /** Pack all cells (plus the white frame 0) into one canvas + UV table. */
  build(): { canvas: HTMLCanvasElement; frames: Frame[] } {
    const WHITE = 4; // 4×4 white square, frame 0
    const sizes = [{ w: WHITE, h: WHITE }, ...this.cells.map((c) => ({ w: c.w, h: c.h }))];
    const packed = packShelves(sizes, this.maxW, this.pad);
    const canvas = document.createElement('canvas');
    canvas.width = packed.width;
    canvas.height = packed.height;
    const ctx = canvas.getContext('2d')!;
    ctx.imageSmoothingEnabled = false;
    const hu = 0.5 / canvas.width, hv = 0.5 / canvas.height; // half texel
    const frames: Frame[] = [];
    const place = (x: number, y: number, w: number, h: number): void => {
      frames.push({
        u0: x / canvas.width + hu, v0: y / canvas.height + hv,
        u1: (x + w) / canvas.width - hu, v1: (y + h) / canvas.height - hv,
        w, h,
      });
    };
    ctx.fillStyle = '#fff';
    ctx.fillRect(packed.boxes[0].x, packed.boxes[0].y, WHITE, WHITE);
    place(packed.boxes[0].x, packed.boxes[0].y, WHITE, WHITE);
    this.cells.forEach((c, i) => {
      const b = packed.boxes[i + 1];
      ctx.drawImage(c.src, c.sx, 0, c.w, c.h, b.x, b.y, c.w, c.h);
      place(b.x, b.y, c.w, c.h);
    });
    this.canvas = canvas;
    this.frames = frames;
    this.dirty = false;
    this.generation++;
    return { canvas, frames };
  }
}

/**
 * Upload an image source (canvas, image, or bitmap) to a sampleable rgba8unorm
 * texture. `premultiply` asks the copy to premultiply RGB by alpha — set it for
 * anything a PREMULTIPLIED-blend shader samples directly (rasterized text
 * blocks); leave it off for the atlas, whose batches do the multiply themselves.
 */
export function textureFromCanvas(
  device: GPUDevice,
  source: HTMLCanvasElement | OffscreenCanvas | HTMLImageElement | ImageBitmap,
  premultiply = false,
): GPUTexture {
  const texture = device.createTexture({
    size: { width: source.width, height: source.height },
    format: 'rgba8unorm',
    usage: 0x4 /* TEXTURE_BINDING */ | 0x2 /* COPY_DST */ | 0x10 /* RENDER_ATTACHMENT */,
  });
  device.queue.copyExternalImageToTexture(
    { source },
    { texture, premultipliedAlpha: premultiply },
    { width: source.width, height: source.height },
  );
  return texture;
}

/**
 * Rasterize a text string to a canvas once — register it as a frame and it
 * batches like any sprite. (Interim text path: the bitmap-font atlas + HUD
 * pass land in a later milestone.)
 */
export function rasterText(text: string, opts?: { font?: string; color?: string; pad?: number }): HTMLCanvasElement {
  const font = opts?.font ?? 'bold 28px monospace';
  const color = opts?.color ?? '#ffffff';
  const pad = opts?.pad ?? 2;
  const c = document.createElement('canvas');
  const ctx = c.getContext('2d')!;
  ctx.font = font;
  const m = ctx.measureText(text);
  c.width = Math.ceil(m.width) + pad * 2;
  c.height = Math.ceil((m.actualBoundingBoxAscent || 20) + (m.actualBoundingBoxDescent || 8)) + pad * 2;
  ctx.font = font; // canvas resize resets state
  ctx.fillStyle = color;
  ctx.textBaseline = 'top';
  ctx.fillText(text, pad, pad);
  return c;
}
