// color-kit — the colour service (hsv, wheel, rainbow, ramp, gradient,
// lerp, shift; every function returns a '#rrggbb' hex string the draw verbs
// accept). Ported verbatim from the raster engine; carried example-local
// until parity-plan Phase 2 LIFTED it here (exported namespaced as
// `colorKit` — generic names like lerp/ramp must not collide with the flat
// engine surface). Pure + dist-tested.

/** A `'#rrggbb'` hex colour string — the format every v2 draw verb accepts. */
export type Hex = string;

const clamp01 = (n: number): number => (n < 0 ? 0 : n > 1 ? 1 : n);
const wrap360 = (h: number): number => ((h % 360) + 360) % 360;
const byte = (n: number): string => Math.round(clamp01(n) * 255).toString(16).padStart(2, '0');

/** Saturation/value tuning shared by the wheel-based generators. */
export interface ColorOptions {
  /** Colour saturation 0 (grey) → 1 (vivid). Default 1. */
  saturation?: number;
  /** Colour brightness 0 (black) → 1 (bright). Default 1. */
  value?: number;
}

/**
 * Convert an HSV colour to a `'#rrggbb'` hex string. `h` is a hue angle in
 * degrees (0/360 = red, 120 = green, 240 = blue; wraps). `s` and `v` are 0→1
 * and default to 1. The foundation of every other generator here.
 */
export function hsv(h: number, s: number = 1, v: number = 1): Hex {
  h = wrap360(h);
  s = clamp01(s);
  v = clamp01(v);
  const c = v * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = v - c;
  let r = 0, g = 0, b = 0;
  if (h < 60) { r = c; g = x; }
  else if (h < 120) { r = x; g = c; }
  else if (h < 180) { g = c; b = x; }
  else if (h < 240) { g = x; b = c; }
  else if (h < 300) { r = x; b = c; }
  else { r = c; b = x; }
  return `#${byte(r + m)}${byte(g + m)}${byte(b + m)}`;
}

function parseHex(hex: Hex): [number, number, number] {
  let s = hex.charAt(0) === '#' ? hex.slice(1) : hex;
  if (s.length === 3) s = s[0] + s[0] + s[1] + s[1] + s[2] + s[2];
  return [
    parseInt(s.slice(0, 2), 16) / 255,
    parseInt(s.slice(2, 4), 16) / 255,
    parseInt(s.slice(4, 6), 16) / 255,
  ];
}

function rgbToHsv(r: number, g: number, b: number): [number, number, number] {
  const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min;
  let h = 0;
  if (d !== 0) {
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h = wrap360(h * 60);
  }
  return [h, max === 0 ? 0 : d / max, max];
}

/**
 * Interpolate / blend two hex colours in RGB space. `t` = 0 returns `a`,
 * `t` = 1 returns `b`.
 */
export function lerp(a: Hex, b: Hex, t: number): Hex {
  t = clamp01(t);
  const [ar, ag, ab] = parseHex(a);
  const [br, bg, bb] = parseHex(b);
  return `#${byte(ar + (br - ar) * t)}${byte(ag + (bg - ag) * t)}${byte(ab + (bb - ab) * t)}`;
}

/**
 * Rotate a colour's hue by `degrees` around the HSV wheel, preserving its
 * saturation and brightness. `shift('#ff0000', 120)` turns red into green.
 */
export function shift(hex: Hex, degrees: number): Hex {
  const [r, g, b] = parseHex(hex);
  const [h, s, v] = rgbToHsv(r, g, b);
  return hsv(h + degrees, s, v);
}

/** A reusable HSV colour wheel sampled by hue angle or normalised position. */
export interface Wheel {
  readonly saturation: number;
  readonly value: number;
  /** Colour at a hue angle in degrees (wraps). */
  hue(degrees: number): Hex;
  /** Colour at normalised position `t` (0→1) around the full 360° wheel. */
  at(t: number): Hex;
  /** `count` evenly-spaced colours spanning `t0`→`t1` (0→1). Defaults to the full wheel. */
  colors(count: number, t0?: number, t1?: number): Hex[];
}

/**
 * Build a reusable colour wheel at a fixed saturation and value. Sample it
 * with `w.hue(210)`, `w.at(0.5)`, `w.colors(8)`.
 */
export function wheel(opts: ColorOptions = {}): Wheel {
  const s = opts.saturation ?? 1;
  const v = opts.value ?? 1;
  return {
    saturation: s,
    value: v,
    hue: (deg) => hsv(deg, s, v),
    at: (t) => hsv(t * 360, s, v),
    colors(count, t0 = 0, t1 = 1) {
      const out: Hex[] = [];
      for (let i = 0; i < count; i++) {
        const t = count <= 1 ? t0 : t0 + (t1 - t0) * (i / (count - 1));
        out.push(hsv(t * 360, s, v));
      }
      return out;
    },
  };
}

/**
 * `count` colours evenly spaced around the full HSV wheel. Loops seamlessly
 * (first and last are not duplicated).
 */
export function rainbow(count: number, opts: ColorOptions = {}): Hex[] {
  const s = opts.saturation ?? 1;
  const v = opts.value ?? 1;
  const out: Hex[] = [];
  for (let i = 0; i < count; i++) out.push(hsv((i / count) * 360, s, v));
  return out;
}

/**
 * A hue ramp — `count` colours stepping from `fromHue` to `toHue` (degrees),
 * both endpoints inclusive. A slice of the rainbow, close together.
 */
export function ramp(fromHue: number, toHue: number, count: number, opts: ColorOptions = {}): Hex[] {
  const s = opts.saturation ?? 1;
  const v = opts.value ?? 1;
  const out: Hex[] = [];
  for (let i = 0; i < count; i++) {
    const t = count <= 1 ? 0 : i / (count - 1);
    out.push(hsv(fromHue + (toHue - fromHue) * t, s, v));
  }
  return out;
}

/**
 * A gradient — `count` colours blending smoothly between two arbitrary hex
 * colours in RGB space, both endpoints inclusive.
 */
export function gradient(from: Hex, to: Hex, count: number): Hex[] {
  const out: Hex[] = [];
  for (let i = 0; i < count; i++) out.push(lerp(from, to, count <= 1 ? 0 : i / (count - 1)));
  return out;
}
