// THE BACKDROP SYSTEM — expandable full-screen background effects, drawn
// BEHIND the world (Rich's replacement for raster's Sky/Starfield: instead
// of porting two fixed classes, backgrounds are DATA we keep adding to).
//
// A BackdropDef is the third member of the effects-as-data family
// (post EffectDef, deformer DeformDef): {name, WGSL snippet, params,
// colors} spliced into a fixed fullscreen template. The engine ships a
// tiny CORE (sky, stars); everything else lives in BACKDROP_PACK or
// arrives as MCP blocks — agents request backdrops by name and NEVER
// write WGSL.
//
//   game.backdrop.add('sky', { curve: 1.4 });            // bottom layer
//   const stars = game.backdrop.add('stars');            // stacked over it
//   stars.set('twinkle', 2).setColor('tint', '#bcd');
//
// Backdrops stack in add order (premultiplied alpha), draw FIRST in the
// frame — inside the 3D pass when a world3d is active (behind the meshes,
// fogged world over them), else at the top of the scene pass — and are
// CAMERA-AWARE: the snippet sees the view origin, so stars can parallax.
//
// Snippet contract (fragment stage): write `color` (vec4f, straight
// alpha). In scope: `uv` (0..1 across the screen, y down), `px` (pixel
// coords), `time` (seconds), `view` (vec4f: world x, y, w, h — use xy for
// parallax), `c0`/`c1` (the def's two colour slots as vec4f), each named
// param as f32, `TAU`, and helpers `hash21(p)` / `noise2(p)` / `fbm2(p)`.
// The BACKGROUND IMAGE the backdrops render over (a game's title art, or
// the Foundry's checkerboard — set via game.backdrop.background) is in
// scope too: `bg` (vec4f at this pixel) and `bgAt(uv)` (sample elsewhere,
// e.g. displacement/warp). It reads transparent where no image is set, so
// a full-cover backdrop can simply ignore it; an overlay reads/blends it.
// Traps: no swizzle assignment; loops need uniform bounds.

import { BITS } from './gpu.js';
import { DEPTH_FORMAT } from './batch.js';
import { rgba } from './color.js';
import { effectDefaults, effectParamIndex, MAX_EFFECT_PARAMS } from './effects.js';
import { textureFromCanvas } from './atlas.js';

/** A backdrop as pure data — the MCP-block delivery shape. */
export interface BackdropDef {
  name: string;
  /** Scalar params (max 8) with defaults — retune live via handle.set(). */
  params?: Record<string, number>;
  /** Up to two named colour slots (declaration order → c0, c1). */
  colors?: Record<string, string>;
  /** The WGSL snippet — writes `color`. See the module header contract. */
  code: string;
  /** Optional GLSL ES 3.0 twin of `code` — same variable scope (`uv`, `px`,
   * `time`, `view`, `c0`/`c1`, named params, `TAU`, hash21/noise2/fbm2,
   * `bg`/`bgAt(p)`, result in `color`), spliced by the WebGL fallback. A def
   * without one is SKIPPED there (one console warn). */
  glsl?: string;
}

/** Pure WGSL assembly (headless-testable). */
export function buildBackdropWGSL(def: BackdropDef): string {
  const names = Object.keys(def.params ?? {});
  if (names.length > MAX_EFFECT_PARAMS) {
    throw new Error(`backdrop '${def.name}': max ${MAX_EFFECT_PARAMS} params`);
  }
  const lets = names
    .map((n, i) => `  let ${n} = u.${i < 4 ? 'p0' : 'p1'}.${'xyzw'[i % 4]};`)
    .join('\n');
  return /* wgsl */ `
const TAU = 6.28318530718;
struct U { res: vec4f, view: vec4f, p0: vec4f, p1: vec4f, c0: vec4f, c1: vec4f }
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var bgTex: texture_2d<f32>;
@group(0) @binding(2) var bgSamp: sampler;
struct VSOut { @builtin(position) pos: vec4f, @location(0) uv: vec2f }

@vertex
fn vs(@builtin(vertex_index) vi: u32) -> VSOut {
  var out: VSOut;
  let x = f32((vi << 1u) & 2u);
  let y = f32(vi & 2u);
  out.pos = vec4f(x * 2.0 - 1.0, 1.0 - y * 2.0, 0.0, 1.0);
  out.uv = vec2f(x, y);
  return out;
}

fn hash21(p: vec2f) -> f32 {
  var q = fract(p * vec2f(123.34, 456.21));
  q += dot(q, q + 45.32);
  return fract(q.x * q.y);
}

fn noise2(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let s = f * f * (3.0 - 2.0 * f);
  let a = hash21(i);
  let b = hash21(i + vec2f(1.0, 0.0));
  let c = hash21(i + vec2f(0.0, 1.0));
  let d = hash21(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, s.x), mix(c, d, s.x), s.y);
}

fn fbm2(p: vec2f) -> f32 {
  var v = 0.0;
  var amp = 0.5;
  var q = p;
  for (var i = 0u; i < 4u; i++) {
    v += noise2(q) * amp;
    q = q * 2.03 + vec2f(17.0, 9.0);
    amp *= 0.5;
  }
  return v;
}

// Sample the background image at a 0..1 coordinate (y DOWN, matching uv). Returns
// transparent black when no background is set (u.res.w is the has-background flag).
fn bgAt(p: vec2f) -> vec4f {
  if (u.res.w < 0.5) { return vec4f(0.0, 0.0, 0.0, 0.0); }
  return textureSampleLevel(bgTex, bgSamp, p, 0.0);
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let uv = in.uv;
  let px = uv * u.res.xy;
  let time = u.res.z;
  let view = u.view;
  let c0 = u.c0;
  let c1 = u.c1;
  let bg = bgAt(uv);
${lets}
  var color = vec4f(0.0, 0.0, 0.0, 1.0);
  {
${def.code}
  }
  return vec4f(color.rgb * color.a, color.a);   // premultiplied out
}
`;
}

// ── The engine CORE backdrops ────────────────────────────────────────────────
// Deliberately minimal (the blocks doctrine): sky + stars. Everything else is
// on-demand data — see BACKDROP_PACK below and, eventually, content-DB blocks.

export const BACKDROPS: Record<string, BackdropDef> = {
  /** Vertical two-colour gradient sky with a tunable curve. */
  sky: {
    name: 'sky',
    params: { curve: 1.0 },
    colors: { top: '#0b0e1a', bottom: '#2a3f6e' },
    code: /* wgsl */ `
    color = vec4f(mix(c0.rgb, c1.rgb, pow(clamp(uv.y, 0.0, 1.0), max(curve, 0.01))), 1.0);`,
  },

  /** Three-layer parallax starfield with twinkle — camera-aware (view.xy). */
  stars: {
    name: 'stars',
    params: { density: 1.0, twinkle: 1.0, drift: 0.0 },
    colors: { tint: '#ffffff' },
    code: /* wgsl */ `
    var acc = 0.0;
    for (var l = 0u; l < 3u; l++) {
      let fl = f32(l);
      let cell = 26.0 - fl * 7.0;                       // nearer layers: sparser, bigger
      let par = 0.15 + fl * 0.25;                       // nearer layers drift more
      let p = (px + view.xy * par + vec2f(time * drift * (fl + 1.0) * 8.0, 0.0)) / cell;
      let id = floor(p);
      let rnd = hash21(id + fl * 91.7);
      let keep = step(1.0 - 0.12 * density, rnd);       // a fraction of cells hold a star
      let centre = vec2f(hash21(id + 3.1), hash21(id + 7.7));
      let d = length(fract(p) - centre);
      let core = smoothstep(0.14 + 0.08 * fl, 0.0, d);
      // Twinkle needs its OWN hash: rnd survives the keep threshold, so it
      // only spans [1-0.12*density, 1] — phase and frequency derived from
      // it are nearly identical and EVERY star fades in unison (Rich:
      // "looks nuts"). Real stars mostly hold steady; a subset glints.
      let twr = hash21(id + 13.7 + fl * 5.3);
      let tw = 0.9 + 0.1 * sin(time * (0.4 + twr * 1.2) * twinkle + twr * TAU * 7.0);
      let glint = step(0.72, twr) * pow(max(sin(time * (0.5 + twr * 1.3) * twinkle + twr * 47.0), 0.0), 24.0) * 0.7;
      acc += keep * core * (tw + glint) * (0.45 + 0.55 * rnd);
    }
    color = vec4f(c0.rgb * acc, acc);`,
  },
};

// ── BACKDROP_PACK — on-demand data (the block-delivery shape) ────────────────

export const BACKDROP_PACK: Record<string, BackdropDef> = {
  /** Curtains of polar light waving across the upper sky. */
  aurora: {
    name: 'aurora',
    params: { amount: 1.0, speed: 1.0 },
    colors: { a: '#37ff9e', b: '#7a5cff' },
    code: /* wgsl */ `
    var acc = vec3f(0.0);
    for (var i = 0u; i < 3u; i++) {
      let fi = f32(i);
      let wave = sin(uv.x * (4.0 + fi * 2.3) + time * speed * (0.35 + fi * 0.2) + fi * 2.1)
               * (0.08 + 0.04 * fi);
      let band = 0.22 + fi * 0.15 + wave;
      let d = abs(uv.y - band);
      let glow = exp(-d * (26.0 - fi * 6.0)) * (0.8 - fi * 0.2);
      let sway = 0.5 + 0.5 * sin(uv.x * 3.0 - time * speed * 0.5 + fi);
      acc += mix(c0.rgb, c1.rgb, sway) * glow;
    }
    let a = clamp(acc.g * 1.4, 0.0, 1.0) * amount;
    color = vec4f(acc * amount, a);`,
  },

  /** Slow fbm nebula clouds between two tints — stack 'stars' over it. */
  nebula: {
    name: 'nebula',
    params: { scale: 3.0, speed: 0.02 },
    colors: { a: '#1a1440', b: '#8a3a6e' },
    code: /* wgsl */ `
    let p = uv * scale + view.xy * 0.0004 + vec2f(time * speed, 0.0);
    let n = fbm2(p);
    let m = fbm2(p * 1.8 + n * 2.2);
    let cloud = smoothstep(0.25, 0.85, n * 0.6 + m * 0.5);
    color = vec4f(mix(c0.rgb, c1.rgb, m) * cloud + c0.rgb * 0.25, 1.0);`,
  },

  /** Low sun over haze bands — a classic synth sunset. */
  sunset: {
    name: 'sunset',
    params: { sunY: 0.62, sunSize: 0.16 },
    colors: { sky: '#2a1445', sun: '#ff9a3d' },
    code: /* wgsl */ `
    let grad = mix(c0.rgb, c1.rgb * 0.55, pow(clamp(uv.y, 0.0, 1.0), 1.6));
    let ar = u.res.x / max(u.res.y, 1.0);
    let d = length(vec2f((uv.x - 0.5) * ar, uv.y - sunY));
    var sun = smoothstep(sunSize, sunSize * 0.92, d);
    // haze bands slice the lower half of the disc
    let band = step(0.5, fract(uv.y * 70.0 + time * 0.4)) * step(sunY, uv.y);
    sun *= 1.0 - band * 0.85;
    let halo = exp(-d * 5.0) * 0.35;
    color = vec4f(grad + c1.rgb * (sun + halo), 1.0);`,
  },
};

/**
 * Fullscreen blit that draws the background image (opaque) beneath the backdrop
 * layers, so overlay backdrops composite over the real pixels and read-effects can
 * also sample them via `bg` / `bgAt(uv)`.
 */
const BG_BLIT_WGSL = /* wgsl */ `
struct VSOut { @builtin(position) pos: vec4f, @location(0) uv: vec2f }
@group(0) @binding(0) var t: texture_2d<f32>;
@group(0) @binding(1) var s: sampler;
@vertex
fn vs(@builtin(vertex_index) vi: u32) -> VSOut {
  var o: VSOut;
  let x = f32((vi << 1u) & 2u);
  let y = f32(vi & 2u);
  o.pos = vec4f(x * 2.0 - 1.0, 1.0 - y * 2.0, 0.0, 1.0);
  o.uv = vec2f(x, y);
  return o;
}
@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  return vec4f(textureSampleLevel(t, s, in.uv, 0.0).rgb, 1.0);
}
`;

/** A live backdrop layer — retune (`set`/`setColor`) or `remove()` it. */
export class BackdropHandle {
  /** @internal */
  constructor(
    readonly def: BackdropDef,
    /** @internal */ public data: Float32Array,
    private chain: BackdropChain,
  ) {}

  /** Update a scalar parameter (by the name declared in the def). */
  set(param: string, value: number): this {
    const i = effectParamIndex(this.def, param);
    if (i >= 0) this.data[8 + i] = value; // after res + view
    return this;
  }

  /** Update a colour slot (by the name declared in the def). */
  setColor(name: string, hex: string): this {
    const i = Object.keys(this.def.colors ?? {}).indexOf(name);
    if (i >= 0) this.data.set(rgba(hex), 16 + i * 4);
    return this;
  }

  /** Remove this backdrop layer. */
  remove(): void {
    this.chain.drop(this);
  }
}

interface Layer {
  handle: BackdropHandle;
  uniforms: GPUBuffer;
  binds: Map<number, GPUBindGroup>; // per sampleCount
}

/** Anything that can become the backdrops' background image. */
export type BackgroundSource = GPUTexture | HTMLCanvasElement | OffscreenCanvas | HTMLImageElement | ImageBitmap;

/**
 * All active backdrop layers. Drawn first in the frame — into the 3D pass
 * when a world exists (behind the meshes), else into the scene pass —
 * with pipelines cached per (def, sampleCount). Device-loss rebuildable.
 */
export class BackdropChain {
  private layers: Layer[] = [];
  private pipelines = new Map<string, GPURenderPipeline>(); // `${name}@${samples}`
  private layout!: GPUBindGroupLayout;
  private device!: GPUDevice;

  // Background image the layers render OVER — a game's title art, a level photo, or
  // the Foundry's checkerboard. Shared by every layer; drawn beneath them and
  // sampleable in-snippet via `bg` / `bgAt(uv)`.
  private sampler!: GPUSampler;
  private defaultTex!: GPUTexture; // 1x1 transparent — keeps the binding valid with no bg
  private bgTex: GPUTexture | null = null;
  private hasBg = false;
  private bgLayout!: GPUBindGroupLayout;
  private bgPipelines = new Map<number, GPURenderPipeline>(); // per sampleCount
  private bgBind: GPUBindGroup | null = null;
  private bgBindTex: GPUTexture | null = null;

  constructor(device: GPUDevice, private format: GPUTextureFormat) {
    this.rebuild(device);
  }

  /**
   * Set (or clear, with null) the background image the backdrops render OVER. It is
   * drawn beneath the layers (so overlays composite over the real pixels) and is
   * sampleable inside a snippet via `bg` / `bgAt(uv)`. Accepts a GPUTexture or any
   * canvas / image / bitmap (uploaded to a texture).
   */
  setBackground(source: BackgroundSource | null): void {
    if (!source) {
      this.bgTex = null;
      this.hasBg = false;
    } else if (source instanceof GPUTexture) {
      this.bgTex = source;
      this.hasBg = true;
    } else {
      this.bgTex = textureFromCanvas(this.device, source);
      this.hasBg = true;
    }
    this.bgBind = null; // rebind the blit next draw
    for (const l of this.layers) l.binds.clear(); // rebind layers with the new texture
  }

  /** Anything to draw? (Game skips the frame + draw entirely when not.) True when
   *  there are layers, or a background image is set (drawn even with no layer over it). */
  get active(): boolean {
    return this.layers.length > 0 || this.hasBg;
  }

  /** Append a layer (built-in name or a custom BackdropDef — the block path). */
  add(backdrop: string | BackdropDef, params?: Record<string, number>): BackdropHandle {
    const def = typeof backdrop === 'string' ? BACKDROPS[backdrop] : backdrop;
    if (!def) throw new Error(`unknown backdrop '${String(backdrop)}' — built-ins: ${Object.keys(BACKDROPS).join(', ')}`);
    const data = new Float32Array(24); // res(4) view(4) p0(4) p1(4) c0(4) c1(4)
    data.set(effectDefaults(def), 8);
    const colors = Object.values(def.colors ?? {});
    data.set(rgba(colors[0] ?? '#ffffff'), 16);
    data.set(rgba(colors[1] ?? '#ffffff'), 20);
    const handle = new BackdropHandle(def, data, this);
    for (const [k, v] of Object.entries(params ?? {})) handle.set(k, v);
    this.layers.push({
      handle,
      uniforms: this.device.createBuffer({ size: data.byteLength, usage: BITS.UNIFORM | BITS.COPY_DST }),
      binds: new Map(),
    });
    return handle;
  }

  /** @internal */
  drop(handle: BackdropHandle): void {
    const i = this.layers.findIndex((l) => l.handle === handle);
    if (i >= 0) {
      this.layers[i].uniforms.destroy();
      this.layers.splice(i, 1);
    }
  }

  /** Remove every layer. */
  clear(): void {
    for (const l of this.layers) l.uniforms.destroy();
    this.layers = [];
  }

  /** @internal Per-frame uniform upload (before any pass begins). */
  frame(w: number, h: number, time: number, view: { x: number; y: number; w: number; h: number }): void {
    for (const l of this.layers) {
      const d = l.handle.data;
      d[0] = w; d[1] = h; d[2] = time; d[3] = this.hasBg ? 1 : 0;
      d[4] = view.x; d[5] = view.y; d[6] = view.w; d[7] = view.h;
      this.device.queue.writeBuffer(l.uniforms, 0, d);
    }
  }

  /** @internal The current background view (a 1x1 transparent default when unset). */
  private bgView(): GPUTextureView {
    return (this.bgTex ?? this.defaultTex).createView();
  }

  /** @internal Draw the background image (if any) then every layer, first thing in an open pass. */
  draw(pass: GPURenderPassEncoder, sampleCount: number): void {
    if (this.hasBg) {
      pass.setPipeline(this.bgPipelineFor(sampleCount));
      if (!this.bgBind || this.bgBindTex !== this.bgTex) {
        this.bgBind = this.device.createBindGroup({
          layout: this.bgLayout,
          entries: [
            { binding: 0, resource: this.bgView() },
            { binding: 1, resource: this.sampler },
          ],
        });
        this.bgBindTex = this.bgTex;
      }
      pass.setBindGroup(0, this.bgBind);
      pass.draw(3);
    }
    for (const l of this.layers) {
      pass.setPipeline(this.pipelineFor(l.handle.def, sampleCount));
      let bind = l.binds.get(sampleCount);
      if (!bind) {
        bind = this.device.createBindGroup({
          layout: this.layout,
          entries: [
            { binding: 0, resource: { buffer: l.uniforms } },
            { binding: 1, resource: this.bgView() },
            { binding: 2, resource: this.sampler },
          ],
        });
        l.binds.set(sampleCount, bind);
      }
      pass.setBindGroup(0, bind);
      pass.draw(3);
    }
  }

  /** (Re)create GPU objects — the device-loss recovery path. */
  rebuild(device: GPUDevice): void {
    this.device = device;
    this.pipelines.clear();
    this.bgPipelines.clear();
    this.bgBind = null;
    this.bgBindTex = null;
    this.layout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX | BITS.STAGE_FRAGMENT, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_FRAGMENT, texture: { sampleType: 'float' } },
        { binding: 2, visibility: BITS.STAGE_FRAGMENT, sampler: { type: 'filtering' } },
      ],
    });
    this.bgLayout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_FRAGMENT, texture: { sampleType: 'float' } },
        { binding: 1, visibility: BITS.STAGE_FRAGMENT, sampler: { type: 'filtering' } },
      ],
    });
    this.sampler = device.createSampler({
      magFilter: 'linear', minFilter: 'linear',
      addressModeU: 'clamp-to-edge', addressModeV: 'clamp-to-edge',
    });
    // 1x1 transparent default so the texture binding is always valid even with no bg.
    this.defaultTex = device.createTexture({
      size: { width: 1, height: 1 },
      format: 'rgba8unorm',
      usage: 0x4 /* TEXTURE_BINDING */ | 0x2 /* COPY_DST */,
    });
    device.queue.writeTexture(
      { texture: this.defaultTex },
      new Uint8Array([0, 0, 0, 0]),
      { bytesPerRow: 4, rowsPerImage: 1 },
      { width: 1, height: 1 },
    );
    // A device-loss rebuild drops any user-set background (it lived on the old device);
    // the consumer re-applies it via setBackground after recovery.
    this.bgTex = null;
    this.hasBg = false;
    this.layers = this.layers.map((l) => ({
      handle: l.handle,
      uniforms: device.createBuffer({ size: l.handle.data.byteLength, usage: BITS.UNIFORM | BITS.COPY_DST }),
      binds: new Map(),
    }));
  }

  private bgPipelineFor(sampleCount: number): GPURenderPipeline {
    let pipeline = this.bgPipelines.get(sampleCount);
    if (pipeline) return pipeline;
    const module = this.device.createShaderModule({ code: BG_BLIT_WGSL });
    pipeline = this.device.createRenderPipeline({
      layout: this.device.createPipelineLayout({ bindGroupLayouts: [this.bgLayout] }),
      vertex: { module, entryPoint: 'vs' },
      fragment: { module, entryPoint: 'fs', targets: [{ format: this.format }] }, // opaque base
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'always' },
      multisample: sampleCount > 1 ? { count: sampleCount } : undefined,
      primitive: { topology: 'triangle-list' },
    });
    this.bgPipelines.set(sampleCount, pipeline);
    return pipeline;
  }

  private pipelineFor(def: BackdropDef, sampleCount: number): GPURenderPipeline {
    const key = `${def.name}@${sampleCount}`;
    let pipeline = this.pipelines.get(key);
    if (pipeline) return pipeline;
    const module = this.device.createShaderModule({ code: buildBackdropWGSL(def) });
    void module.getCompilationInfo().then((info) => {
      for (const m of info.messages) {
        if (m.type === 'error') console.error(`backdrop '${def.name}' WGSL ${m.lineNum}:${m.linePos} ${m.message}`);
      }
    });
    pipeline = this.device.createRenderPipeline({
      layout: this.device.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: { module, entryPoint: 'vs' },
      fragment: {
        module,
        entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
            alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
          },
        }],
      },
      // Lives inside a depth-attached pass; paints behind everything.
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'always' },
      multisample: sampleCount > 1 ? { count: sampleCount } : undefined,
      primitive: { topology: 'triangle-list' },
    });
    this.pipelines.set(key, pipeline);
    return pipeline;
  }
}

/**
 * THE BACKDROP STACK — full-screen layers drawn BEHIND the world and
 * camera-aware (a starfield parallaxes with the view): `game.backdrop.add('stars')`,
 * `game.backdrop.clear()`, `game.backdrop.background(img)`. Built-ins by name
 * ('sky', 'stars', 'aurora', 'nebula', 'sunset') or a custom BackdropDef.
 *
 * Behind the world; `game.post` is the twin that draws OVER the finished frame.
 */
export class BackdropLayer {
  private readonly chain: () => BackdropChain;

  /** @internal Built by `Game` — reach it as `game.backdrop`, never construct one. */
  constructor(chain: () => BackdropChain) {
    this.chain = chain;
  }

  /**
   * Add a backdrop layer (layers stack in add order). Returns a handle:
   * `.set(param, v)` / `.setColor(name, hex)` to retune live, `.remove()` to drop.
   */
  add(backdrop: string | BackdropDef, params?: Record<string, number>): BackdropHandle {
    return this.chain().add(backdrop, params);
  }

  /** Remove every backdrop layer. */
  clear(): void {
    this.chain().clear();
  }

  /**
   * Set (or clear, with null) the BACKGROUND IMAGE the layers render OVER — a
   * game's title art, a level's photo, or (in the Foundry) a checkerboard. It is
   * drawn beneath the backdrop layers and is sampleable inside a snippet via the
   * pre-sampled `bg` (vec4f at the current pixel) or `bgAt(uv)` (sample elsewhere,
   * e.g. for displacement / warp). Accepts a GPUTexture or any canvas / image / bitmap.
   */
  background(source: BackgroundSource | null): void {
    this.chain().setBackground(source);
  }
}
