// The effect system's DATA layer — the block-extensibility keystone.
//
// An effect is a named WGSL SNIPPET + parameter defaults, spliced into a
// fixed full-screen template (the Pixi "shader-bit" model). Game code — and
// the game-building agent — never writes WGSL: it requests effects BY NAME
// with params (`game.post.add('crt', { curve: 0.2 })`). New effects arrive as
// EffectDef data (from the content DB / MCP blocks) through exactly the same
// call — no engine release needed. That is how the engine grows.
//
// Snippet contract: statements that may read `uv` (0..1), `time` (s),
// `texel` (1/resolution), the declared params by name, call `tex(uv)` to
// sample the source frame, and MUST leave the result in `color` (vec4f,
// premultiplied). WGSL note: swizzle assignment is illegal — write
// `color = vec4f(color.rgb * k, color.a)`, never `color.rgb *= k`.
//
// Pure string assembly — headlessly testable; post.ts owns the GPU side.

export interface EffectDef {
  name: string;
  /** WGSL statements (see contract above). */
  code: string;
  /** Ordered params → uniform slots (max 8), with defaults. */
  params?: Record<string, number>;
  /** Optional GLSL ES 3.0 twin of `code` — same variable scope (`uv`, `time`,
   * `texel`, `u.res`, named params, `tex(p)`, result in `color`), spliced by
   * the WebGL fallback. A def without one is SKIPPED there (one console
   * warn), so ship both dialects for effects that must degrade gracefully. */
  glsl?: string;
}

export const MAX_EFFECT_PARAMS = 8;

/** Splice an EffectDef into the full-screen post template → complete WGSL. */
export function buildEffectWGSL(def: EffectDef): string {
  const names = Object.keys(def.params ?? {});
  if (names.length > MAX_EFFECT_PARAMS) {
    throw new Error(`effect '${def.name}': max ${MAX_EFFECT_PARAMS} params`);
  }
  const lets = names
    .map((n, i) => `  let ${n} = u.${i < 4 ? 'p0' : 'p1'}.${'xyzw'[i % 4]};`)
    .join('\n');
  return /* wgsl */ `
struct U { res: vec4f, p0: vec4f, p1: vec4f }   // res: xy = size, z = time
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var samp: sampler;
@group(0) @binding(2) var src: texture_2d<f32>;
struct VSOut { @builtin(position) pos: vec4f, @location(0) uv: vec2f }

@vertex
fn vs(@builtin(vertex_index) vi: u32) -> VSOut {
  var out: VSOut;
  let x = f32((vi << 1u) & 2u);
  let y = f32(vi & 2u);
  out.pos = vec4f(x * 2.0 - 1.0, 1.0 - y * 2.0, 0.0, 1.0);
  out.uv = vec2f(x, y);
  return out;
}

fn tex(p: vec2f) -> vec4f {
  return textureSample(src, samp, clamp(p, vec2f(0.0), vec2f(1.0)));
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let uv = in.uv;
  let time = u.res.z;
  let texel = vec2f(1.0) / u.res.xy;
${lets}
  var color = tex(uv);
  {
${def.code}
  }
  return color;
}
`;
}

/** Ordered default values for an effect's uniform slots (p0.x … p1.w). */
export function effectDefaults(def: EffectDef): number[] {
  const out = new Array<number>(MAX_EFFECT_PARAMS).fill(0);
  Object.values(def.params ?? {}).forEach((v, i) => { out[i] = v; });
  return out;
}

/** Slot index of a named param (for PostHandle.set). -1 if unknown. */
export function effectParamIndex(def: EffectDef, name: string): number {
  return Object.keys(def.params ?? {}).indexOf(name);
}

// ── The engine CORE effects ──────────────────────────────────────────────────
// Deliberately minimal: pixelate (the pixelArt mechanism), bloom (the
// eye-candy staple) and vignette (cheap juice). EVERYTHING else is
// on-demand data — see EFFECT_PACK below and, eventually, content-DB blocks.

export const EFFECTS: Record<string, EffectDef> = {
  /** Chunky pixels: snap sampling to a screen-space grid. 5-tap weighted
   * (centre + 4 corners — the Phaser 4 recipe): blocks average their cell
   * instead of hard-picking one point, so edges inside a block soften. */
  pixelate: {
    name: 'pixelate',
    params: { size: 4 },
    code: /* wgsl */ `
    let px = max(1.0, size);
    let centre = px * floor(uv * u.res.xy / px) + px * 0.5;
    color = tex(centre / u.res.xy) * 0.4
      + tex((centre + px * vec2f(-0.5, -0.5)) / u.res.xy) * 0.15
      + tex((centre + px * vec2f( 0.5, -0.5)) / u.res.xy) * 0.15
      + tex((centre + px * vec2f( 0.5,  0.5)) / u.res.xy) * 0.15
      + tex((centre + px * vec2f(-0.5,  0.5)) / u.res.xy) * 0.15;`,
  },

  /** Darkened corners. */
  vignette: {
    name: 'vignette',
    params: { strength: 0.45 },
    code: /* wgsl */ `
    let c = uv * 2.0 - 1.0;
    color = vec4f(color.rgb * (1.0 - strength * dot(c, c) * 0.7), color.a);`,
  },

  /** One-pass bloom: bright areas leak light (glows, neon, magic). */
  bloom: {
    name: 'bloom',
    params: { threshold: 0.55, strength: 0.9, radius: 2.5 },
    code: /* wgsl */ `
    // Soft additive bloom: pixels above threshold bleed into a halo. Two
    // concentric rings of 8 taps (16 total), staggered per ring and GAUSSIAN-
    // weighted so the outer taps fade out. Dense + weighted means a small
    // bright orb spreads into a smooth glow instead of dropping a discrete
    // ghost copy at each tap (the old sparse 12-tap kernel did exactly that --
    // visible plus/box ghosts around tiny bright sources). The /wsum*2.0
    // normalisation preserves the old brightness on a uniform bright region
    // for any tap count, so ring count is a pure cost/spread knob.
    var glow = vec3f(0.0);
    var wsum = 0.0;
    for (var ring = 1u; ring <= 2u; ring++) {
      let rad = f32(ring) * radius * texel;
      let w = exp(-f32(ring * ring) * 0.28);
      for (var k = 0u; k < 8u; k++) {
        let ang = (f32(k) + f32(ring) * 0.5) * 0.7853982;   // 2pi/8, ring-staggered
        let s = tex(uv + vec2f(cos(ang), sin(ang)) * rad).rgb;
        glow += max(vec3f(0.0), s - vec3f(threshold)) * w;
        wsum += w;
      }
    }
    color = vec4f(color.rgb + glow / wsum * strength * 2.0, color.a);`,
  },
};

// ── The ON-DEMAND effect pack ────────────────────────────────────────────────
// NOT part of the core surface: these are EffectDef DATA, imported explicitly
// and passed to game.post.add(def) — exactly the delivery shape of a content-DB
// effect block. When v2 block publishing starts, this pack migrates there and
// the agent fetches effects by name via MCP instead of importing this module.

export const EFFECT_PACK: Record<string, EffectDef> = {
  /** CRT: barrel curvature + scanlines + vignette, black outside the tube. */
  crt: {
    name: 'crt',
    params: { curve: 0.12, scan: 0.25, vig: 0.35 },
    code: /* wgsl */ `
    let c = uv * 2.0 - 1.0;
    let r2 = dot(c, c);
    let cuv = (c * (1.0 + curve * r2) + 1.0) * 0.5;
    color = tex(cuv);
    let sl = 1.0 - scan * (0.5 + 0.5 * sin(cuv.y * u.res.y * 3.14159));
    var rgb = color.rgb * sl * (1.0 - vig * r2);
    let inside = step(0.0, cuv.x) * step(cuv.x, 1.0) * step(0.0, cuv.y) * step(cuv.y, 1.0);
    color = vec4f(rgb * inside, color.a);`,
  },

  /** Plain scanlines (no distortion). */
  scanlines: {
    name: 'scanlines',
    params: { strength: 0.3, size: 2 },
    code: /* wgsl */ `
    let row = floor(uv.y * u.res.y / max(1.0, size));
    let k = 1.0 - strength * f32(u32(row) % 2u);
    color = vec4f(color.rgb * k, color.a);`,
  },

  /** Quantize colours to N levels — poster / cel look. */
  posterize: {
    name: 'posterize',
    params: { levels: 5 },
    code: /* wgsl */ `
    let n = max(2.0, levels);
    color = vec4f(floor(color.rgb * n + vec3f(0.5)) / n, color.a);`,
  },

  /** Desaturate (amount 0..1). */
  grayscale: {
    name: 'grayscale',
    params: { amount: 1 },
    code: /* wgsl */ `
    let g = dot(color.rgb, vec3f(0.299, 0.587, 0.114));
    color = vec4f(mix(color.rgb, vec3f(g), clamp(amount, 0.0, 1.0)), color.a);`,
  },

  /** Underwater wobble. */
  wave: {
    name: 'wave',
    params: { amp: 0.004, freq: 18, speed: 2 },
    code: /* wgsl */ `
    let w = vec2f(sin(uv.y * freq + time * speed), cos(uv.x * freq * 0.8 + time * speed)) * amp;
    color = tex(uv + w);`,
  },

  /** Chromatic aberration — RGB fringing that grows toward the edges. */
  chroma: {
    name: 'chroma',
    params: { shift: 8 },
    code: /* wgsl */ `
    let off = uv - vec2f(0.5);
    let d = off * (0.5 + dot(off, off) * 3.0) * shift * texel;
    color = vec4f(tex(uv + d).r, color.g, tex(uv - d).b, color.a);`,
  },
};
