// THE VECTOR RENDERER (parity-plan Phase 2) — first-class line art. The
// vector-kit game family (asteroids, thrust, gravitar, cave-explorer…) drew
// Canvas strokes through d.line; THIS is a line ENGINE:
//
// - One instanced draw for MASSES of independent segments: each instance is
//   one segment (endpoints, width, a colour PER ENDPOINT for gradients,
//   glow, dash) expanded to a capsule quad in the vertex stage and
//   SDF-shaded in the fragment: a crisp AA core + an additive PHOSPHOR HALO
//   falloff — the vector-monitor look; scene bloom stacks on top.
// - Retained `VectorShape`: a set of segments under ONE per-shape transform
//   (a shape index per segment → a transform storage buffer), so asteroids
//   rotate and fly with ZERO CPU vertex rewrites — per frame only the tiny
//   transform table uploads. Static segment data re-packs only when shapes
//   are added/removed/edited (grow-only buffer, dirty-flagged).
// - `shape.shatter()`: the exploding-outline effect as one call — every
//   segment re-parents to its own fragment transform with a velocity away
//   from the centroid plus spin, fading out over `life`.
// - Deformable polylines: `shape.setPoints()` re-packs just that shape —
//   blow craters in a terrain by splicing vertices.
// - Immediate mode too: `seg()`/`poly()` push per-frame segments (HUD
//   sweeps, aim lines) through the same draw.
//
// Module load is DOM/GPU-free; the maths (segment packing, shatter
// kinematics, WGSL assembly) is pure and dist-tested.

import { BITS, shaderModule } from './gpu.js';
import { textOutline, type VecTextOptions } from './vecfont.js';
import { arcPoints, triangulate, isConvex } from './vecshapes.js';
import { DEPTH_FORMAT, Z_RANGE } from './batch.js';
import { rgba } from './color.js';
import * as colorKit from './colorkit.js';

export const LINE_FLOATS = 24;       // per segment instance (6 vec4s)
export const FILL_FLOATS = 8;        // per filled vertex: pos+z+slot | rgba
export const XFORM_FLOATS = 8;       // per transform slot (2 vec4s)

/** Assemble the line shader (pure string work — dist-tested). Two variants:
 * the SCENE shader draws crisp AA cores only, and the STAMP shader feeds the
 * shared GlowPass (soft tinted cores into the half-res blur target — glow as
 * a POST pass: in-shader halos couldn't join at polyline corners, a blurred
 * image of the finished lines joins perfectly, and the quads shrink to core
 * size). */
export function buildLineWGSL(stamp = false): string {
  return /* wgsl */ `
const STAMP = ${stamp};
struct U { view: vec4f }
// seg:   ax, ay, bx, by                  (shape-local endpoints)
// style: coreHalf, stampHalf, z, shapeIdx (world units; z 0..1) — stampHalf
//        is the glow-stamp half-width (the blurred halo's source thickness)
// extra: dash period, glow intensity, capped (width >= 1), dwell
// c0/c1: rgba at endpoint a / endpoint b (gradient along the line)
//
// JOINTS: adjacent segments in a chain are cut on the ANGLE BISECTOR
// they share, taking opposite sides of one plane, so they abut instead
// of overlapping. Each still contributes half of the round cap, so the
// join looks exactly as it did — but every pixel is painted ONCE, which
// is what lets a chain take an alpha. Overlapping caps blend twice and
// bead every corner (0.35 becomes 0.58); at alpha 1 that was invisible,
// because drawing a colour over itself changes nothing.
// Cutting each segment square across its OWN end is the obvious version
// and is wrong: two perpendicular cuts leave an uncovered wedge and
// notch every corner. One shared plane has no space between its sides.
// join.xy / join.zw are the inward normals; all zero = no cut (a lone
// segment, or the free end of an open chain).
// TWO EXCEPTIONS, both cut square instead. HAIRLINES: a width < 1 core
// is AA-limited (peak alpha below 1) so it beads anyway, and at that
// scale a square cut's notch is sub-pixel. And the GLOW STAMP, which is
// additive and saturates cleanly — corners burning brighter is the look,
// and what dwell exists to exaggerate.
struct Inst { seg: vec4f, style: vec4f, extra: vec4f, c0: vec4f, c1: vec4f, join: vec4f }
// Transform slot: x, y, rot, scale | alphaMul, glowMul, 0, 0. Slot 0 is
// the identity — immediate segments live there.
struct XF { pos: vec4f, mods: vec4f }
struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) local: vec2f,        // capsule space: along (world u), across
  @location(1) len: f32,
  @location(2) width: vec2f,        // coreHalf, haloW
  @location(3) c0: vec4f,
  @location(4) c1: vec4f,
  @location(5) extra: vec3f,        // dash, glow (already × glowMul), dwell
  @location(6) capped: f32,         // 1 = round caps; 0 = hairline flat cut
  @location(7) join: vec4f,         // cut planes at a / at b, in capsule space
}
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var<storage, read> inst: array<Inst>;
@group(0) @binding(2) var<storage, read> xf: array<XF>;

@vertex
fn vs(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VSOut {
  let d = inst[ii];
  let t = xf[u32(d.style.w)];
  // Shape transform: scale, rotate, translate the endpoints.
  let cr = cos(t.pos.z);
  let sr = sin(t.pos.z);
  let s = t.pos.w;
  let a = t.pos.xy + vec2f(
    (d.seg.x * cr - d.seg.y * sr) * s,
    (d.seg.x * sr + d.seg.y * cr) * s,
  );
  let b = t.pos.xy + vec2f(
    (d.seg.z * cr - d.seg.w * sr) * s,
    (d.seg.z * sr + d.seg.w * cr) * s,
  );
  let ab = b - a;
  let raw = length(ab);
  let len = max(1e-5, raw);
  // A ZERO-LENGTH segment is a DOT — seg(x, y, x, y). Without a fallback axis
  // its direction is 0/0, the quad collapses to a point and nothing rasterises
  // at all. Any axis will do: the capsule SDF around a zero-length segment is
  // a disc whichever way it faces.
  let dir = select(vec2f(1.0, 0.0), ab / len, raw > 1e-5);
  let n = vec2f(-dir.y, dir.x);
  // The quad covers the core (or the stamp width) + AA margin + round caps.
  // Dwell fattens the ends, so the quad has to reach far enough to contain it.
  let dwellGain = 1.0 + d.extra.w * 0.85;
  var reach = d.style.x * dwellGain + 2.0;
  if (STAMP) { reach = d.style.y * dwellGain + 2.0; }
  let c01 = vec2f(f32(vi & 1u), f32(vi >> 1u));
  let along = mix(-reach, len + reach, c01.x);
  let across = (c01.y - 0.5) * 2.0 * reach;
  let world = a + dir * along + n * across;
  let ndc = (world - u.view.xy) / u.view.zw * 2.0 - 1.0;
  var out: VSOut;
  out.pos = vec4f(ndc.x, -ndc.y, 1.0 - d.style.z, 1.0);
  out.local = vec2f(along, across);
  out.len = len;
  out.width = vec2f(d.style.x, d.style.y);
  out.c0 = vec4f(d.c0.rgb, d.c0.a * t.mods.x);
  out.c1 = vec4f(d.c1.rgb, d.c1.a * t.mods.x);
  out.extra = vec3f(d.extra.x, d.extra.y * t.mods.y, d.extra.w);
  out.capped = d.extra.z;
  // The cut planes turn with the shape, then drop into capsule space so the
  // fragment can test them with a dot product and nothing else.
  let ja = vec2f(d.join.x * cr - d.join.y * sr, d.join.x * sr + d.join.y * cr);
  let jb = vec2f(d.join.z * cr - d.join.w * sr, d.join.z * sr + d.join.w * cr);
  out.join = vec4f(dot(ja, dir), dot(ja, n), dot(jb, dir), dot(jb, n));
  return out;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  // Capsule SDF in local space: distance to the segment [0, len] on the axis.
  let q = vec2f(in.local.x - clamp(in.local.x, 0.0, in.len), in.local.y);
  let d = length(q);
  let aa = max(fwidth(d), 1e-4);
  // Hairline mode (scene only): cut flat at the endpoints — see the JOINTS
  // note above. The glow stamp keeps its soft caps (MAX blend absorbs them).
  // A dot has no ends to cut square, so the hairline rule must not erase it.
  if (!STAMP && in.capped < 0.5 && in.len > 1e-4 && (in.local.x < 0.0 || in.local.x > in.len)) {
    discard;
  }
  // Cut on the joins — see the JOINTS note above. A zero normal dots to 0 and
  // so never discards, which is how a free end keeps its round cap.
  // Cut on the joins — see the JOINTS note above. FADED, not discarded: the
  // two sides of a joint compute their distance to the same plane through
  // different bases, so near it they disagree in the last bits. A hard test
  // then either keeps a fragment twice (a bright hairline along the diagonal
  // of an axis-aligned corner, where a whole row of pixel centres lands
  // exactly on zero) or drops it twice (a dark notch). Both were seen, one per
  // backend, from the same code. Fading over a pixel makes the two sides sum
  // to one across the seam whichever way the bits fall, and antialiases the
  // cut into the bargain. The residual is second order — at alpha a the worst
  // error is a²/4, invisible in a one-pixel band.
  // The distances and their screen derivatives are computed UNCONDITIONALLY:
  // fwidth reads neighbouring fragments, so WGSL requires uniform control flow
  // and rejects the shader outright if it sits inside an if.
  let ja = in.join.xy;
  let jb = in.join.zw;
  let da = in.local.x * ja.x + in.local.y * ja.y;
  let db = (in.local.x - in.len) * jb.x + in.local.y * jb.y;
  let wa = max(fwidth(da), 1e-4);
  let wb = max(fwidth(db), 1e-4);
  var jcut = 1.0;
  if (!STAMP && in.capped >= 0.5) {
    if (dot(ja, ja) > 0.0) { jcut *= smoothstep(-0.5, 0.5, da / wa); }
    if (dot(jb, jb) > 0.0) { jcut *= smoothstep(-0.5, 0.5, db / wb); }
    if (jcut <= 0.0) { discard; }
  }
  let tt = clamp(in.local.x / in.len, 0.0, 1.0);
  var col = mix(in.c0, in.c1, tt);
  // Dash: a smooth on/off gate along the axis (period in world units, half
  // duty).
  var gate = 1.0;
  if (in.extra.x > 0.0) {
    let ph = fract(in.local.x / in.extra.x);
    let waa = aa / in.extra.x;
    gate = 1.0 - smoothstep(0.5 - waa, 0.5 + waa, abs(ph - 0.5) * 2.0);
  }
  // BEAM DWELL. A real display's beam decelerates at the end of a stroke, so
  // more electrons land there and the spot burns brighter and fatter. How much
  // it decelerates depends on HOW SHARPLY IT TURNS: a shallow bend in a
  // polyline barely slows the beam, a hairpin nearly stops it, and the end of
  // a stroke stops it dead. So the boost is scaled per end by sin(half the
  // turn) — 0 straight through, 1 doubled back — which the join bisector
  // already carries: it is a unit vector in capsule space, so its component
  // along the axis IS cos(half the turn). A FREE end has no bisector (a zero
  // normal) and is a real terminus, so it keeps the full boost.
  // With both gains at 1 this is exactly the old single-k behaviour.
  let dwellW = in.width.x * 2.0 + 4.0;
  let kA = 1.0 - smoothstep(0.0, dwellW, max(in.local.x, 0.0));
  let kB = 1.0 - smoothstep(0.0, dwellW, max(in.len - in.local.x, 0.0));
  let sA = select(1.0, sqrt(max(0.0, 1.0 - in.join.x * in.join.x)), dot(in.join.xy, in.join.xy) > 0.0);
  let sB = select(1.0, sqrt(max(0.0, 1.0 - in.join.z * in.join.z)), dot(in.join.zw, in.join.zw) > 0.0);
  let k = max(kA * sA, kB * sB);
  let boost = 1.0 + in.extra.z * 0.85 * k;
  if (STAMP) {
    // The glow-pass stamp: a SOFT tinted core (triangle falloff to the
    // stamp width), brightness = glow × the shape's live glowMul. The
    // shared half-res gaussian blur turns this into the phosphor halo —
    // and because it blurs the FINISHED line image, joints join perfectly
    // (the in-shader halo could not: hard joint cuts left notched wedges
    // at every corner — Rich's screenshot).
    let soft = (1.0 - smoothstep(0.0, max(in.width.y * boost, 1e-4), d)) * gate;
    let g = soft * col.a * in.extra.y * (1.0 + in.extra.z * 1.2 * k);
    return vec4f(col.rgb * g, g);              // additive-summed in the target
  }
  // The scene line: a crisp AA core, nothing else — glow 0 IS this look.
  let cw = in.width.x * boost;
  let core = (1.0 - smoothstep(cw - aa, cw + aa, d)) * gate * jcut;
  let aCore = core * col.a;
  return vec4f(col.rgb * aCore, aCore);        // premultiplied out
}
`;
}

/**
 * The FILL shader — solid faces under the line art.
 *
 * A triangulated outline, one vertex at a time: local position, the shape's
 * transform slot, a depth, and a colour PER VERTEX (which is what gives the
 * gradient — no extra uniform, no second pass). It shares the same `xf`
 * transform table as the lines, so a filled shape moves for the same 8 floats.
 *
 * Depth is the point of it. The fill pass WRITES depth where the line pass
 * only tests it, so a nearer filled shape hides both the fills and the lines
 * behind it — corridors, Elite hulls, a Tempest web with solid lanes.
 */
export function buildFillWGSL(): string {
  return /* wgsl */ `
struct U { view: vec4f }
// v: x, y (shape-local), z (0..1 depth), shapeIdx
struct Vtx { v: vec4f, color: vec4f }
struct XF { pos: vec4f, mods: vec4f }
struct VSOut { @builtin(position) pos: vec4f, @location(0) color: vec4f }
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var<storage, read> verts: array<Vtx>;
@group(0) @binding(2) var<storage, read> xf: array<XF>;

@vertex
fn vs(@builtin(vertex_index) vi: u32) -> VSOut {
  let d = verts[vi];
  let t = xf[u32(d.v.w)];
  let cr = cos(t.pos.z);
  let sr = sin(t.pos.z);
  let s = t.pos.w;
  let world = t.pos.xy + vec2f(
    (d.v.x * cr - d.v.y * sr) * s,
    (d.v.x * sr + d.v.y * cr) * s,
  );
  let ndc = (world - u.view.xy) / u.view.zw * 2.0 - 1.0;
  var out: VSOut;
  out.pos = vec4f(ndc.x, -ndc.y, 1.0 - d.v.z, 1.0);
  // The shape's live alpha multiplies the fill, so fading a shape fades both
  // its face and its outline together.
  out.color = vec4f(d.color.rgb, d.color.a * t.mods.x);
  return out;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  return vec4f(in.color.rgb * in.color.a, in.color.a);   // premultiplied
}
`;
}

// ---------------------------------------------------------------------------
// Pure maths — dist-tested.

export interface VecPt { x: number; y: number }

/** A clip rectangle in WORLD units. */
export interface VecClipRect { x: number; y: number; w: number; h: number }

/**
 * World clip rect → an integer pixel scissor on a `pxW × pxH` target, given the
 * view rect the layer was begun with. `null` = nothing of the rect is on the
 * target, so the whole draw can be skipped.
 *
 * Pure so both backends share it AND so the half-res glow target gets the same
 * arithmetic — a halo clipped to a different rectangle than its line is the
 * bug this exists to prevent.
 */
export function clipToScissor(
  clip: VecClipRect, viewX: number, viewY: number, viewW: number, viewH: number,
  pxW: number, pxH: number,
): { x: number; y: number; w: number; h: number } | null {
  if (viewW <= 0 || viewH <= 0 || pxW <= 0 || pxH <= 0) return null;
  const sx = pxW / viewW, sy = pxH / viewH;
  const clampX = (v: number): number => Math.max(0, Math.min(pxW, Math.round(v)));
  const clampY = (v: number): number => Math.max(0, Math.min(pxH, Math.round(v)));
  const x0 = clampX((clip.x - viewX) * sx);
  const x1 = clampX((clip.x + clip.w - viewX) * sx);
  const y0 = clampY((clip.y - viewY) * sy);
  const y1 = clampY((clip.y + clip.h - viewY) * sy);
  if (x1 <= x0 || y1 <= y0) return null;
  return { x: x0, y: y0, w: x1 - x0, h: y1 - y0 };
}

/** Expand a polyline into segment endpoint pairs (closed joins last→first). */
export function polySegs(points: readonly VecPt[], closed = false): Array<[VecPt, VecPt]> {
  const out: Array<[VecPt, VecPt]> = [];
  for (let i = 1; i < points.length; i++) out.push([points[i - 1], points[i]]);
  if (closed && points.length > 2) out.push([points[points.length - 1], points[0]]);
  return out;
}

/**
 * Where each segment of a chain should stop, so neighbours ABUT instead of
 * overlapping — four floats per segment, matching `polySegs` order.
 *
 * Each segment end carries the inward normal of the plane it is cut on: the
 * two segments meeting at a joint share one plane, the ANGLE BISECTOR, and
 * take opposite sides of it. Between them they still tile the whole join —
 * each contributes half of the round cap — so the picture is unchanged while
 * every pixel is painted exactly once.
 *
 * That is the difference between this and cutting each segment square across
 * its own end, which is the obvious thing to try and notches every corner: two
 * perpendicular cuts leave an uncovered wedge between them, whereas one shared
 * plane has no space between its two sides.
 *
 * Painting once is what makes ALPHA work on an outline. Overlapping caps blend
 * twice, so at `alpha` 0.35 a joint reaches 1 − 0.65² = 0.58 while the rest of
 * the line sits at 0.35, and every corner beads. Fully opaque lines never
 * showed it, because drawing the same colour over itself changes nothing.
 *
 * A free end — either end of an open chain — gets a zero normal, which the
 * shader reads as "no cut" and leaves as a round cap.
 */
export function chainJoins(points: readonly VecPt[], closed = false): Float32Array {
  return segJoins(polySegs(points, closed));
}

/**
 * `chainJoins` for a list of segments rather than a path — the emitter's
 * particle outlines arrive already cut into pairs.
 *
 * Two segments are joined when one ends where the next begins, which is the
 * only thing that actually matters and needs no separate `closed` flag: a loop
 * is simply a list whose last segment lands back on the first.
 */
export function segJoins(segs: ReadonlyArray<readonly [VecPt, VecPt]>): Float32Array {
  const n = segs.length;
  const out = new Float32Array(n * 4);
  if (n < 2) return out;
  const dirs = segs.map(([a, b]) => {
    const dx = b.x - a.x, dy = b.y - a.y;
    const l = Math.hypot(dx, dy);
    return l > 1e-9 ? { x: dx / l, y: dy / l } : { x: 0, y: 0 };
  });
  const meets = (i: number, j: number): boolean =>
    Math.abs(segs[i][1].x - segs[j][0].x) < 1e-6 && Math.abs(segs[i][1].y - segs[j][0].y) < 1e-6;
  for (let i = 0; i < n; i++) {
    const prev = (i - 1 + n) % n;
    if (!meets(prev, i)) continue;                      // a free end: round cap
    const a = dirs[prev], b = dirs[i];
    let mx = a.x + b.x, my = a.y + b.y;
    const l = Math.hypot(mx, my);
    // A chain that doubles clean back on itself has no bisector — cut square
    // across instead, which is the limit of the bisector as the angle closes.
    if (l < 1e-6) { mx = b.x; my = b.y; } else { mx /= l; my /= l; }
    out[prev * 4 + 2] = -mx; out[prev * 4 + 3] = -my;   // the one ending here
    out[i * 4] = mx; out[i * 4 + 1] = my;               // the one starting
  }
  return out;
}



// ---------------------------------------------------------------------------
// The VECTOR EMITTER — particles made of line art.
//
// A sprite particle is a textured quad; a vector particle is a tiny OUTLINE
// that flies, spins, fades and glows with the rest of the layer. It costs the
// same as any other segments: it packs into the same buffers, rides the same
// transform slot, and feeds the same glow stamp, so a burst of glowing shards
// needs nothing new on the GPU side at all.
//
// Everything here is pure — the two backends share it verbatim.


/**
 * A COLOUR PER PARTICLE, rather than one colour for the whole burst.
 *
 * The emitter hands each particle the next index from a running counter, so a
 * stream keeps walking the source across frames instead of restarting every
 * call — that is what makes a thruster cycle the spectrum smoothly rather than
 * strobing one hue per frame.
 *
 * - `'rainbow'` — the full hue wheel
 * - `{ hue: [from, to], step?, sat?, val? }` — an arc of it (`[200, 320]` for
 *   an ice plume, `[0, 60]` for flame)
 * - `{ from, to }` — walk between two literal colours
 * - `string[]` — cycle an explicit palette
 * - `(i) => string` — anything else; `i` is the particle's index in the run
 *
 * `step` is DEGREES PER PARTICLE and defaults to 1, so a burst of `count`
 * spans `count × step` degrees. Raise it to fan a single burst across the
 * wheel; leave it at 1 for a stream that cycles gradually.
 */
export type VecColorSource =
  | 'rainbow'
  | (string & {})
  | readonly string[]
  | ((i: number) => string)
  | { hue: readonly [number, number]; step?: number; sat?: number; val?: number }
  | { from: string; to: string; step?: number };

/** @internal A packed style recoloured — everything else (width, glow, dash,
 *  z) is preserved, so a per-particle colour costs one object, not a re-pack. */
export function tintStyle(base: PackedStyle, color: string): PackedStyle {
  const c = rgba(color) as unknown as [number, number, number, number];
  return { ...base, c0: c, c1: c };
}

/**
 * One packed style per segment, or null when the chain is uniform.
 *
 * This is what makes colour work on CHAINS, and it covers both ways of asking:
 *
 * - `colors` — a SOURCE stepped once per segment (rainbow polygons, hue-graded
 *   terrain). Per index, because that is what a source means.
 * - `color2` — a GRADIENT from `color`, run once along the WHOLE run by ARC
 *   LENGTH. A single instanced segment can only ramp end to end, so without
 *   this the whole from→to repeats inside every segment and a polyline comes
 *   out banded, one full ramp per edge. Measuring by length rather than by
 *   segment index matters as soon as the edges differ: a long edge would
 *   otherwise sweep the same amount of colour as a short one and the ramp
 *   would visibly stall and rush.
 *
 * On a CLOSED outline the ramp runs the whole way round and meets itself at the
 * first point, so `color` and `color2` sit next to each other there — the seam
 * any linear gradient on a loop has. Pick close colours, or leave it open.
 */
export function segmentStyles(
  raw: LineStyle, segs: ReadonlyArray<readonly [VecPt, VecPt]>,
): PackedStyle[] | null {
  const n = segs.length;
  if (n <= 0) return null;
  const base = packStyle(raw);
  if (raw.colors !== undefined) {
    const out: PackedStyle[] = new Array(n);
    // A RAMP source (rainbow, a hue arc, a two-colour walk) is continuous in
    // its index, so it should advance with DISTANCE along the chain: on an
    // uneven run — terrain, an arc with mixed step sizes — a per-index walk
    // gives a long edge and a short one the same slice of the ramp, and the
    // colour visibly stalls then rushes. An ARRAY or a FUNCTION is discrete and
    // per-segment by intent (`i % 2` for alternating stripes), so those keep
    // the integer index.
    const ramp = rampSource(raw.colors);
    const at = ramp ? arcIndex(segs) : null;
    for (let i = 0; i < n; i++) {
      out[i] = tintStyle(base, resolveVecColor(raw.colors, at ? at[i] : i));
    }
    return out;
  }
  // One segment already ramps end to end on its own — packStyle has it covered.
  if (raw.color2 === undefined || n < 2) return null;

  const cum = new Array<number>(n + 1);
  cum[0] = 0;
  for (let i = 0; i < n; i++) {
    const [a, b] = segs[i];
    cum[i + 1] = cum[i] + Math.hypot(b.x - a.x, b.y - a.y);
  }
  const total = cum[n];
  const at = (i: number): number => (total > 1e-9 ? cum[i] / total : i / n);

  const from = raw.color ?? '#ffffff';
  const to = raw.color2;
  const alpha = raw.alpha ?? 1;
  const ramp = (t: number): [number, number, number, number] => {
    const c = rgba(colorKit.lerp(from, to, t)) as unknown as [number, number, number, number];
    return [c[0], c[1], c[2], c[3] * alpha];
  };
  const out: PackedStyle[] = new Array(n);
  for (let i = 0; i < n; i++) out[i] = { ...base, c0: ramp(at(i)), c1: ramp(at(i + 1)) };
  return out;
}

/** Is this source a continuous RAMP (safe to index fractionally), rather than a
 *  discrete per-segment list or callback? */
function rampSource(src: VecColorSource): boolean {
  if (typeof src === 'function' || Array.isArray(src)) return false;
  if (typeof src === 'string') return src === 'rainbow';
  return true;                                    // { hue } or { from, to }
}

/** Each segment's position along the chain, expressed on the same 0..n scale
 *  the index uses — so `step` keeps meaning what it meant, and a chain of equal
 *  segments resolves to exactly 0, 1, 2 … as it always did. */
function arcIndex(segs: ReadonlyArray<readonly [VecPt, VecPt]>): number[] {
  const n = segs.length;
  const out: number[] = new Array(n);
  let total = 0;
  for (let i = 0; i < n; i++) {
    out[i] = total;
    total += Math.hypot(segs[i][1].x - segs[i][0].x, segs[i][1].y - segs[i][0].y);
  }
  if (total < 1e-9) return out.map((_, i) => i);
  for (let i = 0; i < n; i++) out[i] = (out[i] / total) * n;
  return out;
}

/**
 * The translation that realises a shape's `pivot` — where the shape is actually
 * drawn, which is what you want for framing a camera on it or hanging something
 * off it.
 *
 * The shader only knows `world = rotate(scale(local)) + T`, with no pivot in
 * it. Turning about an arbitrary point is the same transform with a different
 * T, so the whole feature lives here and costs nothing per vertex:
 *
 *   world(p) = R·S·(p − pivot) + pivot + xy  =  R·S·p + (xy + pivot − R·S·pivot)
 *
 * The pivot itself therefore lands at exactly `(x + pivot.x, y + pivot.y)`,
 * which is the point a shatter should burst from.
 */
export function shapeOrigin(s: {
  x: number; y: number; rot: number; scale: number; pivot: VecPt | null;
}): VecPt {
  const p = s.pivot;
  if (!p) return { x: s.x, y: s.y };
  const c = Math.cos(s.rot) * s.scale, n = Math.sin(s.rot) * s.scale;
  return {
    x: s.x + p.x - (p.x * c - p.y * n),
    y: s.y + p.y - (p.x * n + p.y * c),
  };
}

/** Resolve a colour source for particle `i`. Pure — shared by both backends. */
export function resolveVecColor(src: VecColorSource, i: number): string {
  if (typeof src === 'function') return src(i);
  if (typeof src === 'string') {
    return src === 'rainbow' ? colorKit.hsv(i % 360) : src;
  }
  if (Array.isArray(src)) {
    const a = src as readonly string[];
    return a.length ? a[i % a.length] : '#ffffff';
  }
  const o = src as { hue?: readonly [number, number]; from?: string; to?: string; step?: number; sat?: number; val?: number };
  const step = o.step ?? 1;
  if (o.hue) {
    const [lo, hi] = o.hue;
    const span = hi - lo;
    // A wrapping arc: walk it and fold back, so it cycles rather than clamping.
    const t = span === 0 ? 0 : ((i * step) % Math.abs(span)) / Math.abs(span);
    return colorKit.hsv(lo + span * t, o.sat ?? 1, o.val ?? 1);
  }
  // Two literal colours: ping-pong between them so the run never jumps.
  const period = Math.max(1, Math.round(360 / Math.max(1e-6, step)));
  const p = (i % period) / period;
  return colorKit.lerp(o.from ?? '#ffffff', o.to ?? '#ffffff', p < 0.5 ? p * 2 : (1 - p) * 2);
}

/** The outline a vector particle is cut from. */
export type VecShapeKind = 'line' | 'triangle' | 'square' | 'diamond' | 'circle' | 'cross' | 'star';

/** Outline for one particle kind, centred on the origin at RADIUS 1. */
export function particleOutline(kind: VecShapeKind, circleSides = 10): Array<[VecPt, VecPt]> {
  const ring = (n: number, turn = 0, r = 1): VecPt[] =>
    Array.from({ length: n }, (_, i) => {
      const a = turn + (i / n) * Math.PI * 2;
      return { x: Math.cos(a) * r, y: Math.sin(a) * r };
    });
  switch (kind) {
    case 'line':     return [[{ x: -1, y: 0 }, { x: 1, y: 0 }]];
    case 'triangle': return polySegs(ring(3, -Math.PI / 2), true);
    case 'square':   return polySegs(ring(4, Math.PI / 4), true);
    case 'diamond':  return polySegs(ring(4), true);
    case 'cross':    return [
      [{ x: -1, y: 0 }, { x: 1, y: 0 }],
      [{ x: 0, y: -1 }, { x: 0, y: 1 }],
    ];
    case 'star': {
      const out: Array<[VecPt, VecPt]> = [];
      const outer = ring(5, -Math.PI / 2);
      const inner = ring(5, -Math.PI / 2 + Math.PI / 5, 0.42);
      for (let i = 0; i < 5; i++) {
        out.push([outer[i], inner[i]]);
        out.push([inner[i], outer[(i + 1) % 5]]);
      }
      return out;
    }
    case 'circle':
    default:         return polySegs(ring(Math.max(3, circleSides)), true);
  }
}

/** A burst of vector particles. Everything is optional except x/y. */
export interface VecEmitOptions {
  x: number; y: number;
  /** Particles in the burst (default 12). */
  count?: number;
  /** Outline to cut them from — one kind, or an array to mix per particle. */
  shape?: VecShapeKind | VecShapeKind[];
  /** Radius in world units (default 6) ± `sizeVar` (default 2). */
  size?: number; sizeVar?: number;
  /** Initial speed (default 90) ± `speedVar` (default 40). */
  speed?: number; speedVar?: number;
  /** Direction in radians (default 0) ± `spread`/2 (default a full circle). */
  angle?: number; spread?: number;
  /** Space the angles EVENLY across the spread — a clean ring or fan. */
  even?: boolean;
  /** Jitter the spawn point within this radius (default 0). */
  spawnRadius?: number;
  /** Random spin up to ±spin rad/s (default 3). */
  spin?: number;
  /** Seconds (default 1.2) ± `lifeVar` (default 0.4). */
  life?: number; lifeVar?: number;
  /** Velocity damping per second (default 0.4). */
  drag?: number;
  /** Downward acceleration (default 0); negative rises. */
  gravity?: number;
  /** Final size as a fraction of the start (default 1 = no change; 0 shrinks
   *  away, >1 grows — expanding shockwave rings are `shrink: 3`). */
  shrink?: number;
  /** Line look: `color`, `width`, `glow` — the same style shapes take. */
  style?: LineStyle;
  /**
   * A colour PER PARTICLE, overriding `style.color`. Rainbow plumes, flame
   * ramps and two-colour gradients without hard-coding a palette:
   *
   * ```ts
   * colors: 'rainbow'                       // the whole wheel
   * colors: { hue: [0, 60], step: 4 }       // flame: red → orange → yellow
   * colors: { from: '#41d6ff', to: '#ff5fa2' }
   * colors: (i) => i % 2 ? '#fff' : '#0ff'
   * ```
   */
  colors?: VecColorSource;
  /** Segments per circle (default 10). Fewer = chunkier, cheaper. */
  circleSides?: number;
}

/** One shatter fragment's kinematic state (pure step: stepFragment). */
export interface VecFragment {
  /** Fragment transform (world). */
  x: number; y: number; rot: number; scale: number;
  vx: number; vy: number; spin: number;
  age: number; life: number;
}

/** Spawn kinematics for one shattered segment. The fragment transform sits
 * ON the segment's world MIDPOINT (x, y) — so its spin turns the piece
 * about its own centre, never orbiting the shape origin — and flies along
 * the outward unit direction (dirX, dirY) with jitter + spin from `rand`. */
export function spawnFragment(
  x: number, y: number, dirX: number, dirY: number,
  opts: { speed?: number; spin?: number; life?: number }, rand: () => number,
): VecFragment {
  const speed = opts.speed ?? 60;
  const jitter = 0.6 + rand() * 0.8;
  return {
    x, y, rot: 0, scale: 1,
    vx: dirX * speed * jitter + (rand() - 0.5) * speed * 0.3,
    vy: dirY * speed * jitter + (rand() - 0.5) * speed * 0.3,
    spin: (rand() - 0.5) * 2 * (opts.spin ?? 3),
    age: 0, life: Math.max(0.05, (opts.life ?? 1.2) * (0.7 + rand() * 0.6)),
  };
}

/** Advance one fragment; returns false once expired. Pure — dist-tested. */
export function stepFragment(f: VecFragment, dt: number, drag = 0.4): boolean {
  f.age += dt;
  if (f.age >= f.life) return false;
  const damp = Math.max(0, 1 - drag * dt);
  f.vx *= damp;
  f.vy *= damp;
  f.x += f.vx * dt;
  f.y += f.vy * dt;
  f.rot += f.spin * dt;
  return true;
}

/** Fragment alpha over age: hold, then fade the last 40%. */
export function fragmentAlpha(age: number, life: number): number {
  const t = Math.min(1, age / Math.max(1e-5, life));
  return t < 0.6 ? 1 : 1 - (t - 0.6) / 0.4;
}

// ---------------------------------------------------------------------------
// TRAILS — the ribbon a moving thing leaves behind.
//
// This is the replacement for full-screen phosphor feedback, and it is better
// on every axis that matters. Feedback smeared the WHOLE image: a stationary
// ship accumulated its own halo every frame until it was a bright blob, and
// the effect could not be aimed at one object or tuned per object. A trail is
// geometry — it belongs to the thing that made it, it tapers and grades along
// its length, and something standing still leaves nothing at all.

/** One star. Mutate these directly — the field re-reads them every frame, so
 *  anything the built-in motion does not cover, you can just do yourself. */
export interface VecStar {
  /** DRIFT: world position. WARP: lateral offset from the tunnel axis, before
   *  projection — screen position is derived, not stored. */
  x: number;
  y: number;
  /** DRIFT: which layer, normalised — 0 (nearest, full speed) to 1 (farthest).
   *  WARP: distance down the tunnel, `near`..`far`. */
  z: number;
}

/** `'drift'` scrolls a flat field in any direction; `'warp'` flies INTO the
 *  screen (or out of it, at negative speed). */
export type VecStarMode = 'drift' | 'warp';

/** Tuning for `layer.starfield()`. Every field is also a live property on the
 *  returned object — change any of them, any frame. */
export interface VecStarfieldOptions {
  /** How many stars (default 240). */
  count?: number;
  /** `'drift'` (default) or `'warp'`. */
  mode?: VecStarMode;
  /** The rectangle the field lives in. Default: the layer's current view, so
   *  it follows a resize on its own. */
  bounds?: VecClipRect;
  /**
   * DRIFT: world units per second for the NEAREST layer. WARP: units of depth
   * per second toward the camera. **Negative reverses it** — a drift field
   * scrolls the other way, a warp field flies backwards out of the screen.
   */
  speed?: number;
  /** DRIFT: direction of travel in radians (default 0 = right, +y is down).
   *  Turn it live and the whole field banks. */
  angle?: number;
  /**
   * DRIFT: how many parallax LAYERS, each slower, smaller and dimmer than the
   * one in front (default 4). `0` or `1` is a flat field with no parallax.
   *
   * `count` is shared out across them automatically and the depth spacing is
   * worked out from the layer count, so this is the only knob: ask for 4 and
   * you get four clearly separated sheets of sky. Set it any time and the
   * field re-layers itself.
   */
  layers?: number;
  /** WARP: the vanishing point (default the centre of `bounds`). Move it to
   *  steer — the field swings about it like a camera turning. */
  origin?: VecPt;
  /** WARP: focal length in world units (default 260). Bigger = narrower field
   *  of view, so stars come at you from further ahead. */
  focal?: number;
  /** WARP: nearest depth before a star recycles (default 12). */
  near?: number;
  /** WARP: the depth stars spawn at (default 900). */
  far?: number;
  /**
   * BEND the field sideways with depth. A vector is a constant lean; a
   * FUNCTION `(t, time) => ({x, y})` is a curve, where `t` is 0 near to 1 far
   * and `time` is seconds since the field was made — which is how you get a
   * tunnel that snakes, undulates or whips over as the ship turns.
   *
   * ```ts
   * field.bend = (t, time) => ({ x: Math.sin(time + t * 3) * 260 * t, y: 0 });
   * ```
   *
   * **`'warp'` only.** A flat field has no depth axis to bend along, so
   * bending one just slides its parallax bands sideways past each other, which
   * reads as a glitch rather than a curve. It is ignored in `'drift'`.
   */
  bend?: VecPt | ((t: number, time: number) => VecPt) | null;
  /** WARP: roll the whole field about `origin`, radians/second. */
  spin?: number;
  /** Star size in world units at the nearest depth (default 2.2). */
  size?: number;
  /**
   * Tail length, in SECONDS of travel. **0 (the default) is no tail at all** —
   * plain dots.
   *
   * Each star remembers where it has BEEN, so a tail is a real trail: turn the
   * field and the tails bend, leaving a curve painted on the screen. It fades
   * and thins away to nothing behind, and it lengthens with speed and with
   * nearness on its own — wind it up with the throttle and you have the
   * hyperspace jump.
   */
  streak?: number;
  /** Star colour (default '#ffffff'). */
  color?: string;
  /** A colour SOURCE indexed per star, for a mixed-temperature sky. Resolved
   *  when a star is (re)spawned, not per frame. */
  colors?: VecColorSource | null;
  /** Halo intensity (default 0.5). */
  glow?: number;
  /** Depth for the vector pass. Default: behind everything else in the layer. */
  z?: number;
  /** Deterministic layouts — pass the game's seeded rng. */
  rng?: () => number;
}

/** @internal What a starfield needs from its layer. */
interface StarHost {
  seg(x0: number, y0: number, x1: number, y1: number, style: LineStyle): void;
  /** The view being drawn, so an unbounded field follows a resize. */
  readonly viewRect: { x: number; y: number; w: number; h: number };
}

/**
 * A STARFIELD — the backdrop every game in this canon has, and the one thing
 * all of ours were hand-rolling.
 *
 * Two modes off one object. `'drift'` scrolls a flat parallax field in any
 * direction; `'warp'` flies into the screen down a projected tunnel. Both are
 * fully live: `speed`, `angle`, `origin`, `bend`, `spin`, `streak`, `size`,
 * `glow` and `color` are plain properties, so a ship that accelerates, banks
 * or jumps to lightspeed is a few assignments and no rebuild.
 *
 * ```ts
 * const sky = game.vector.starfield({ count: 300, speed: 60, angle: Math.PI });
 * sky.speed = 60 + throttle * 900;              // accelerate
 * sky.angle += turn * dt;                       // bank
 *
 * const tunnel = game.vector.starfield({ mode: 'warp', speed: 320, streak: 0.05 });
 * tunnel.bend = (t, time) => ({ x: Math.sin(time * 1.2 + t * 4) * 300 * t, y: 0 });
 * ```
 *
 * `stars` is the raw array, so anything the built-ins do not cover you can do
 * by hand — and `each` runs a callback over every star each step if you would
 * rather not write the loop.
 */
export class VecStarfield {
  mode: VecStarMode;
  bounds: VecClipRect | null;
  speed: number;
  angle: number;
  origin: VecPt | null;
  focal: number;
  near: number;
  far: number;
  bend: VecPt | ((t: number, time: number) => VecPt) | null;
  spin: number;
  size: number;
  streak: number;
  color: string;
  colors: VecColorSource | null;
  glow: number;
  z: number | undefined;
  dead = false;

  /** Every star, live. Move them, cull them, sort them — it is just an array. */
  readonly stars: VecStar[] = [];
  /** Run over every star each step, after the built-in motion and before the
   *  draw. The escape hatch for anything the options do not express. */
  each: ((s: VecStar, dt: number, field: VecStarfield) => void) | null = null;

  /** @internal Per-star colour, resolved at (re)spawn rather than per frame. */
  private tints: string[] = [];
  /** @internal A RING of past SCREEN positions per star, `STREAK_CAP` deep —
   *  what makes a streak a trail rather than an extrapolation. Screen space, so
   *  a point stays where it was painted even when the projection moves under
   *  it, which is the whole point: turn, and the tails curve. */
  private hist = new Float32Array(0);
  /** @internal Newest slot in the ring, shared by every star. */
  private head = 0;
  /** @internal How old each ring slot is, in seconds. Shared too — samples are
   *  taken for the whole field at once. This is what keeps a tail the same
   *  LENGTH at any frame rate: below the sample rate the clock cannot keep up
   *  and records one position per frame instead, spaced further apart, so the
   *  ribbon has to stop at `streak` seconds' worth rather than at a fixed
   *  count of samples. */
  private ages = new Float32Array(STREAK_CAP);
  /** @internal Stars whose history is stale (just spawned or just wrapped) and
   *  must be refilled from their current position, or the ribbon draws a streak
   *  across the whole screen from wherever they used to be. */
  private fresh: Uint8Array = new Uint8Array(0);
  /** @internal Time since the last sample, and whether one is due this frame. */
  private tick = 0;
  private sampling = false;
  /** @internal Ring slot holding the OLDEST still-live sample — the far end of
   *  every tail. Shared, because the ages are. */
  private tailIdx = 0;

  /** @internal How many recorded positions this tail is worth. Derived from
   *  its length rather than exposed: one sample per ~1/60 s of tail keeps a
   *  long trail smooth and a short one cheap, and there is no sensible reason
   *  a game would want to choose a different number. */
  private get steps(): number {
    return Math.max(2, Math.min(STREAK_CAP, Math.round(this.streak * 60)));
  }
  /** @internal */ private _layers: number;

  /**
   * DRIFT parallax layers — see the option. Assign any time; the field
   * re-layers on the spot.
   */
  get layers(): number { return this._layers; }
  set layers(n: number) {
    const v = Math.max(0, Math.round(n));
    if (v === this._layers) return;
    this._layers = v;
    for (let i = 0; i < this.stars.length; i++) this.stars[i].z = this.layerOf(i);
  }

  /** @internal The normalised depth of the layer star `i` belongs to. Stars are
   *  dealt round the layers by index, so the split is even and a star keeps its
   *  layer when it recycles. */
  private layerOf(i: number): number {
    return this._layers > 1 ? (i % this._layers) / (this._layers - 1) : 0;
  }

  /** @internal Stars are placed LAZILY. A field is almost always built during
   *  setup, before the first frame, when the layer has no view rect yet — and
   *  laying out against a zero-sized rect puts every star at the origin and
   *  makes the drift wrap divide by zero. */
  private filled = false;
  /** @internal Accumulated roll, seconds, and a reused style object. */
  private roll = 0;
  private time = 0;
  private scratch: LineStyle = {};
  private rng: () => number;

  /** @internal */
  constructor(private host: StarHost, o: VecStarfieldOptions = {}) {
    this.mode = o.mode ?? 'drift';
    this.bounds = o.bounds ?? null;
    this.speed = o.speed ?? 60;
    this.angle = o.angle ?? 0;
    this._layers = Math.max(0, Math.round(o.layers ?? 4));
    this.origin = o.origin ?? null;
    this.focal = o.focal ?? 260;
    this.near = Math.max(1e-3, o.near ?? 12);
    this.far = Math.max(this.near + 1, o.far ?? 900);
    this.bend = o.bend ?? null;
    this.spin = o.spin ?? 0;
    this.size = o.size ?? 2.2;
    this.streak = o.streak ?? 0;
    this.color = o.color ?? '#ffffff';
    this.colors = o.colors ?? null;
    this.glow = o.glow ?? 0.5;
    this.z = o.z;
    this.rng = o.rng ?? Math.random;
    this.resize(Math.max(0, Math.round(o.count ?? 240)));
  }

  /** @internal Is there a rectangle worth laying out against yet? */
  private get ready(): boolean {
    const r = this.rect;
    return r.w > 0 && r.h > 0;
  }

  /** The rectangle in play — the explicit `bounds`, else the live view. */
  get rect(): { x: number; y: number; w: number; h: number } {
    return this.bounds ?? this.host.viewRect;
  }

  /** Grow or shrink the field, keeping the stars already placed. */
  resize(count: number): void {
    while (this.stars.length > count) { this.stars.pop(); this.tints.pop(); }
    while (this.stars.length < count) {
      const s: VecStar = { x: 0, y: 0, z: 0 };
      this.stars.push(s);
      this.tints.push(this.color);
      if (this.filled) this.place(s, this.stars.length - 1, true);
      else this.filled = false;
    }
    if (this.hist.length !== this.stars.length * STREAK_CAP * 2) {
      this.hist = new Float32Array(this.stars.length * STREAK_CAP * 2);
      this.fresh = new Uint8Array(this.stars.length).fill(1);
    }
    if (!this.filled) this.reset();
  }

  /** Re-scatter every star — a new level, a jump, a different sky. */
  reset(): void {
    if (!this.ready) { this.filled = false; return; }
    for (let i = 0; i < this.stars.length; i++) this.place(this.stars[i], i, true);
    this.filled = true;
  }

  /** @internal Is star `i`'s whole ribbon — head AND the far end of its tail —
   *  outside the rect? Culling on the head alone makes a long tail vanish the
   *  instant the star itself leaves, which is very visible at the edges. */
  private gone(i: number, px: number, py: number, r: { x: number; y: number; w: number; h: number }, m: number): boolean {
    const out = (x: number, y: number): boolean =>
      x < r.x - m || x > r.x + r.w + m || y < r.y - m || y > r.y + r.h + m;
    if (!out(px, py)) return false;
    if (this.streak <= 0 || this.fresh[i]) return true;
    const base = i * STREAK_CAP * 2;
    return out(this.hist[base + this.tailIdx * 2], this.hist[base + this.tailIdx * 2 + 1]);
  }

  /** @internal Record the newest screen position for star `i`, and refill the
   *  whole ring when its history is stale so the ribbon starts as a point. */
  private track(i: number, px: number, py: number): void {
    const base = i * STREAK_CAP * 2;
    if (this.fresh[i]) {
      for (let k = 0; k < STREAK_CAP; k++) { this.hist[base + k * 2] = px; this.hist[base + k * 2 + 1] = py; }
      this.fresh[i] = 0;
    } else if (this.sampling) {
      this.hist[base + this.head * 2] = px;
      this.hist[base + this.head * 2 + 1] = py;
    }
  }

  /** @internal Put one star somewhere valid. `anywhere` spreads it through the
   *  whole volume (initial fill); otherwise it enters at the far edge. */
  private place(s: VecStar, i: number, anywhere: boolean): void {
    const r = this.rect;
    if (this.mode === 'warp') {
      s.z = anywhere
        ? this.near + this.rng() * (this.far - this.near)
        : (this.speed >= 0 ? this.far : this.near);
      // Spread within the FRUSTUM at the star's own depth, not within a fixed
      // box. A box puts most of its stars where they project small AND culls
      // the near ones off-screen, so the field reads sparse and distant however
      // many you ask for. Scaling the spread with z keeps the ON-SCREEN density
      // even, which is what a starfield is actually for.
      const k = s.z / this.focal;
      s.x = (this.rng() * 2 - 1) * (r.w * 0.5) * k;
      s.y = (this.rng() * 2 - 1) * (r.h * 0.5) * k;
    } else {
      s.x = r.x + this.rng() * r.w;
      s.y = r.y + this.rng() * r.h;
      s.z = this.layerOf(i);
    }
    this.tints[i] = this.colors ? resolveVecColor(this.colors, i) : this.color;
    if (this.fresh.length > i) this.fresh[i] = 1;
  }

  step(dt: number): void {
    if (this.dead || dt <= 0) return;
    if (!this.filled) { this.reset(); if (!this.filled) return; }
    this.time += dt;
    // The history is sampled on a CLOCK, not per frame: `streak` is a duration,
    // so one sample every streak/steps seconds gives the same length of tail at
    // 30 Hz and at 144 Hz. Sampling per frame would make a fast display draw a
    // short one.
    this.sampling = false;
    if (this.streak > 0) {
      for (let k = 0; k < STREAK_CAP; k++) this.ages[k] += dt;
      const interval = this.streak / this.steps;
      this.tick += dt;
      if (this.tick >= interval) {
        this.tick = interval > 0 ? this.tick % interval : 0;
        this.head = (this.head + 1) % STREAK_CAP;
        this.ages[this.head] = 0;
        this.sampling = true;
      }
      // Where every tail currently ends, so a star can be kept alive until its
      // WHOLE ribbon has left the view rather than just its head.
      this.tailIdx = this.head;
      for (let q = 1; q < this.steps; q++) {
        const idx = (this.head - q + STREAK_CAP) % STREAK_CAP;
        if (this.ages[idx] > this.streak) break;
        this.tailIdx = idx;
      }
    }
    if (this.streak <= 0) this.tailIdx = this.head;
    this.roll += this.spin * dt;
    const stars = this.stars;
    if (this.mode === 'warp') {
      const span = this.far - this.near;
      for (let i = 0; i < stars.length; i++) {
        const s = stars[i];
        s.z -= this.speed * dt;
        // Recycle at whichever end it ran off, so a reversed field works too.
        if (s.z < this.near) { this.place(s, i, false); s.z = this.far - (this.near - s.z) % span; }
        else if (s.z > this.far) { this.place(s, i, false); s.z = this.near + (s.z - this.far) % span; }
      }
    } else {
      const r = this.rect;
      if (r.w <= 0 || r.h <= 0) return;
      const dx = Math.cos(this.angle), dy = Math.sin(this.angle);
      const sgn = Math.sign(this.speed) || 1;
      const ex = dx * sgn, ey = dy * sgn;           // actual direction of travel
      const ax = Math.abs(ex), ay = Math.abs(ey);
      for (let i = 0; i < stars.length; i++) {
        const s = stars[i];
        const v = this.speed * (1 - LAYER_FALLOFF * s.z);
        s.x += dx * v * dt;
        s.y += dy * v * dt;
        // Off the far side, ribbon and all: come back in through the edge the
        // field is flowing FROM. A star is deliberately allowed to run past the
        // rect while its tail is still inside — modulo-wrapping it the moment
        // its head crossed is what made long tails vanish at the edges. A
        // teleport is also why the history has to be dropped: carried across,
        // the ribbon would draw a line straight back over the whole screen.
        if (this.gone(i, s.x, s.y, r, 2)) {
          if (this.rng() * (ax + ay) < ax) {
            s.x = ex > 0 ? r.x - 1 : r.x + r.w + 1;
            s.y = r.y + this.rng() * r.h;
          } else {
            s.y = ey > 0 ? r.y - 1 : r.y + r.h + 1;
            s.x = r.x + this.rng() * r.w;
          }
          this.fresh[i] = 1;
        }
      }
    }
    if (this.each) for (const s of stars) this.each(s, dt, this);
  }

  /** @internal Draw one star's tail through its RECORDED positions, tapering
   *  and fading toward the oldest. Because these are where the star actually
   *  WAS, a turn leaves a curve painted into the screen — extrapolating from
   *  the current heading instead swings the whole tail round with the ship,
   *  which is the thing that does not look like a trail. */
  private ribbon(i: number, px: number, py: number, st: LineStyle): void {
    const w0 = st.width as number, a0 = st.alpha as number;
    const n = this.steps;
    const base = i * STREAK_CAP * 2;
    let hx = px, hy = py, age = 0;
    for (let q = 1; q <= n; q++) {
      const idx = (this.head - (q - 1) + STREAK_CAP) % STREAK_CAP;
      const next = this.ages[idx];
      if (next > this.streak) break;               // past the end of the tail
      const tx = this.hist[base + idx * 2], ty = this.hist[base + idx * 2 + 1];
      // Fade by AGE, not by how many samples happened to be taken, so the tail
      // looks the same whatever the frame rate managed.
      this.taper(w0, a0, (age + next) * 0.5 / this.streak, st);
      this.host.seg(tx, ty, hx, hy, st);
      hx = tx; hy = ty; age = next;
    }
  }

  /** @internal Width and alpha part-way down a tail — `t` is 0 at the head and
   *  1 at the far end, where both reach nothing. Written into the shared style
   *  object, so a whole field's tails cost no allocation. */
  private taper(w: number, a: number, t: number, st: LineStyle): void {
    st.width = Math.max(0.25, w * (1 - t));
    st.alpha = Math.max(0, a * (1 - t));
  }

  /** @internal The bend offset at depth fraction `t`. */
  private bendAt(t: number): { x: number; y: number } {
    const b = this.bend;
    if (!b) return ZERO_BEND;
    return typeof b === 'function' ? b(t, this.time) : { x: b.x * t * t, y: b.y * t * t };
  }

  /** @internal */
  emit(): void {
    if (this.dead || !this.filled || this.stars.length === 0) return;
    const st = this.scratch;
    st.glow = this.glow;
    st.z = this.z;
    st.alpha = 1;
    const r = this.rect;
    const m = 8;                                   // off-screen cull margin
    if (this.mode === 'warp') {
      const ox = this.origin ? this.origin.x : r.x + r.w / 2;
      const oy = this.origin ? this.origin.y : r.y + r.h / 2;
      const span = this.far - this.near;
      const cr = Math.cos(this.roll), sr = Math.sin(this.roll);
      for (let i = 0; i < this.stars.length; i++) {
        const s = this.stars[i];
        const rx = s.x * cr - s.y * sr, ry = s.x * sr + s.y * cr;
        const t = (s.z - this.near) / span;
        const k = this.focal / s.z;
        const bend = this.bendAt(t);
        const px = ox + rx * k + bend.x, py = oy + ry * k + bend.y;
        // Off the screen: RECYCLE rather than skip. Stars spread outward as
        // they approach, so most of the population leaves the view long before
        // it reaches the near plane — waiting for `near` to recycle them leaves
        // the field a tenth as dense as the count asked for. But wait for the
        // whole RIBBON to leave, or a long tail is cut off the instant its
        // star crosses the edge.
        if (this.gone(i, px, py, r, m)) {
          this.place(s, i, false);
          continue;
        }
        // Near stars are bigger and brighter — the whole sense of depth.
        const near = 1 - t;
        st.width = Math.max(0.6, this.size * (0.3 + near * 0.7));
        st.color = this.tints[i];
        st.alpha = 0.35 + near * 0.65;
        if (this.streak > 0) { this.track(i, px, py); this.ribbon(i, px, py, st); }
        else this.host.seg(px, py, px, py, st);    // a zero-length seg is a dot
      }
      return;
    }
    for (let i = 0; i < this.stars.length; i++) {
      const s = this.stars[i];
      const near = 1 - s.z;
      // No bend here: see the note on the option — a flat field has no depth
      // axis to bend along.
      const px = s.x, py = s.y;
      st.width = Math.max(0.35, this.size * (0.3 + near * 0.7));
      st.color = this.tints[i];
      st.alpha = 0.3 + near * 0.7;
      if (this.streak > 0) { this.track(i, px, py); this.ribbon(i, px, py, st); }
      else this.host.seg(px, py, px, py, st);
    }
  }

  /** Remove the field from the layer. */
  kill(): void {
    this.dead = true;
  }
}

const ZERO_BEND = { x: 0, y: 0 };
/** How many past positions a streak can remember. */
const STREAK_CAP = 16;
/** How much slower the FARTHEST drift layer runs than the nearest. Derived
 *  from the layer count rather than exposed: what a game wants to say is "four
 *  layers", not "four layers spread over 0.8 of a speed range". At 0.8 the back
 *  layer crawls at a fifth of the front, which separates them clearly without
 *  the far sky looking frozen. */
const LAYER_FALLOFF = 0.8;

/** Tuning for `layer.trail()`. Everything is optional. */
export interface VecTrailOptions {
  /** Samples kept (default 32). The oldest is the tail. */
  length?: number;
  /**
   * Minimum world distance between samples (default 4). Without it a slow or
   * stationary emitter fills the buffer with duplicate points and the trail
   * collapses to a dot — the single thing most hand-rolled trails get wrong.
   */
  minDist?: number;
  /**
   * Split a move LONGER than this into several samples (default 0 = off).
   *
   * Without it a trail lays down exactly one sample per frame, so its shape
   * depends on frame rate: the same object at 30fps leaves chords twice as
   * long as at 60, and a fast mover on a curve draws a visible polygon. Set
   * it to the longest chord you are happy with and the ribbon looks the same
   * at any frame rate.
   *
   * It is off by default because on a LENGTH-bound trail it also shortens the
   * ribbon — `length: 32, maxDist: 8` can never span more than 256 units. On
   * a `life`-bound trail there is no such interaction, so turn it on freely.
   */
  maxDist?: number;
  /** Seconds a sample survives. Omit and the trail is length-bound only. */
  life?: number;
  /** Stroke width at the head (default 3) and at the tail (default 0). */
  width?: number;
  tailWidth?: number;
  /** Alpha at the head (default 1) and at the tail (default 0). */
  alpha?: number;
  tailAlpha?: number;
  /** Head colour, and optionally a different tail colour to grade toward. */
  color?: string;
  tailColor?: string;
  /** …or a full colour SOURCE stepped along the trail — the same sources
   *  `colors` and the emitter take (`'rainbow'`, `{ hue }`, a palette, a fn). */
  colors?: VecColorSource;
  /** Halo intensity at the head (default 0.7); it fades out with the alpha. */
  glow?: number;
  /** Beam dwell 0..1 (default 0). */
  dwell?: number;
  /** Depth, as on any line. */
  z?: number;
}

/** @internal What a trail needs from a layer — both backends satisfy it. */
interface TrailHost {
  seg(x0: number, y0: number, x1: number, y1: number, style: LineStyle): void;
}

/**
 * A ribbon that follows a moving point, tapering and fading toward its tail.
 *
 * ```ts
 * const wake = game.vector.trail({ length: 40, width: 4, color: '#41d6ff', tailColor: '#ff2d95' });
 * wake.push(ship.x, ship.y);        // once a frame; the layer draws it
 * wake.kill();                      // when the ship dies
 * ```
 *
 * The layer draws every live trail for you, so there is no per-frame draw call
 * to forget. Samples are dropped by `length`, by `life`, or both.
 */
export class VecTrail {
  /** Live-tunable — change any of these between frames. */
  length: number;
  minDist: number;
  maxDist: number;
  life: number;
  width: number;
  tailWidth: number;
  alpha: number;
  tailAlpha: number;
  color: string;
  tailColor: string | null;
  colors: VecColorSource | null;
  glow: number;
  dwell: number;
  z: number | undefined;
  dead = false;

  /** @internal Newest LAST. Ages run in step with it. */
  private pts: VecPt[] = [];
  private ages: number[] = [];
  /** @internal One style object, rewritten per segment — packStyle copies out
   *  of it, so there is no garbage per segment per frame. */
  private scratch: LineStyle = {};

  /** @internal */
  constructor(private host: TrailHost, o: VecTrailOptions = {}) {
    this.length = Math.max(2, o.length ?? 32);
    this.minDist = o.minDist ?? 4;
    this.maxDist = o.maxDist ?? 0;
    this.life = o.life ?? 0;
    this.width = o.width ?? 3;
    this.tailWidth = o.tailWidth ?? 0;
    this.alpha = o.alpha ?? 1;
    this.tailAlpha = o.tailAlpha ?? 0;
    this.color = o.color ?? '#ffffff';
    this.tailColor = o.tailColor ?? null;
    this.colors = o.colors ?? null;
    this.glow = o.glow ?? 0.7;
    this.dwell = o.dwell ?? 0;
    this.z = o.z;
  }

  /** How many samples the trail is currently holding. */
  get count(): number { return this.pts.length; }
  /** The samples, oldest first — read-only. */
  get points(): readonly VecPt[] { return this.pts; }

  /**
   * Add a sample. Call once a frame with the thing's position; a move shorter
   * than `minDist` is folded into the head rather than added, so standing
   * still does not eat the buffer.
   */
  push(x: number, y: number): void {
    const head = this.pts[this.pts.length - 1];
    if (head) {
      const d = Math.hypot(x - head.x, y - head.y);
      if (d < this.minDist) {
        head.x = x; head.y = y;
        this.ages[this.ages.length - 1] = 0;
        return;
      }
      if (this.maxDist > 0 && d > this.maxDist) {
        // Fill in the gap so the ribbon's shape does not depend on frame rate.
        // Capped, so a teleport cannot spam thousands of samples — for a real
        // jump you want clear() anyway.
        const steps = Math.min(64, Math.ceil(d / this.maxDist));
        for (let k = 1; k <= steps; k++) {
          const f = k / steps;
          this.add(head.x + (x - head.x) * f, head.y + (y - head.y) * f);
        }
        return;
      }
    }
    this.add(x, y);
  }

  /** @internal One sample, with the length cap applied. */
  private add(x: number, y: number): void {
    this.pts.push({ x, y });
    this.ages.push(0);
    while (this.pts.length > this.length) { this.pts.shift(); this.ages.shift(); }
  }

  /** Drop every sample — a teleport, so the ribbon doesn't smear across it. */
  clear(): void { this.pts.length = 0; this.ages.length = 0; }

  /** Stop drawing this trail and let the layer forget it. */
  kill(): void { this.dead = true; }

  /** @internal Age samples out when `life` is set. */
  step(dt: number): void {
    if (this.life <= 0) return;
    for (let i = 0; i < this.ages.length; i++) this.ages[i] += dt;
    let drop = 0;
    while (drop < this.ages.length && this.ages[drop] > this.life) drop++;
    if (drop > 0) { this.pts.splice(0, drop); this.ages.splice(0, drop); }
  }

  /** @internal Push the ribbon into the layer as per-segment lines. */
  emit(): void {
    const n = this.pts.length;
    if (n < 2) return;

    // The taper runs on ARC LENGTH, not sample index. Sample spacing is never
    // even — a mover that speeds up and slows down lays down chords that
    // differ by 5x within one ribbon — and an index-based ramp gives those
    // chords the same width step regardless of how far they span, so the
    // trail visibly thins fast where samples are dense and slowly where they
    // are sparse. Measuring along the ribbon makes the taper uniform in SPACE,
    // which is what the eye expects.
    const cum: number[] = new Array(n);
    cum[0] = 0;
    for (let i = 1; i < n; i++) {
      const a = this.pts[i - 1], b = this.pts[i];
      cum[i] = cum[i - 1] + Math.hypot(b.x - a.x, b.y - a.y);
    }
    const total = cum[n - 1];
    const at = (i: number): number => (total > 1e-9 ? cum[i] / total : i / (n - 1));

    const st = this.scratch;
    st.z = this.z;
    st.dwell = this.dwell;
    for (let i = 0; i < n - 1; i++) {
      const t0 = at(i), t1 = at(i + 1);
      // Width, alpha and glow come from the segment's MIDPOINT, so a long
      // chord doesn't jump a step.
      const tm = (t0 + t1) / 2;
      st.width = this.tailWidth + (this.width - this.tailWidth) * tm;
      st.alpha = this.tailAlpha + (this.alpha - this.tailAlpha) * tm;
      st.glow = this.glow * tm;
      if (this.colors) {
        st.color = resolveVecColor(this.colors, i);
        st.color2 = undefined;
      } else if (this.tailColor) {
        // Each segment carries its OWN slice of the ramp end to end, so the
        // colour is continuous along the ribbon rather than banded per chord.
        st.color = colorKit.lerp(this.tailColor, this.color, t0);
        st.color2 = colorKit.lerp(this.tailColor, this.color, t1);
      } else {
        st.color = this.color;
        st.color2 = undefined;
      }
      const a = this.pts[i], b = this.pts[i + 1];
      this.host.seg(a.x, a.y, b.x, b.y, st);
    }
  }
}

// ---------------------------------------------------------------------------
// Styles + handles.

export interface LineStyle {
  /** Stroke width, world units (default 2). */
  width?: number;
  color?: string;
  /** Colour at the far endpoint — a gradient along the line. ONE line: on a
   *  polyline this repeats per segment and reads as banding. For a chain, use
   *  `colors`. */
  color2?: string;
  /**
   * A colour SOURCE walked one step PER SEGMENT — the chain-safe way to grade
   * a line. `'rainbow'`, `{ hue: [from, to] }`, `{ from, to }`, a palette
   * array, or your own `(i) => string`. Overrides `color`.
   *
   * ```ts
   * game.vector.shape(pts, { colors: 'rainbow', width: 2, glow: 0.9 });
   * game.vector.poly(ridge, { colors: { hue: [200, 320] } });
   * ```
   *
   * The same sources the emitter takes — see {@link VecColorSource}.
   */
  colors?: VecColorSource;
  alpha?: number;
  /** Phosphor halo intensity 0..~1.5 (default 0.5; 0 = clean line). The
   * halo radius is width × (3 + glow × 5). */
  glow?: number;
  /** Dash period in world units (half duty; 0 = solid). Dashes gate the
   * CORE only — the halo stays continuous, which is what sells it. */
  dash?: number;
  /**
   * BEAM DWELL 0..1 (default 0) — how much the ends of each segment brighten
   * and fatten, the way a real display's beam does where it slows down.
   *
   * On a closed outline the endpoints coincide at every joint, so it is the
   * CORNERS that light up: the single most recognisable property of a vector
   * monitor after the halo itself. Try 0.5–0.8 with `glow` up.
   */
  dwell?: number;
  /** Depth (0..Z_RANGE like sprites; default mid-range). */
  z?: number;
}

/** A shape's solid face. Absent (or transparent) = outline only, the default. */
export interface VecFill {
  /**
   * The face colour, as HEX (`#rgb`, `#rrggbb`, `#rrggbbaa`) — the engine's
   * colour parser takes nothing else and falls back to white. `'transparent'`,
   * `'none'` or a zero alpha mean no fill at all.
   *
   * Optional only because `stops` can supply the colours instead; give one or
   * the other or you get no face.
   */
  color?: string;
  /** Gradient end colour — a two-stop ramp. Omit for a flat face. */
  to?: string;
  /**
   * A MULTI-STOP ramp, evenly spaced along the gradient axis. Overrides `to`.
   * Pairs with `colorKit`: `stops: colorKit.rainbow(6)` or
   * `colorKit.ramp('fire', 5)`.
   */
  stops?: string[];
  /** Gradient direction in SHAPE-LOCAL radians (default 0 = left→right). The
   *  gradient spans the outline's own bounding box along that axis, so it
   *  rotates with the shape and never needs re-authoring at a new size. */
  angle?: number;
  /**
   * RADIAL instead of linear: the ramp runs from the outline's centroid out to
   * its furthest vertex, so `angle` is ignored. The centre-glow look — a
   * Tempest well, a shield bubble, a planet.
   */
  radial?: boolean;
}

export interface VectorShapeOptions extends LineStyle {
  /**
   * A SOLID FACE under the outline — the Tempest 2000 look, and what makes a
   * corridor a corridor.
   *
   * ```ts
   * game.vector.shape(pts, { fill: '#1b2a6b' });                       // flat
   * game.vector.shape(pts, { fill: { color: '#4b1d7a', to: '#ff2d95' } }); // gradient
   * ```
   *
   * Fills WRITE DEPTH, so a nearer shape hides the fills AND the outlines
   * behind it — set `z` per shape to order them. Outlines still draw over
   * their own fill (equal depth passes), so a shape is never hidden by itself.
   */
  fill?: string | string[] | VecFill | null;
  x?: number;
  y?: number;
  rot?: number;
  scale?: number;
  /**
   * The point the shape TURNS AND SCALES ABOUT, in the same space as the
   * points you handed in. Default `null` — the origin, `(0, 0)`.
   *
   * Build geometry wherever it is natural and say where its centre is:
   *
   * ```ts
   * const ring = vectorKit.ringSections(cx, cy, 250, 12);          // built in place
   * game.vector.shape(ring[0].points, { pivot: { x: cx, y: cy } }); // and it spins in place
   * ```
   *
   * Without it a shape turns about `(0, 0)` in its own point space, so anything
   * built away from the origin ORBITS the origin instead of turning where it
   * sits. `x`/`y` still translate, measured from the pivot.
   */
  pivot?: VecPt | null;
  /** Join the last point back to the first (default true). */
  closed?: boolean;
  /**
   * SCREEN WRAP. Give the shape the world size and it is drawn at its mirror
   * positions too, so a rock straddling an edge stays whole instead of being
   * sliced in half — the thing every Asteroids-like needs and the one thing a
   * single retained transform cannot express.
   *
   * ```ts
   * game.vector.shape(rockPoints, { x, y, wrap: { w: view.w, h: view.h } });
   * ```
   *
   * Keep the position itself in range with `vectorKit.wrapPosition`; this is
   * only the drawing half.
   */
  wrap?: { w: number; h: number } | null;
}

/**
 * Triangulate an outline into fill vertices — `[x, y, r, g, b, a]` per vertex,
 * three per triangle — with the gradient resolved PER VERTEX at pack time.
 *
 * `VectorShape` calls this for you; it is exported because it is pure and
 * testable, and because it is the honest description of what a fill costs:
 * one ear-clip when the outline changes, then nothing at runtime.
 *
 * An unparseable, `'transparent'`, `'none'` or zero-alpha colour yields no
 * vertices at all — that is how "no fill" is spelled.
 */
export function buildFill(
  points: readonly VecPt[], fill: string | string[] | VecFill | null | undefined,
): number[] {
  if (!fill || points.length < 3) return [];
  const spec: VecFill = typeof fill === 'string' ? { color: fill }
    : Array.isArray(fill) ? { color: fill[0] ?? '', stops: fill }
    : fill;
  // `rgba()` is HEX ONLY and silently returns WHITE for anything it can't
  // parse, so the word 'transparent' has to be caught here — otherwise the
  // documented "transparent means no fill" would paint an opaque white face.
  const raw = spec.stops?.length ? spec.stops
    : (spec.color && spec.to ? [spec.color, spec.to] : [spec.color ?? '']);
  if (!raw[0] || raw[0] === 'transparent' || raw[0] === 'none') return [];
  const stops = raw.map((c) => rgba(c) as unknown as [number, number, number, number]);
  if (stops.every((c) => c[3] <= 0)) return [];     // #rrggbb00 = no face

  // Where each vertex sits on the ramp, 0..1.
  let at: (p: VecPt) => number;
  // A radial ramp needs a vertex AT THE CENTRE to carry t = 0. Ear clipping
  // only ever emits rim vertices, so on a regular polygon every one of them
  // sits at t = 1 and the whole face comes out the LAST stop — a flat disc.
  // Fanning from the centroid fixes it, and is valid whenever the centroid is
  // guaranteed inside, i.e. when the outline is convex. Concave radial fills
  // fall back to ear clipping and are only as smooth as their vertices.
  let fan: VecPt | null = null;
  if (spec.radial) {
    let cx = 0, cy = 0;
    for (const p of points) { cx += p.x; cy += p.y; }
    cx /= points.length; cy /= points.length;
    let max = 0;
    for (const p of points) max = Math.max(max, Math.hypot(p.x - cx, p.y - cy));
    at = (p) => (max > 1e-9 ? Math.hypot(p.x - cx, p.y - cy) / max : 0);
    if (isConvex(points)) fan = { x: cx, y: cy };
  } else {
    // Project onto the gradient axis over the outline's own bounds, so the
    // ramp spans the shape whatever its size or orientation.
    const a = spec.angle ?? 0;
    const ax = Math.cos(a), ay = Math.sin(a);
    let lo = Infinity, hi = -Infinity;
    for (const p of points) {
      const t = p.x * ax + p.y * ay;
      if (t < lo) lo = t;
      if (t > hi) hi = t;
    }
    const span = hi - lo;
    at = (p) => (span > 1e-9 ? ((p.x * ax + p.y * ay) - lo) / span : 0);
  }

  // Sample the ramp: n stops make n-1 evenly spaced segments.
  const last = stops.length - 1;
  const sample = (t: number, ch: number): number => {
    if (last === 0) return stops[0][ch];
    const f = Math.max(0, Math.min(1, t)) * last;
    const i = Math.min(last - 1, Math.floor(f));
    const k = f - i;
    return stops[i][ch] + (stops[i + 1][ch] - stops[i][ch]) * k;
  };

  const out: number[] = [];
  const push = (p: VecPt): void => {
    const t = at(p);
    out.push(p.x, p.y, sample(t, 0), sample(t, 1), sample(t, 2), sample(t, 3));
  };
  if (fan) {
    // CONCENTRIC RINGS, one per stop. A plain centroid fan only has vertices
    // at t=0 and t=1, so every middle stop of a 3+ stop radial would be
    // interpolated straight past and never appear. Subdividing centre→rim into
    // one band per stop gives each of them a ring of vertices to live on.
    const K = Math.max(2, stops.length);
    const ring = (k: number, i: number): VecPt => {
      const f = k / (K - 1);
      return { x: fan.x + (points[i].x - fan.x) * f, y: fan.y + (points[i].y - fan.y) * f };
    };
    const n = points.length;
    for (let k = 0; k < K - 1; k++) {
      for (let i = 0; i < n; i++) {
        const j = (i + 1) % n;
        if (k === 0) {
          push(fan); push(ring(1, i)); push(ring(1, j));
        } else {
          push(ring(k, i)); push(ring(k + 1, i)); push(ring(k + 1, j));
          push(ring(k, i)); push(ring(k + 1, j)); push(ring(k, j));
        }
      }
    }
  } else {
    for (const [i, j, k] of triangulate(points)) {
      push(points[i]); push(points[j]); push(points[k]);
    }
  }
  return out;
}

/** A LineStyle resolved to the numbers an instance carries. `segmentStyles`
 *  returns these; nothing else needs to build one. */
export interface PackedStyle {
  coreHalf: number; stampHalf: number; z: number;
  dash: number; glow: number; capped: number; dwell: number;
  c0: [number, number, number, number];
  c1: [number, number, number, number];
}

function packStyle(o: LineStyle): PackedStyle {
  const width = o.width ?? 2;
  const glow = o.glow ?? 0.5;
  const c0 = rgba(o.color ?? '#ffffff') as unknown as [number, number, number, number];
  const c1 = o.color2 ? (rgba(o.color2) as unknown as [number, number, number, number]) : c0;
  const alpha = o.alpha ?? 1;
  return {
    coreHalf: width / 2,
    // The glow-stamp half-width: a touch fatter than the core so hairlines
    // still bloom; the GlowPass blur does the real widening.
    stampHalf: glow > 0 ? width / 2 + 1 + glow * 2 : 0,
    z: (o.z ?? Z_RANGE * 0.5) / Z_RANGE,
    dash: o.dash ?? 0,
    glow,
    capped: width >= 1 ? 1 : 0,
    dwell: Math.max(0, o.dwell ?? 0),
    c0: [c0[0], c0[1], c0[2], c0[3] * alpha],
    c1: [c1[0], c1[1], c1[2], c1[3] * alpha],
  };
}

/** A retained line shape: segments under one live transform. Mutate
 * x/y/rot/scale/alpha/glowMul freely — the per-frame cost is 8 floats. */
export class VectorShape {
  x: number; y: number; rot: number; scale: number;
  /** Whole-shape alpha multiplier (fade without touching colours). */
  alpha = 1;
  /** Whole-shape halo multiplier (pump the glow on hits). */
  glowMul = 1;
  /** @see VectorShapeOptions.wrap — set or clear it at any time. */
  wrap: { w: number; h: number } | null;
  /** @see VectorShapeOptions.pivot — set or clear it at any time; it is read
   *  per frame, so nothing re-packs. */
  pivot: VecPt | null;
  dead = false;

  /** @see VectorShapeOptions.fill — assign at any time; re-packs next frame. */
  get fill(): string | string[] | VecFill | null { return this.rawFill; }
  set fill(f: string | string[] | VecFill | null) {
    this.rawFill = f;
    this.retriangulate();
    this.layer.dirty = true;
  }
  /** @internal */ private rawFill: string | string[] | VecFill | null = null;
  /** @internal The outline's own points — the fill needs them, the segment
   *  pairs alone cannot be triangulated. */
  points: VecPt[] = [];
  /** @internal Triangulated fill vertices: [x, y, r, g, b, a] per vertex. */
  fillVerts: number[] = [];
  /** @internal */ segs: Array<[VecPt, VecPt]>;
  /** @internal Bisector cut planes, 4 floats per segment — see chainJoins. */
  joins: Float32Array;
  /** @internal */ style: PackedStyle;
  /** @internal Per-segment styles when `colors` is set — see segmentStyles. */
  segStyles: PackedStyle[] | null = null;
  /** @internal */ raw: LineStyle;
  /** @internal */ layer: VectorLayer;

  constructor(layer: VectorLayer, points: readonly VecPt[], opts: VectorShapeOptions) {
    this.layer = layer;
    this.x = opts.x ?? 0; this.y = opts.y ?? 0;
    this.rot = opts.rot ?? 0; this.scale = opts.scale ?? 1;
    this.segs = polySegs(points, opts.closed ?? true);
    this.joins = chainJoins(points, opts.closed ?? true);
    this.points = points.map((p) => ({ x: p.x, y: p.y }));
    this.wrap = opts.wrap ?? null;
    this.pivot = opts.pivot ?? null;
    this.raw = { ...opts };
    this.style = packStyle(this.raw);
    this.segStyles = segmentStyles(this.raw, this.segs);
    this.rawFill = opts.fill ?? null;
    this.retriangulate();
  }

  /** @internal Rebuild the filled face. Runs on construction, on setPoints and
   *  when `fill` is assigned — never per frame. */
  private retriangulate(): void {
    this.fillVerts = buildFill(this.points, this.rawFill);
  }

  /** True when this shape contributes a solid face. */
  get filled(): boolean { return this.fillVerts.length > 0; }

  /** Merge new style fields (width/color/glow/dash/…) — hit flashes, retro
   * width toggles. Re-packs on the next frame. */
  restyle(style: Partial<LineStyle>): void {
    Object.assign(this.raw, style);
    this.style = packStyle(this.raw);
    this.segStyles = segmentStyles(this.raw, this.segs);
    this.layer.dirty = true;
  }

  /** Replace the outline (deformable terrain: splice + set). Re-packs only
   * on the next flush. */
  setPoints(points: readonly VecPt[], closed = true): void {
    this.segs = polySegs(points, closed);
    this.joins = chainJoins(points, closed);
    this.points = points.map((p) => ({ x: p.x, y: p.y }));
    this.segStyles = segmentStyles(this.raw, this.segs);
    this.retriangulate();
    this.layer.dirty = true;
  }

  /** Explode the outline: every segment flies off on its own transform with
   * outward velocity + spin, fading over `life`. The shape itself dies. */
  shatter(opts: { speed?: number; spin?: number; life?: number; drag?: number } = {}): void {
    this.layer.shatterShape(this, opts);
  }

  kill(): void {
    if (this.dead) return;
    this.dead = true;
    this.layer.dirty = true;
  }
}

/** @internal One live piece — a shatter shard or an emitted particle. */
export interface LiveFragment extends VecFragment {
  /** Segments about the piece's own centre. Shatter makes one; an emitted
   *  particle makes a whole outline, rigid under the shared transform. */
  segs: Array<[VecPt, VecPt]>;
  /** Cut planes for `segs`, or null for a lone shard — see chainJoins. */
  joins: Float32Array | null;
  style: PackedStyle;
  drag: number;
  /** Size envelope over life — start and end scale (both 1 for shatter). */
  scaleFrom: number;
  scaleTo: number;
  /** Downward acceleration, world units/s². */
  gravity: number;
  /** Inherited from the shattered shape — the glow slider must keep
   * governing pieces already in flight. */
  glowMul: number;
}

// ---------------------------------------------------------------------------
// The layer: retained shapes + fragments + immediate pushes, ONE pipeline.

export class VectorLayer {
  /** @internal Static (retained) data needs re-packing. */
  dirty = false;

  /**
   * Clip the WHOLE layer to a world-space rectangle — a radar scope, a
   * Battlezone viewport, a split screen, Tempest's tube mouth. `null` (the
   * default) draws everywhere.
   *
   * ```ts
   * game.vector.clip = { x: 40, y: 40, w: 320, h: 320 };
   * ```
   *
   * It is a scissor on the whole layer draw, not per shape — the layer is one
   * pass, and that is the level at which clipping is free. The GLOW STAMP is
   * scissored with it, so halos are cut at the same edge instead of leaking
   * out of the window (which is what makes it look like a window at all).
   *
   * `d.pushClip` does NOT reach the vector layer; this is its clip.
   */
  clip: VecClipRect | null = null;


  private shapes: VectorShape[] = [];
  private fragments: LiveFragment[] = [];
  private trails: VecTrail[] = [];
  /** @internal Registered starfields, stepped and drawn with the trails. */
  private fields: VecStarfield[] = [];
  /**
   * @internal How many of this frame's immediate instances are BACKDROP —
   * starfields, which emit before anything else.
   *
   * Immediate pushes normally draw after the retained shapes, and lines test
   * depth without writing it, so line-over-line is pure submission order: a
   * starfield would paint straight over every ship and rock in the scene. A
   * backdrop is the one thing in the layer that is defined by being behind, so
   * its span of the dynamic buffer is drawn first, before the static pass.
   */
  private backdropCount = 0;

  /** The view rect this layer is drawing — what an unbounded starfield uses. */
  get viewRect(): { x: number; y: number; w: number; h: number } {
    const u = this.uniformData;
    return { x: u[0], y: u[1], w: u[2], h: u[3] };
  }

  /**
   * A STARFIELD behind the game — parallax drift, or a warp tunnel into the
   * screen. Everything about it is a live property; see `VecStarfield`.
   *
   * ```ts
   * const sky = game.vector.starfield({ count: 300, speed: 60, angle: Math.PI });
   * sky.speed = 60 + throttle * 900;                    // live
   * const tunnel = game.vector.starfield({ mode: 'warp', speed: 320, streak: 0.05 });
   * ```
   *
   * The layer steps and draws it — there is nothing to call per frame.
   * `kill()` removes it.
   */
  starfield(opts: VecStarfieldOptions = {}): VecStarfield {
    const f = new VecStarfield(this, opts);
    this.fields.push(f);
    return f;
  }

  /** Runs across frames so a stream cycles a colour source smoothly. */
  private colorSeq = 0;
  private rng: () => number = Math.random;

  /**
   * SOLID FACES on or off. `null` (the default) is AUTO — the pass runs only
   * when at least one live shape actually has a fill, so a pure line-art game
   * never pays for it. `true`/`false` force it.
   */
  fills: boolean | null = null;

  private staticData: Float32Array<ArrayBuffer> = new Float32Array(1024 * LINE_FLOATS);
  private staticCount = 0;
  /** Fill vertices: opaque ones first (they write depth), then translucent. */
  private fillData: Float32Array<ArrayBuffer> = new Float32Array(1024 * FILL_FLOATS);
  private fillOpaque = 0;
  private fillBlend = 0;
  private dynData: Float32Array<ArrayBuffer> = new Float32Array(1024 * LINE_FLOATS);
  private dynCount = 0;
  private dynGlow = 0;
  private xformData: Float32Array<ArrayBuffer> = new Float32Array(256 * XFORM_FLOATS);
  private uniformData = new Float32Array(4);

  private device!: GPUDevice;
  private pipeline!: GPURenderPipeline;
  private stampPipeline!: GPURenderPipeline;
  private layout!: GPUBindGroupLayout;
  private uniforms!: GPUBuffer;
  private staticBuf!: GPUBuffer;
  private dynBuf!: GPUBuffer;
  private fillBuf!: GPUBuffer;
  private fillBind!: GPUBindGroup;
  private fillPipeline!: GPURenderPipeline;
  private fillBlendPipeline!: GPURenderPipeline;
  private xformBuf!: GPUBuffer;
  private staticBind!: GPUBindGroup;
  private dynBind!: GPUBindGroup;

  constructor(device: GPUDevice, private format: GPUTextureFormat) {
    this.rebuild(device);
  }

  /** Live counts (debug/HUD). */
  get counts(): { shapes: number; fragments: number; segments: number } {
    let segments = this.dynCount;
    for (const s of this.shapes) if (!s.dead) segments += s.segs.length * (s.wrap ? 4 : 1);
    for (const f of this.fragments) segments += f.segs.length;
    return { shapes: this.shapes.filter((s) => !s.dead).length, fragments: this.fragments.length, segments };
  }

  /** Add a retained shape from an outline (see VectorShapeOptions). */
  shape(points: readonly VecPt[], opts: VectorShapeOptions = {}): VectorShape {
    const s = new VectorShape(this, points, opts);
    this.shapes.push(s);
    this.dirty = true;
    return s;
  }

  /**
   * A TRAIL — the ribbon a moving thing leaves behind.
   *
   * ```ts
   * const wake = game.vector.trail({ length: 40, width: 4, color: '#41d6ff', tailColor: '#ff2d95' });
   * wake.push(ship.x, ship.y);          // once a frame, and that is all
   * ```
   *
   * The layer ages and draws every live trail itself, so there is no per-frame
   * draw call to forget. `kill()` when the thing making it dies.
   *
   * This is what replaced full-screen phosphor feedback. Feedback smeared the
   * whole image and blew out anything that stood still; a trail is geometry
   * owned by one object, so it tapers, grades, and leaves nothing behind
   * something that is not moving.
   */
  trail(opts: VecTrailOptions = {}): VecTrail {
    const t = new VecTrail(this, opts);
    this.trails.push(t);
    return t;
  }

  /** Immediate one-frame segment (aim lines, scanner sweeps, lightning). */
  seg(x0: number, y0: number, x1: number, y1: number, style: LineStyle = {}): void {
    const p = packStyle(style);
    if (p.glow > 0) this.dynGlow = Math.max(this.dynGlow, p.stampHalf);
    this.pushDyn(x0, y0, x1, y1, p, 0);
  }

  /** Immediate one-frame polyline. */
  poly(points: readonly VecPt[], style: LineStyle = {}, closed = false): void {
    const p = packStyle(style);
    if (p.glow > 0) this.dynGlow = Math.max(this.dynGlow, p.stampHalf);
    const segs = polySegs(points, closed);
    const per = segmentStyles(style, segs);
    const joins = chainJoins(points, closed);
    let k = 0;
    for (const [a, b] of segs) {
      this.pushDyn(a.x, a.y, b.x, b.y, per?.[k] ?? p, 0, joins, k * 4);
      k++;
    }
  }

  /**
   * Immediate arc — `from` and `to` in radians, clockwise (y is down, so
   * -PI/2 is straight up). A full circle is `arc(x, y, r, 0, Math.PI * 2)`.
   *
   * ```ts
   * game.vector.arc(cx, cy, 90, -0.5, 0.5, { color: '#41d6ff', glow: 0.9 });
   * ```
   *
   * `steps` overrides the tessellation (default: one segment per ~11°). For a
   * ring that ROTATES or breaks apart, build it retained instead — see
   * `vectorKit.ringSections()`.
   */
  arc(cx: number, cy: number, r: number, from: number, to: number, style: LineStyle = {}, steps?: number): void {
    this.poly(arcPoints(cx, cy, r, from, to, steps), style, false);
  }

  /**
   * Draw a line of text AS LINE ART — the same beam that draws everything else.
   *
   * ```ts
   * game.vector.text('SCORE 004200', 20, 20, { size: 26, style: { color: '#39f0a0', glow: 0.8 } });
   * game.vector.text('GAME OVER', cx, cy, { size: 70, align: 'center', colors: 'rainbow' });
   * ```
   *
   * Caps-only (lowercase folds up), straight strokes only, `\n` starts a new
   * line. It takes everything a line takes — `width`, `glow`, `dash`, and a
   * `colors` SOURCE stepped per stroke.
   *
   * This is the immediate path. To make text a real object that can fly,
   * rotate and `shatter()`, build it with `vectorKit.textOutline()` and hand
   * the polylines to `shape()`.
   */
  text(str: string, x: number, y: number, opts: VecTextOptions & { style?: LineStyle } = {}): void {
    const style = opts.style ?? {};
    for (const pts of textOutline(str, x, y, opts)) this.poly(pts, style, false);
  }

  /** @internal Deterministic tests inject a seeded rng. */
  setRng(rng: () => number): void {
    this.rng = rng;
  }

  /** @internal */
  shatterShape(shape: VectorShape, opts: { speed?: number; spin?: number; life?: number; drag?: number }): void {
    if (shape.dead) return;
    // Bake the shape's transform into WORLD space and re-express every
    // segment about its own MIDPOINT — the fragment transform then sits ON
    // the piece, so spin turns it in place (parented to the shape origin it
    // would orbit — Rich: "segments rotate from their ends").
    const cr = Math.cos(shape.rot), sr = Math.sin(shape.rot);
    const s = shape.scale;
    // The same translation the shader uses, so a pivoted shape shatters from
    // where it is DRAWN rather than from where its points happen to be.
    const org = shapeOrigin(shape);
    const toWorld = (p: VecPt): VecPt => ({
      x: org.x + (p.x * cr - p.y * sr) * s,
      y: org.y + (p.x * sr + p.y * cr) * s,
    });
    // Pieces fly out from the point the shape turned about.
    const hub = shape.pivot
      ? { x: shape.x + shape.pivot.x, y: shape.y + shape.pivot.y }
      : { x: shape.x, y: shape.y };
    let k = 0;
    for (const seg of shape.segs) {
      const a = toWorld(seg[0]);
      const b = toWorld(seg[1]);
      const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
      const dx = mid.x - hub.x, dy = mid.y - hub.y;
      const dl = Math.hypot(dx, dy) || 1;
      const f = spawnFragment(mid.x, mid.y, dx / dl, dy / dl, opts, this.rng) as LiveFragment;
      f.segs = [[{ x: a.x - mid.x, y: a.y - mid.y }, { x: b.x - mid.x, y: b.y - mid.y }]];
      f.joins = null;                            // one shard, nothing to join
      f.style = shape.segStyles?.[k++] ?? shape.style;
      f.drag = opts.drag ?? 0.4;
      f.glowMul = shape.glowMul;
      f.scaleFrom = 1;
      f.scaleTo = 1;
      f.gravity = 0;
      this.fragments.push(f);
    }
    shape.kill();
  }


  /**
   * Spawn a burst of VECTOR particles — little outlines that fly, spin, fade
   * and glow with the rest of the layer.
   *
   * ```ts
   * game.vector.emit({ x, y, count: 24, shape: ['triangle', 'square'],
   *                    size: 7, speed: 160, spin: 6,
   *                    style: { color: '#41d6ff', width: 2, glow: 0.9 } });
   * ```
   *
   * They cost what any other segments cost: same buffers, same transform slot,
   * same glow stamp. Mixing `shape` kinds picks one per particle.
   */
  emit(opts: VecEmitOptions): void {
    const rand = this.rng;
    const count = opts.count ?? 12;
    const kinds: VecShapeKind[] = Array.isArray(opts.shape)
      ? (opts.shape.length ? opts.shape : ['square'])
      : [opts.shape ?? 'square'];
    const baseStyle = packStyle(opts.style ?? {});
    const src = opts.colors;
    const size = opts.size ?? 6;
    const sizeVar = opts.sizeVar ?? 2;
    const speed = opts.speed ?? 90;
    const speedVar = opts.speedVar ?? 40;
    const angle = opts.angle ?? 0;
    const spread = opts.spread ?? Math.PI * 2;
    const spawnR = opts.spawnRadius ?? 0;
    const life = opts.life ?? 1.2;
    const lifeVar = opts.lifeVar ?? 0.4;
    const shrink = opts.shrink ?? 1;
    // One outline per kind, built once and shared — the per-particle scale
    // lives in the transform, so the geometry never needs re-cutting.
    const outlines = new Map<VecShapeKind, Array<[VecPt, VecPt]>>();
    const joins = new Map<VecShapeKind, Float32Array>();
    for (const k of kinds) {
      if (outlines.has(k)) continue;
      const o = particleOutline(k, opts.circleSides ?? 10);
      outlines.set(k, o);
      // Particles FADE, so their outlines need joining as much as any shape —
      // an unjoined one beads at every corner all the way down.
      joins.set(k, segJoins(o));
    }

    for (let i = 0; i < count; i++) {
      const a = opts.even
        ? angle - spread / 2 + spread * ((i + 0.5) / count)
        : angle + (rand() - 0.5) * spread;
      const v = Math.max(0, speed + (rand() - 0.5) * 2 * speedVar);
      const r = Math.max(0.1, size + (rand() - 0.5) * 2 * sizeVar);
      const sx = spawnR > 0 ? opts.x + (rand() - 0.5) * 2 * spawnR : opts.x;
      const sy = spawnR > 0 ? opts.y + (rand() - 0.5) * 2 * spawnR : opts.y;
      const kind = kinds.length === 1 ? kinds[0] : kinds[(rand() * kinds.length) | 0];
      // The cursor lives on the LAYER, not the call, so a per-frame stream
      // keeps walking the wheel instead of restarting on every emit().
      const style = src === undefined ? baseStyle : tintStyle(baseStyle, resolveVecColor(src, this.colorSeq++));
      const f: LiveFragment = {
        x: sx, y: sy, rot: rand() * Math.PI * 2, scale: r,
        vx: Math.cos(a) * v, vy: Math.sin(a) * v,
        spin: (rand() - 0.5) * 2 * (opts.spin ?? 3),
        age: 0, life: Math.max(0.05, life + (rand() - 0.5) * 2 * lifeVar),
        segs: outlines.get(kind)!,
        joins: joins.get(kind)!,
        style,
        drag: opts.drag ?? 0.4,
        glowMul: 1,
        scaleFrom: r,
        scaleTo: r * shrink,
        gravity: opts.gravity ?? 0,
      };
      this.fragments.push(f);
    }
    this.dirty = true;
  }

  /** Advance fragments and trails (Game ticks this). */
  update(dt: number): void {
    if (this.trails.length) {
      this.trails = this.trails.filter((t) => !t.dead);
      for (const t of this.trails) t.step(dt);
    }
    if (this.fields.length) {
      this.fields = this.fields.filter((f) => !f.dead);
      for (const f of this.fields) f.step(dt);
    }
    let removed = false;
    for (let i = this.fragments.length - 1; i >= 0; i--) {
      const f = this.fragments[i];
      f.vy += f.gravity * dt;
      if (!stepFragment(f, dt, f.drag)) {
        this.fragments.splice(i, 1);
        removed = true;
        continue;
      }
      if (f.scaleTo !== f.scaleFrom) {
        const t = Math.min(1, f.age / Math.max(1e-5, f.life));
        f.scale = f.scaleFrom + (f.scaleTo - f.scaleFrom) * t;
      }
    }
    if (removed) this.dirty = true;
  }

  /** Start a frame (same world rect as the sprite batches). */
  begin(viewX: number, viewY: number, viewW: number, viewH: number): void {
    this.dynCount = 0;
    this.dynGlow = 0;
    this.uniformData[0] = viewX;
    this.uniformData[1] = viewY;
    this.uniformData[2] = viewW;
    this.uniformData[3] = viewH;
  }

  /** How wide the widest live glow stamp is (0 = nothing glows) — Game
   * wakes the shared GlowPass with it. Valid after prepare(). */
  glowSize = 0;

  /**
   * Upload everything for this frame: repack static data if dirty, pack the
   * live transform table, upload the dynamic pushes, and measure the glow.
   * Game calls this BEFORE the GlowPass renders (the stamps draw there).
   */
  prepare(): void {
    // Trails become ordinary immediate segments here, so they land after
    // anything the game pushed itself this frame. Give a trail a lower `z`
    // if you need a filled shape to cover it.
    // Starfields go down FIRST and are drawn as a separate span BEHIND the
    // retained shapes — see `backdropCount`.
    for (const f of this.fields) if (!f.dead) f.emit();
    this.backdropCount = this.dynCount;
    for (const t of this.trails) if (!t.dead) t.emit();
    // Reap dead shapes; repack static data only when something changed.
    if (this.dirty) {
      this.shapes = this.shapes.filter((s) => !s.dead);
      this.repackStatic();
      this.dirty = false;
    }
    // Transforms upload every frame — they're the live-mutable part.
    // Slot 0 = identity; shapes then fragments follow in pack order. A WRAPPED
    // shape takes FOUR consecutive slots (itself plus three mirrors), which is
    // why the count is summed rather than just the array length.
    let slots = 1 + this.fragments.length;
    for (const s of this.shapes) slots += s.wrap ? 4 : 1;
    if (slots * XFORM_FLOATS > this.xformData.length) {
      this.xformData = new Float32Array(ceilPow2(slots) * XFORM_FLOATS);
      this.xformBuf.destroy();
      this.xformBuf = this.device.createBuffer({ size: this.xformData.byteLength, usage: BITS.STORAGE | BITS.COPY_DST });
      this.makeBinds();
    }
    const x = this.xformData;
    x[0] = 0; x[1] = 0; x[2] = 0; x[3] = 1; x[4] = 1; x[5] = 1; x[6] = 0; x[7] = 0;
    let slot = 1;
    for (const s of this.shapes) {
      // A pivot is purely a different translation — see shapeOrigin.
      const org = shapeOrigin(s);
      const write = (dx: number, dy: number): void => {
        const o = slot * XFORM_FLOATS;
        x[o] = org.x + dx; x[o + 1] = org.y + dy; x[o + 2] = s.rot; x[o + 3] = s.scale;
        x[o + 4] = s.alpha; x[o + 5] = s.glowMul; x[o + 6] = 0; x[o + 7] = 0;
        slot++;
      };
      write(0, 0);
      if (s.wrap) {
        // Mirror to the FAR side — a shape in the left half ghosts on the
        // right and vice versa, so the copy is always where the wrap needs it.
        // Off-screen mirrors cost a few instances and no bookkeeping, which
        // beats deciding per frame whether each one is needed.
        const dx = s.x < s.wrap.w / 2 ? s.wrap.w : -s.wrap.w;
        const dy = s.y < s.wrap.h / 2 ? s.wrap.h : -s.wrap.h;
        write(dx, 0);
        write(0, dy);
        write(dx, dy);
      }
    }
    for (const f of this.fragments) {
      const o = slot * XFORM_FLOATS;
      x[o] = f.x; x[o + 1] = f.y; x[o + 2] = f.rot; x[o + 3] = f.scale;
      x[o + 4] = fragmentAlpha(f.age, f.life); x[o + 5] = f.glowMul; x[o + 6] = 0; x[o + 7] = 0;
      slot++;
    }
    this.device.queue.writeBuffer(this.xformBuf, 0, x.buffer, 0, slots * XFORM_FLOATS * 4);
    this.device.queue.writeBuffer(this.uniforms, 0, this.uniformData);
    if (this.dynCount > 0) {
      this.device.queue.writeBuffer(this.dynBuf, 0, this.dynData.buffer, 0, this.dynCount * LINE_FLOATS * 4);
    }
    // Measure the widest live glow stamp (glowMul-scaled) for the GlowPass.
    let g = 0;
    for (const s of this.shapes) {
      if (s.style.glow > 0 && s.glowMul > 0) g = Math.max(g, s.style.stampHalf * Math.min(2, s.glowMul));
    }
    for (const f of this.fragments) {
      if (f.style.glow > 0 && f.glowMul > 0) g = Math.max(g, f.style.stampHalf * Math.min(2, f.glowMul));
    }
    if (this.dynGlow > 0) g = Math.max(g, this.dynGlow);
    this.glowSize = g;
  }

  /**
   * Draw the crisp scene lines (static + dynamic, two draws max).
   *
   * `pxW`/`pxH` are the target's pixel size — needed only to turn `clip` into
   * a scissor; omit them and clipping is skipped.
   */
  draw(pass: GPURenderPassEncoder, pxW = 0, pxH = 0): void {
    const sc = this.scissorFor(pxW, pxH);
    if (sc === 'empty') return;
    if (sc) pass.setScissorRect(sc.x, sc.y, sc.w, sc.h);
    // FACES FIRST, and all of them, before any line — the fill pass is what
    // writes depth, so every occluder has to be down before the lines test
    // against it.
    if (this.fillsOn) {
      if (this.fillOpaque > 0) {
        pass.setPipeline(this.fillPipeline);
        pass.setBindGroup(0, this.fillBind);
        pass.draw(this.fillOpaque);
      }
      if (this.fillBlend > 0) {
        pass.setPipeline(this.fillBlendPipeline);
        pass.setBindGroup(0, this.fillBind);
        pass.draw(this.fillBlend, 1, this.fillOpaque);
      }
    }
    // The BACKDROP span of the immediate buffer, before the retained shapes.
    if (this.backdropCount > 0) {
      pass.setPipeline(this.pipeline);
      pass.setBindGroup(0, this.dynBind);
      pass.draw(4, this.backdropCount);
    }
    if (this.staticCount > 0) {
      pass.setPipeline(this.pipeline);
      pass.setBindGroup(0, this.staticBind);
      pass.draw(4, this.staticCount);
    }
    if (this.dynCount > this.backdropCount) {
      pass.setPipeline(this.pipeline);
      pass.setBindGroup(0, this.dynBind);
      pass.draw(4, this.dynCount - this.backdropCount, 0, this.backdropCount);
    }
    // Hand the full rect back — the caller keeps drawing into this pass.
    if (sc) pass.setScissorRect(0, 0, pxW, pxH);
  }

  /** @internal The pixel scissor for `clip`, or null when there is nothing to
   *  clip, or 'empty' when the rect is entirely off-target. */
  private scissorFor(pxW: number, pxH: number): { x: number; y: number; w: number; h: number } | null | 'empty' {
    if (!this.clip || pxW <= 0 || pxH <= 0) return null;
    const u = this.uniformData;
    return clipToScissor(this.clip, u[0], u[1], u[2], u[3], pxW, pxH) ?? 'empty';
  }

  /** Draw the soft glow stamps into the GlowPass's half-res target pass
   * (Game hands this as the extra-stamps callback). Zero-glow segments
   * contribute nothing (brightness multiplies to 0). */
  stampGlow(pass: GPURenderPassEncoder, pxW = 0, pxH = 0): void {
    // Same rect, HALF-res target: the shared maths means the halo is cut at
    // exactly the line's edge instead of bleeding past the window.
    const sc = this.scissorFor(pxW, pxH);
    if (sc === 'empty') return;
    if (sc) pass.setScissorRect(sc.x, sc.y, sc.w, sc.h);
    if (this.staticCount > 0) {
      pass.setPipeline(this.stampPipeline);
      pass.setBindGroup(0, this.staticBind);
      pass.draw(4, this.staticCount);
    }
    if (this.dynCount > 0) {
      pass.setPipeline(this.stampPipeline);
      pass.setBindGroup(0, this.dynBind);
      pass.draw(4, this.dynCount);
    }
    if (sc) pass.setScissorRect(0, 0, pxW, pxH);
  }

  /** Kill everything (scene teardown). */
  clear(): void {
    this.shapes = [];
    this.fragments = [];
    this.trails = [];
    this.fields = [];
    this.dirty = true;
  }

  /** (Re)create GPU objects — device-loss recovery. */
  rebuild(device: GPUDevice): void {
    this.device = device;
    this.layout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_VERTEX, buffer: { type: 'read-only-storage' } },
        { binding: 2, visibility: BITS.STAGE_VERTEX, buffer: { type: 'read-only-storage' } },
      ],
    });
    const module = shaderModule(device, buildLineWGSL(false), 'VectorLayer');
    this.pipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: { module, entryPoint: 'vs' },
      fragment: {
        module,
        entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
            alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
          },
        }],
      },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'less-equal' },
      primitive: { topology: 'triangle-strip' },
    });
    // The glow-stamp variant renders into the GlowPass's half-res target:
    // additive (overlaps sum), no depth attachment on that pass.
    const stampModule = shaderModule(device, buildLineWGSL(true), 'VectorLayer stamp');
    this.stampPipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: { module: stampModule, entryPoint: 'vs' },
      fragment: {
        module: stampModule,
        entryPoint: 'fs',
        targets: [{
          format: this.format,
          // MAX, not additive: overlapping round caps at every joint (and
          // self-crossing outlines) saturate instead of summing into knots.
          blend: {
            color: { operation: 'max', srcFactor: 'one', dstFactor: 'one' },
            alpha: { operation: 'max', srcFactor: 'one', dstFactor: 'one' },
          },
        }],
      },
      primitive: { topology: 'triangle-strip' },
    });
    // The FILL pipelines. Opaque faces write depth (they are the occluders);
    // translucent ones only test it — a see-through face that stamped depth
    // would punch a hole in everything behind it.
    const fillModule = shaderModule(device, buildFillWGSL(), 'VectorLayer fill');
    const fillTargets: GPUColorTargetState[] = [{
      format: this.format,
      blend: {
        color: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
        alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
      },
    }];
    const fillLayout = device.createPipelineLayout({ bindGroupLayouts: [this.layout] });
    this.fillPipeline = device.createRenderPipeline({
      layout: fillLayout,
      vertex: { module: fillModule, entryPoint: 'vs' },
      fragment: { module: fillModule, entryPoint: 'fs', targets: fillTargets },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: true, depthCompare: 'less-equal' },
      primitive: { topology: 'triangle-list' },
    });
    this.fillBlendPipeline = device.createRenderPipeline({
      layout: fillLayout,
      vertex: { module: fillModule, entryPoint: 'vs' },
      fragment: { module: fillModule, entryPoint: 'fs', targets: fillTargets },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'less-equal' },
      primitive: { topology: 'triangle-list' },
    });
    this.uniforms = device.createBuffer({ size: 16, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.fillBuf = device.createBuffer({ size: this.fillData.byteLength, usage: BITS.STORAGE | BITS.COPY_DST });
    this.staticBuf = device.createBuffer({ size: this.staticData.byteLength, usage: BITS.STORAGE | BITS.COPY_DST });
    this.dynBuf = device.createBuffer({ size: this.dynData.byteLength, usage: BITS.STORAGE | BITS.COPY_DST });
    this.xformBuf = device.createBuffer({ size: this.xformData.byteLength, usage: BITS.STORAGE | BITS.COPY_DST });
    this.makeBinds();
    this.dirty = true;                 // re-upload static data on the new device
  }

  private makeBinds(): void {
    const mk = (buf: GPUBuffer): GPUBindGroup => this.device.createBindGroup({
      layout: this.layout,
      entries: [
        { binding: 0, resource: { buffer: this.uniforms } },
        { binding: 1, resource: { buffer: buf } },
        { binding: 2, resource: { buffer: this.xformBuf } },
      ],
    });
    this.staticBind = mk(this.staticBuf);
    this.dynBind = mk(this.dynBuf);
    this.fillBind = mk(this.fillBuf);
  }

  private pushDyn(
    x0: number, y0: number, x1: number, y1: number, p: PackedStyle, slot: number,
    j?: Float32Array | null, ji = 0,
  ): void {
    if ((this.dynCount + 1) * LINE_FLOATS > this.dynData.length) {
      const next = new Float32Array(this.dynData.length * 2);
      next.set(this.dynData);
      this.dynData = next;
      this.dynBuf.destroy();
      this.dynBuf = this.device.createBuffer({ size: this.dynData.byteLength, usage: BITS.STORAGE | BITS.COPY_DST });
      this.makeBinds();
    }
    writeSeg(this.dynData, this.dynCount * LINE_FLOATS, x0, y0, x1, y1, p, slot, j, ji);
    this.dynCount++;
  }

  /** @internal Are solid faces on this frame? `fills` overrides the auto-check. */
  private get fillsOn(): boolean {
    if (this.fills !== null) return this.fills;
    for (const s of this.shapes) if (!s.dead && s.filled) return true;
    return false;
  }

  /**
   * @internal Pack every filled shape's triangles. OPAQUE faces go first and
   * write depth (they are the occluders); translucent ones follow and do not,
   * because a see-through face that still stamped depth would punch a hole in
   * everything behind it.
   */
  private repackFills(): void {
    const live = this.shapes.filter((s) => !s.dead && s.filled);
    let n = 0;
    for (const s of live) n += (s.fillVerts.length / 6) * (s.wrap ? 4 : 1);
    if (n * FILL_FLOATS > this.fillData.length) {
      this.fillData = new Float32Array(ceilPow2(n) * FILL_FLOATS);
      this.fillBuf.destroy();
      this.fillBuf = this.device.createBuffer({ size: this.fillData.byteLength, usage: BITS.STORAGE | BITS.COPY_DST });
      this.makeBinds();
    }
    const d = this.fillData;
    let i = 0;
    // Two passes over the same list so the buffer is [opaque…, translucent…].
    for (const wantOpaque of [true, false]) {
      for (const s of live) {
        const opaque = s.fillVerts[5] >= 0.999 && s.alpha >= 0.999;
        if (opaque !== wantOpaque) continue;
        const slot = this.slotOf.get(s) ?? 0;
        const copies = s.wrap ? 4 : 1;
        for (let c = 0; c < copies; c++) {
          for (let v = 0; v < s.fillVerts.length; v += 6) {
            const o = i * FILL_FLOATS;
            d[o] = s.fillVerts[v]; d[o + 1] = s.fillVerts[v + 1];
            d[o + 2] = s.style.z; d[o + 3] = slot + c;
            d[o + 4] = s.fillVerts[v + 2]; d[o + 5] = s.fillVerts[v + 3];
            d[o + 6] = s.fillVerts[v + 4]; d[o + 7] = s.fillVerts[v + 5];
            i++;
          }
        }
      }
      if (wantOpaque) this.fillOpaque = i;
    }
    this.fillBlend = i - this.fillOpaque;
    if (i > 0) this.device.queue.writeBuffer(this.fillBuf, 0, d.buffer, 0, i * FILL_FLOATS * 4);
  }

  /** @internal Shape → its first transform slot, so fills and lines agree. */
  private slotOf = new Map<VectorShape, number>();

  private repackStatic(): void {
    let n = 0;
    for (const s of this.shapes) n += s.segs.length * (s.wrap ? 4 : 1);
    for (const f of this.fragments) n += f.segs.length;
    if (n * LINE_FLOATS > this.staticData.length) {
      this.staticData = new Float32Array(ceilPow2(n) * LINE_FLOATS);
      this.staticBuf.destroy();
      this.staticBuf = this.device.createBuffer({ size: this.staticData.byteLength, usage: BITS.STORAGE | BITS.COPY_DST });
      this.makeBinds();
    }
    let i = 0;
    let slot = 1;
    this.slotOf.clear();
    for (const s of this.shapes) {
      this.slotOf.set(s, slot);
      const copies = s.wrap ? 4 : 1;
      for (let c = 0; c < copies; c++) {
        let k = 0;
        for (const [a, b] of s.segs) {
          writeSeg(this.staticData, i * LINE_FLOATS, a.x, a.y, b.x, b.y,
            s.segStyles?.[k] ?? s.style, slot, s.joins, k * 4);
          i++; k++;
        }
        slot++;
      }
    }
    for (const f of this.fragments) {
      let k = 0;
      for (const [a, b] of f.segs) {
        writeSeg(this.staticData, i * LINE_FLOATS, a.x, a.y, b.x, b.y, f.style, slot, f.joins, k * 4);
        i++; k++;
      }
      slot++;
    }
    this.staticCount = i;
    if (i > 0) this.device.queue.writeBuffer(this.staticBuf, 0, this.staticData.buffer, 0, i * LINE_FLOATS * 4);
    this.repackFills();
  }
}

function writeSeg(
  d: Float32Array, o: number, x0: number, y0: number, x1: number, y1: number,
  p: PackedStyle, slot: number, j?: Float32Array | null, ji = 0,
): void {
  d[o] = x0; d[o + 1] = y0; d[o + 2] = x1; d[o + 3] = y1;
  d[o + 4] = p.coreHalf; d[o + 5] = p.stampHalf; d[o + 6] = p.z; d[o + 7] = slot;
  d[o + 8] = p.dash; d[o + 9] = p.glow; d[o + 10] = p.capped; d[o + 11] = p.dwell;
  d[o + 12] = p.c0[0]; d[o + 13] = p.c0[1]; d[o + 14] = p.c0[2]; d[o + 15] = p.c0[3];
  d[o + 16] = p.c1[0]; d[o + 17] = p.c1[1]; d[o + 18] = p.c1[2]; d[o + 19] = p.c1[3];
  // Join planes. All zero = a lone segment or a free end: round caps, no cut.
  d[o + 20] = j ? j[ji] : 0; d[o + 21] = j ? j[ji + 1] : 0;
  d[o + 22] = j ? j[ji + 2] : 0; d[o + 23] = j ? j[ji + 3] : 0;
}

function ceilPow2(n: number): number {
  let v = 1024;
  while (v < n) v *= 2;
  return v;
}
