// GENERATED VECTOR GEOMETRY — the constructions the classics are built from.
//
// `generatePolygon` (asteroid rocks) and `generateTerrain` (landscapes) live in
// vectorkit; this is the CIRCULAR half of the family:
//
// - arcs, and rings cut into individually destructible sections — Star Castle's
//   three counter-rotating shields, Tempest's rims, Omega Race's barriers, and
//   every radar sweep ever drawn.
// - the TUBE: a whole genre's playfield. Lanes running away to a vanishing
//   point, a near rim the player crawls around and a far rim the enemies climb
//   out of.
//
// Runtime-import-free (the one import is a `type`, erased at build), so both
// backends and the kit can share it with no chance of a cycle. Pure maths over
// plain `{x, y}` data. The 2D world is Y-DOWN, so angles run CLOCKWISE and
// -PI/2 points straight up.

import type { VecPt } from './vector.js';

const TAU = Math.PI * 2;

/**
 * How many segments an arc of this sweep needs to read as a curve — one per
 * ~11°, minimum 1. Every arc here uses it when `steps` is omitted.
 *
 * It is purely ANGULAR, so it takes no view of radius: a huge circle gets the
 * same 32 segments as a tiny one and reads as faceted, while a narrow ring
 * section gets only two. Pass an explicit `steps` in both cases — up for a
 * smooth curve at a large radius, down for deliberate chunky chords.
 */
export function arcSteps(sweep: number): number {
  return Math.max(1, Math.ceil(Math.abs(sweep) / (Math.PI / 16)));
}

/**
 * Points along a circular arc from `from` to `to` radians — the retained path.
 *
 * ```ts
 * const shield = game.vector.shape(
 *   vectorKit.arcPoints(0, 0, 120, -0.4, 0.4),
 *   { x: cx, y: cy, closed: false, color: '#41d6ff' },
 * );
 * ```
 *
 * Returns `steps + 1` points. Build the arc about the ORIGIN and put the centre
 * in the shape's `x`/`y` if you want it to rotate — a shape spins about its own
 * origin, so an arc built at `(cx, cy)` would orbit instead of turning in place.
 *
 * `layer.arc()` is the immediate shortcut over the top of this.
 */
export function arcPoints(
  cx: number, cy: number, r: number,
  from: number, to: number, steps?: number,
): Array<{ x: number; y: number }> {
  const sweep = to - from;
  const n = Math.max(1, Math.round(steps ?? arcSteps(sweep)));
  const out: Array<{ x: number; y: number }> = [];
  for (let i = 0; i <= n; i++) {
    const a = from + sweep * (i / n);
    out.push({ x: cx + Math.cos(a) * r, y: cy + Math.sin(a) * r });
  }
  return out;
}

/** Tuning for `ringSections`. */
export interface RingSectionOptions {
  /** Gap between neighbouring sections in radians (default 0.14). */
  gap?: number;
  /** Segments per section (default: derived from the sweep by `arcSteps`). */
  steps?: number;
  /** Where the first section starts (default -PI/2 — straight up). */
  from?: number;
  /** Total sweep the sections divide (default a full turn). */
  span?: number;
}

/** One section of a segmented ring. */
export interface RingSection {
  /** The arc outline — hand it straight to `shape()` or `poly()`. */
  points: Array<{ x: number; y: number }>;
  /** Start and end angle in radians, MONOTONIC (`to` > `from`, never wrapped)
   *  so `arcHit` can test the span without unwrapping anything. */
  from: number;
  to: number;
  /** 0-based, clockwise from `opts.from`. */
  index: number;
}

/**
 * Cut a ring into `count` separately drawable sections — Star Castle's shields.
 *
 * ```ts
 * const shields = vectorKit.ringSections(0, 0, 140, 12, { gap: 0.16 })
 *   .map((s) => ({ ...s, shape: game.vector.shape(s.points, { x: cx, y: cy, closed: false }) }));
 * ```
 *
 * Each section is its OWN point array, so each becomes its own `VectorShape`
 * and can `shatter()` while its neighbours keep turning. Build at the origin
 * and carry the centre on the shapes, so the whole ring rotates as one.
 */
export function ringSections(
  cx: number, cy: number, r: number, count: number,
  opts: RingSectionOptions = {},
): RingSection[] {
  const gap = opts.gap ?? 0.14;
  const from = opts.from ?? -Math.PI / 2;
  const span = opts.span ?? TAU;
  const n = Math.max(1, Math.round(count));
  const pitch = span / n;
  const arc = Math.max(0, pitch - gap);
  const out: RingSection[] = [];
  for (let i = 0; i < n; i++) {
    const a0 = from + i * pitch + gap / 2;
    const a1 = a0 + arc;
    out.push({ points: arcPoints(cx, cy, r, a0, a1, opts.steps), from: a0, to: a1, index: i });
  }
  return out;
}

/**
 * Is `(px, py)` ON an arc — within `tol` of the radius AND inside the sweep?
 *
 * The hit test segmented rings need: a shot only kills the shield section it
 * actually crossed. Test in the ring's LOCAL space — subtract the centre and
 * rotate the point by `-ring.rot` first, so a spinning ring needs no
 * per-section bookkeeping.
 */
export function arcHit(
  cx: number, cy: number, r: number,
  from: number, to: number,
  px: number, py: number, tol = 6,
): boolean {
  const dx = px - cx, dy = py - cy;
  if (Math.abs(Math.hypot(dx, dy) - r) > tol) return false;
  const sweep = Math.abs(to - from);
  if (sweep >= TAU) return true;
  const lo = Math.min(from, to);
  let a = (Math.atan2(dy, dx) - lo) % TAU;
  if (a < 0) a += TAU;
  return a <= sweep;
}

// ─────────────────────────────────────────────────────────────────────────────
// THE TUBE — Tempest's playfield, and the whole genre that followed it.
//
// A web is two copies of one silhouette: a big NEAR rim at the screen plane and
// a small FAR rim shrunk toward a vanishing point, joined by SPOKES. Everything
// else is bookkeeping on top of that — the player crawls the near rim, enemies
// climb a lane out of the far one, and everything in between interpolates.
//
// The lanes are the unit of play, not the vertices: lane `i` is the strip
// between rim vertex `i` and `i + 1`. `laneAt(lane, t)` is the whole gameplay
// surface — where a thing sits, which way it faces, and how big it should be
// drawn — for `t` from 0 (on the near rim, in the player's face) to 1 (at the
// far rim, just spawned).
// ─────────────────────────────────────────────────────────────────────────────

/** A web silhouette. `vee` is the open one; the rest close into a loop. */
export type TubeProfile = 'circle' | 'square' | 'plus' | 'vee' | 'star';

/** Unit-space outlines, fitted to roughly -1..1. `circle` is generated
 *  analytically instead (an exact ring beats a resampled polygon). */
const PROFILES: Record<Exclude<TubeProfile, 'circle'>, { pts: VecPt[]; closed: boolean }> = {
  square: {
    pts: [{ x: -1, y: -1 }, { x: 1, y: -1 }, { x: 1, y: 1 }, { x: -1, y: 1 }],
    closed: true,
  },
  plus: {
    pts: [
      { x: -0.38, y: -1 }, { x: 0.38, y: -1 }, { x: 0.38, y: -0.38 }, { x: 1, y: -0.38 },
      { x: 1, y: 0.38 }, { x: 0.38, y: 0.38 }, { x: 0.38, y: 1 }, { x: -0.38, y: 1 },
      { x: -0.38, y: 0.38 }, { x: -1, y: 0.38 }, { x: -1, y: -0.38 }, { x: -0.38, y: -0.38 },
    ],
    closed: true,
  },
  vee: {
    pts: [{ x: -1, y: -0.85 }, { x: 0, y: 0.9 }, { x: 1, y: -0.85 }],
    closed: false,
  },
  star: {
    pts: Array.from({ length: 10 }, (_, i) => {
      const a = -Math.PI / 2 + (i / 10) * TAU;
      const r = i % 2 === 0 ? 1 : 0.45;
      return { x: Math.cos(a) * r, y: Math.sin(a) * r };
    }),
    closed: true,
  },
};

/** Edge lengths of a path (plus the closing edge), and their total. */
function edgeLengths(pts: readonly VecPt[]): { len: number[]; total: number } {
  const len: number[] = [];
  let total = 0;
  for (let i = 1; i < pts.length; i++) {
    const l = Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y);
    len.push(l);
    total += l;
  }
  return { len, total };
}

/**
 * Turn a silhouette into `n` lane boundaries, KEEPING EVERY CORNER.
 *
 * Equal-arc-length sampling is the obvious approach and it is wrong here: with
 * 12 lanes on a 12-corner cross, not one sample lands on a corner and the web
 * comes out as a rounded blob instead of a plus. Tempest's shapes are crisp,
 * and their lane widths vary — that is the authentic trade, and the right one,
 * because the silhouette is the whole point of choosing a profile.
 *
 * So: each edge gets at least one lane, the rest are apportioned by edge length
 * (largest remainder), and each edge subdivides evenly within itself. Corners
 * therefore always fall on a lane boundary. Below one lane per edge the shape
 * cannot survive at all, so that case falls back to equal-arc sampling.
 *
 * A closed path yields `n` points, an open one `n + 1`.
 */
function sampleProfile(path: readonly VecPt[], closed: boolean, n: number): VecPt[] {
  const pts = closed ? [...path, path[0]] : [...path];
  const { len } = edgeLengths(pts);
  const edges = len.length;
  if (n < edges) return resamplePath(path, closed, n);

  // Largest-remainder apportionment, floored at one lane per edge.
  const total = len.reduce((a, b) => a + b, 0);
  const ideal = len.map((l) => (total > 0 ? (l / total) * n : n / edges));
  const count = ideal.map((v) => Math.max(1, Math.floor(v)));
  let used = count.reduce((a, b) => a + b, 0);
  const byFrac = ideal
    .map((v, i) => ({ i, frac: v - Math.floor(v) }))
    .sort((a, b) => b.frac - a.frac);
  for (let k = 0; used < n; k++, used++) count[byFrac[k % edges].i]++;
  while (used > n) {
    let big = 0;
    for (let i = 1; i < edges; i++) if (count[i] > count[big]) big = i;
    if (count[big] <= 1) break;                      // can't go below one per edge
    count[big]--;
    used--;
  }

  const out: VecPt[] = [];
  for (let e = 0; e < edges; e++) {
    const a = pts[e], b = pts[e + 1];
    for (let j = 0; j < count[e]; j++) {
      const f = j / count[e];
      out.push({ x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f });
    }
  }
  if (!closed) out.push({ x: pts[pts.length - 1].x, y: pts[pts.length - 1].y });
  return out;
}

/**
 * Walk a path and drop `n` points at EQUAL arc length, corners be damned — the
 * fallback for when there are fewer lanes than the profile has edges. An open
 * path gets `n + 1` points (both ends included); a closed one gets `n`.
 */
function resamplePath(path: readonly VecPt[], closed: boolean, n: number): VecPt[] {
  const pts = closed ? [...path, path[0]] : [...path];
  const { len: segLen, total } = edgeLengths(pts);
  // Either way the step is total/n: a closed loop takes n of them and joins
  // back, an open path takes n + 1 and lands exactly on the far end.
  const wanted = closed ? n : n + 1;
  const out: VecPt[] = [];
  for (let k = 0; k < wanted; k++) {
    let d = total * (k / n);
    if (d >= total) { out.push({ x: pts[pts.length - 1].x, y: pts[pts.length - 1].y }); continue; }
    let i = 0;
    while (i < segLen.length && d > segLen[i]) { d -= segLen[i]; i++; }
    const a = pts[i], b = pts[i + 1] ?? pts[i];
    const f = segLen[i] > 0 ? d / segLen[i] : 0;
    out.push({ x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f });
  }
  return out;
}

/** Tuning for `generateTube`. */
export interface TubeOptions {
  /** Playable lanes around the web (default 16). */
  lanes?: number;
  /** Rim silhouette (default 'circle'). */
  profile?: TubeProfile;
  /** Near-rim centre in world units (default 0, 0). */
  x?: number;
  y?: number;
  /** Near-rim radius (default 300) — the rim in the player's face. */
  near?: number;
  /** Far-rim radius (default `near * 0.3`). Smaller = a deeper tube. */
  far?: number;
  /** The vanishing point — the far rim's centre (default the near centre).
   *  Offset it and the tube leans away instead of receding straight back. */
  vanishX?: number;
  vanishY?: number;
  /** Spin the whole web about its centre, radians (default 0). */
  rot?: number;
  /** Force the loop open or closed. Default: the profile decides ('vee' is
   *  open, the rest close), which is also whether lane 0 and lane n-1 are
   *  neighbours — i.e. whether the player wraps. */
  closed?: boolean;
}

/** Where something on a lane sits, faces, and how big to draw it. */
export interface LanePose {
  x: number;
  y: number;
  /** Facing OUT of the tube (from the far rim toward the near one) — the
   *  direction an enemy is travelling, and the way a rim ship points. */
  angle: number;
  /** 1 on the near rim, `far / near` at the vanishing end. Multiply sprite or
   *  line size by it and things shrink correctly as they climb. */
  scale: number;
}

/** A generated web. `nearRim`/`farRim`/`spokes` draw it; `laneAt` plays it. */
export interface Tube {
  /** Playable lanes (NOT the vertex count — an open web has one more vertex). */
  lanes: number;
  closed: boolean;
  nearRim: VecPt[];
  farRim: VecPt[];
  /** Near vertex → far vertex, one per rim vertex. */
  spokes: Array<[VecPt, VecPt]>;
  /** Rim VERTEX `i` at depth `t` (0 = near, 1 = far). Wraps when closed. */
  rimAt(i: number, t: number): VecPt;
  /**
   * Rim position at a CONTINUOUS vertex parameter — `u` 0..lanes, sliding along
   * the rim rather than hopping vertex to vertex. `rimPointAt(2.5, 0)` is
   * halfway along the near rim's third edge. Wraps or clamps like everything
   * else. This is the glide primitive; `laneAt` is built on it.
   */
  rimPointAt(u: number, t: number): VecPt;
  /**
   * The middle of LANE `lane` at depth `t` — position, facing and scale.
   *
   * `lane` is CONTINUOUS: whole numbers sit in the middle of a lane, and
   * everything between glides smoothly along the rim (round corners included),
   * so a claw can slide rather than snap. `t` runs 0 (near rim) to 1 (far).
   */
  laneAt(lane: number, t: number): LanePose;
  /** Bring a lane position into range — wraps on a closed web, clamps on an
   *  open one. Feed a fractional lane through this after moving it. */
  wrapLane(v: number): number;
  /** Signed lane distance `from` → `to`, taking the SHORT way round a closed
   *  web (lane 15 → lane 0 of 16 is +1, not -15). Steering and AI both need
   *  this; getting it wrong makes things scurry the long way round. */
  laneDelta(from: number, to: number): number;
  /** Move a lane position toward `to` by at most `maxStep` lanes, the short way
   *  round, never overshooting — one frame of a smooth glide.
   *
   *  Steps in LANES, so on a profile whose lanes differ in length this changes
   *  speed as it goes. Use `glide` to move at a constant speed instead. */
  stepLane(from: number, to: number, maxStep: number): number;

  // ── Moving at a constant SPEED ─────────────────────────────────────────────
  // A lane is a slot, not a distance. On a star the spike edges are twice the
  // length of the notches between them, so anything advancing at a fixed
  // lanes-per-second visibly doubles its speed across a spike and halves it
  // again on the way out. These four convert between lane numbers and rim
  // DISTANCE in world units, which is what "a set speed" actually means.

  /** Total near-rim length in world units — the closing edge included when the
   *  web is closed. `perimeter / speed` is how long one lap takes. */
  perimeter: number;
  /** Near-rim length of lane `i` in world units. Equal for a circle or a
   *  square; 2:1 between a star's longest and shortest. */
  laneLength(i: number): number;
  /**
   * Move a lane position along the rim by `dist` WORLD UNITS, signed, wrapping
   * or clamping like `wrapLane`. This is the constant-speed step:
   *
   * ```ts
   * lane = web.advance(lane, dir * 880 * dt);   // 880 world units per second,
   * ```                                         // on every profile alike
   *
   * where `wrapLane(lane + dir * n * dt)` would have moved at `n` lanes per
   * second and so sped up and slowed down around the rim.
   */
  advance(lane: number, dist: number): number;
  /** Signed rim DISTANCE `from` → `to` in world units, the short way round —
   *  `laneDelta` measured in world units instead of lanes. */
  arcDelta(from: number, to: number): number;
  /** Move toward `to` by at most `maxDist` WORLD UNITS, the short way round,
   *  never overshooting. The constant-speed twin of `stepLane`. */
  glide(from: number, to: number, maxDist: number): number;

  // ── The hidden circle: which way is "round" ────────────────────────────────
  // A silhouette has no left and right, and asking its line segments which way
  // they point is a losing game — the answer changes at every corner. So the
  // rim is ALSO parameterised by angle about the web's centre: a circle that is
  // never drawn, used purely to gauge direction. Steering becomes "go round the
  // circle", identically on a disc, a square or a star, with no segment checks
  // anywhere. On an OPEN web the circle stops where the shape does.

  /** Where `lane` sits on the circle, radians about the web's centre. */
  angleOf(lane: number): number;
  /** The lane at a given angle on the circle — the inverse of `angleOf`, and
   *  the whole of mouse steering: `laneAtAngle(atan2(my - cy, mx - cx))`. */
  laneAtAngle(angle: number): number;
  /** Turn `dAngle` radians round the circle — **positive is clockwise on
   *  screen**, on every profile alike. Clamps at the ends of an open web.
   *
   *  This paces by ANGLE, so on a star the claw covers more ground near a spike
   *  tip than in a notch. `steer` paces by DISTANCE instead and holds one
   *  speed — prefer it for a player-controlled ship. */
  turn(lane: number, dAngle: number): number;
  /** The angles the rim actually spans. A full turn when closed; on an open web
   *  the reachable arc, past which `turn` and `laneAtAngle` clamp. */
  angleSpan: { from: number; to: number };

  // ── Where the ship goes, and which way the player's keys point ─────────────

  /** The lane at the BOTTOM of the web — where a tube game's ship starts.
   *
   *  Not a detail: Tempest and everything after it put the ship at the bottom
   *  middle, and the whole feel of the controls is calibrated from there. Start
   *  it at the top and every profile plays inverted. */
  bottom: number;
  /**
   * Move a ship `dist` world units the way the PLAYER reads it — **positive is
   * to their right** — at one constant speed whatever the rim is doing.
   *
   * ```ts
   * lane = web.steer(lane, dir * 880 * dt);      // dir: -1 left, +1 right
   * ```
   *
   * This is `advance` with the sign sorted out. Some silhouettes wind clockwise
   * on screen and some anticlockwise, so "forward along the path" is rightward
   * on one and leftward on the next; `steer` folds in that single build-time
   * winding so left is left on all of them.
   *
   * Read at the BOTTOM, where the ship lives. A ring has no global left and
   * right — carry on far enough round and the ship is climbing the far side, at
   * which point the screen direction is reversed. Every tube game does this.
   */
  steer(lane: number, dist: number): number;
  /** The fractional lane nearest a world point — mouse and spinner control.
   *  `laneAt(laneOf(x, y), 0)` lands on the rim under the cursor. */
  laneOf(x: number, y: number): number;
}

/**
 * Build a tube playfield.
 *
 * ```ts
 * const web = vectorKit.generateTube({ x: cx, y: cy, near: 300, far: 80, lanes: 16, profile: 'star' });
 * game.vector.poly(web.nearRim, { color: '#41d6ff' }, web.closed);
 * game.vector.poly(web.farRim,  { color: '#2a4a7a' }, web.closed);
 * for (const [a, b] of web.spokes) game.vector.seg(a.x, a.y, b.x, b.y, { color: '#2a4a7a' });
 *
 * const p = web.laneAt(playerLane, 0);        // the claw, on the near rim
 * const e = web.laneAt(enemyLane, enemyT);    // a flipper, climbing out
 * ```
 *
 * The geometry is STATIC — generate once per level, not per frame. Only
 * `laneAt` runs in the loop, and it is a lerp and an atan2.
 */
export function generateTube(opts: TubeOptions = {}): Tube {
  const lanes = Math.max(2, Math.round(opts.lanes ?? 16));
  const profile = opts.profile ?? 'circle';
  const closed = opts.closed ?? (profile !== 'vee');
  const x = opts.x ?? 0;
  const y = opts.y ?? 0;
  const near = opts.near ?? 300;
  const far = opts.far ?? near * 0.3;
  const vx = opts.vanishX ?? x;
  const vy = opts.vanishY ?? y;
  const rot = opts.rot ?? 0;

  // One unit silhouette, sampled into evenly-spaced lane boundaries…
  let unit: VecPt[];
  if (profile === 'circle') {
    // An exact ring — closed sweeps the full turn in `lanes` steps, open sweeps
    // a half-turn and keeps both ends (a bowl the player can fall off).
    const span = closed ? TAU : Math.PI;
    unit = Array.from({ length: closed ? lanes : lanes + 1 }, (_, i) => {
      const a = -Math.PI / 2 + span * (i / lanes);
      return { x: Math.cos(a), y: Math.sin(a) };
    });
  } else {
    unit = sampleProfile(PROFILES[profile].pts, closed, lanes);
  }
  // …then stamped twice: big at the screen plane, small at the vanishing point.
  const cr = Math.cos(rot), sr = Math.sin(rot);
  const place = (p: VecPt, cx: number, cy: number, r: number): VecPt => ({
    x: cx + (p.x * cr - p.y * sr) * r,
    y: cy + (p.x * sr + p.y * cr) * r,
  });
  const nearRim = unit.map((p) => place(p, x, y, near));
  const farRim = unit.map((p) => place(p, vx, vy, far));
  const spokes: Array<[VecPt, VecPt]> = nearRim.map((p, i) => [p, farRim[i]]);

  const n = nearRim.length;
  const rimAt = (i: number, t: number): VecPt => {
    const k = closed ? ((i % n) + n) % n : Math.max(0, Math.min(n - 1, i));
    const a = nearRim[k], b = farRim[k];
    return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
  };

  // A CONTINUOUS walk of the rim. Everything below is expressed through this,
  // which is what makes fractional lanes glide instead of snap: `u` is a
  // position along the vertex chain, so sliding it moves along the actual
  // edges and turns each corner properly rather than cutting across it.
  const rimPointAt = (u: number, t: number): VecPt => {
    const w = closed ? ((u % lanes) + lanes) % lanes : Math.max(0, Math.min(lanes, u));
    const i = Math.floor(w);
    const f = w - i;
    const a = rimAt(i, t), b = rimAt(i + 1, t);
    return { x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f };
  };

  const wrapLane = (v: number): number => (closed
    ? ((v % lanes) + lanes) % lanes
    : Math.max(0, Math.min(lanes - 1, v)));

  const laneDelta = (from: number, to: number): number => {
    const d = to - from;
    if (!closed) return d;
    let m = d % lanes;
    if (m > lanes / 2) m -= lanes;
    if (m < -lanes / 2) m += lanes;
    return m;
  };

  // How long each lane actually is, and a running total, so a lane number can
  // be converted to a distance along the rim and back. Measured on the NEAR rim
  // — that is the surface the player moves on; the far rim is the same shape
  // scaled, so the ratios match anyway.
  const laneLen: number[] = [];
  const cum: number[] = [0];
  for (let i = 0; i < lanes; i++) {
    const a = rimPointAt(i, 0), b = rimPointAt(i + 1, 0);
    const l = Math.hypot(b.x - a.x, b.y - a.y);
    laneLen.push(l);
    cum.push(cum[i] + l);
  }
  const perimeter = cum[lanes];

  /** Lane number → distance along the rim. */
  const arcOf = (lane: number): number => {
    const w = wrapLane(lane);
    const i = Math.min(lanes - 1, Math.floor(w));
    return cum[i] + (w - i) * laneLen[i];
  };
  /** Distance along the rim → lane number. */
  const laneOfArc = (s: number): number => {
    const d = closed
      ? ((s % perimeter) + perimeter) % perimeter
      : Math.max(0, Math.min(perimeter, s));
    let i = 0;
    while (i < lanes - 1 && d >= cum[i + 1]) i++;
    return laneLen[i] > 0 ? i + (d - cum[i]) / laneLen[i] : i;
  };

  const advance = (lane: number, dist: number): number =>
    wrapLane(laneOfArc(arcOf(lane) + dist));

  const arcDelta = (from: number, to: number): number => {
    let d = arcOf(to) - arcOf(from);
    if (!closed) return d;
    if (d > perimeter / 2) d -= perimeter;
    if (d < -perimeter / 2) d += perimeter;
    return d;
  };

  // ── The hidden circle ──────────────────────────────────────────────────────
  // Steering needs ONE unambiguous notion of "round" that owes nothing to the
  // silhouette. So the whole rim — every profile, every corner — is also
  // parameterised by ANGLE about the web's centre: a circle that is never drawn
  // and exists purely to say which way round is which. No tangents, no
  // per-segment direction guessing, no special case at a corner.
  //
  // A table of the unwrapped angle at each rim vertex is all it takes. Every
  // profile here is star-shaped about its centre — one rim point per ray — so
  // this angle runs MONOTONICALLY along the path, which is the property that
  // makes the two parameterisations agree: moving forward along the rim is
  // always moving forward round the circle, so `advance` steers as cleanly as
  // `turn` does and neither can double back.
  const ang: number[] = [];
  for (let k = 0; k <= lanes; k++) {
    const p = rimPointAt(k, 0);
    const raw = Math.atan2(p.y - y, p.x - x);
    if (k === 0) { ang.push(raw); continue; }
    let d = raw - ang[k - 1];
    while (d > Math.PI) d -= TAU;
    while (d < -Math.PI) d += TAU;
    ang.push(ang[k - 1] + d);
  }
  // Which way the path winds, so the table can be read as strictly increasing.
  const wind = ang[lanes] >= ang[0] ? 1 : -1;

  /** Where a lane sits on the circle, unwrapped to match the table. */
  const angleOf = (lane: number): number => {
    const u = wrapLane(lane) + 0.5;
    const p = rimPointAt(u, 0);
    let a = Math.atan2(p.y - y, p.x - x);
    const k = Math.min(lanes - 1, Math.floor(u));
    while (a - ang[k] > Math.PI) a -= TAU;
    while (ang[k] - a > Math.PI) a += TAU;
    return a;
  };

  /** The lane sitting at a given angle on the circle — the inverse. */
  const laneAtAngle = (a: number): number => {
    const lo = ang[0] * wind, hi = ang[lanes] * wind;
    let t = a * wind;
    if (closed) t = lo + ((((t - lo) % TAU) + TAU) % TAU);
    else {
      // An OPEN web has ends, and past them the claw stops rather than carrying
      // on round the circle into thin air. But clamp the RIGHT representative:
      // an open span runs less than a full turn, so at most one of `t ± 2PI k`
      // can lie inside it — take the one nearest the middle of the span, and
      // only clamp when the angle is genuinely off the end of the shape.
      t += Math.round(((lo + hi) / 2 - t) / TAU) * TAU;
      t = Math.max(lo, Math.min(hi, t));
    }
    let k = 0;
    while (k < lanes - 1 && t > ang[k + 1] * wind) k++;
    // Exact position on edge `k`: intersect the ray at angle `a` with it.
    // Interpolating the angle itself would sag away from the straight edge.
    const A = rimPointAt(k, 0), B = rimPointAt(k + 1, 0);
    const ax = A.x - x, ay = A.y - y;
    const dx = Math.cos(t * wind), dy = Math.sin(t * wind);
    const den = (ax - (B.x - x)) * dy - (ay - (B.y - y)) * dx;
    const f = Math.abs(den) > 1e-12 ? (ax * dy - ay * dx) / den : 0;
    return wrapLane(k + Math.max(0, Math.min(1, f)) - 0.5);
  };

  return {
    lanes, closed, nearRim, farRim, spokes, rimAt, rimPointAt, wrapLane, laneDelta,
    perimeter, advance, arcDelta, angleOf, laneAtAngle,
    angleSpan: { from: ang[0], to: ang[lanes] },
    // Angle PI/2 is straight down in a y-down world. On an open web whose rim
    // never reaches the bottom, laneAtAngle clamps to the nearest end.
    bottom: laneAtAngle(Math.PI / 2),

    turn(lane: number, dAngle: number): number {
      let a = angleOf(lane) + dAngle;
      // Clamp in UNWRAPPED angle space, or a big turn on an open web wraps
      // right past the end and comes back round instead of stopping at it.
      if (!closed) {
        const lo = Math.min(ang[0], ang[lanes]), hi = Math.max(ang[0], ang[lanes]);
        a = Math.max(lo, Math.min(hi, a));
      }
      return laneAtAngle(a);
    },

    // Which way is the player's RIGHT? At the bottom of the web, where the ship
    // sits, a rim that winds CLOCKWISE on screen runs leftward — differentiate
    // c + r(cos t, sin t) at t = PI/2 and the tangent is (-1, 0). A rim that
    // winds the other way runs rightward there. That is the whole difference,
    // it is one sign, and it is known once at build time: `wind`.
    //
    // It is also the entire reason a vee felt right while every closed profile
    // felt inverted — the vee is the only silhouette here that winds
    // anticlockwise on screen.
    steer(lane: number, dist: number): number {
      return advance(lane, -wind * dist);
    },

    laneLength(i: number): number {
      return laneLen[Math.min(lanes - 1, Math.max(0, closed ? ((i % lanes) + lanes) % lanes : i))];
    },

    glide(from: number, to: number, maxDist: number): number {
      const d = arcDelta(from, to);
      return Math.abs(d) <= maxDist ? wrapLane(to) : advance(from, Math.sign(d) * maxDist);
    },

    laneAt(lane: number, t: number): LanePose {
      // Lane `l` spans rim parameter l..l+1, so its middle is l + 0.5.
      const u = wrapLane(lane) + 0.5;
      const here = rimPointAt(u, t);
      // Facing runs along the LANE — near-mid minus far-mid — so an off-centre
      // vanishing point tilts the ships correctly rather than pointing them
      // all at the middle of the screen.
      const n0 = rimPointAt(u, 0), f0 = rimPointAt(u, 1);
      // Scale is the lane's width at this depth over its width at the rim.
      const wa = rimPointAt(u - 0.5, t), wb = rimPointAt(u + 0.5, t);
      const na = rimPointAt(u - 0.5, 0), nb = rimPointAt(u + 0.5, 0);
      const nw = Math.hypot(nb.x - na.x, nb.y - na.y);
      return {
        x: here.x,
        y: here.y,
        angle: Math.atan2(n0.y - f0.y, n0.x - f0.x),
        scale: nw > 0 ? Math.hypot(wb.x - wa.x, wb.y - wa.y) / nw : 1,
      };
    },

    stepLane(from: number, to: number, maxStep: number): number {
      const d = laneDelta(from, to);
      return Math.abs(d) <= maxStep ? wrapLane(to) : wrapLane(from + Math.sign(d) * maxStep);
    },

    laneOf(x0: number, y0: number): number {
      // Nearest point on the near rim, as a rim parameter — then back off half
      // a lane so the LANE CENTRE lands under the cursor.
      let bestU = 0, bestD = Infinity;
      for (let i = 0; i < lanes; i++) {
        const a = rimAt(i, 0), b = rimAt(i + 1, 0);
        const dx = b.x - a.x, dy = b.y - a.y;
        const l2 = dx * dx + dy * dy;
        const f = l2 > 0 ? Math.max(0, Math.min(1, ((x0 - a.x) * dx + (y0 - a.y) * dy) / l2)) : 0;
        const px = a.x + dx * f, py = a.y + dy * f;
        const d = (x0 - px) ** 2 + (y0 - py) ** 2;
        if (d < bestD) { bestD = d; bestU = i + f; }
      }
      return wrapLane(bestU - 0.5);
    },
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// PROJECTED WIREFRAME — Battlezone, Star Wars, Red Baron, Tail Gunner, Elite.
//
// First-person line art is a 3D problem solved on a 2D canvas: the hardware had
// no depth buffer and no shading, just a beam and a matrix. That is exactly what
// this is — points through a camera, edges clipped at the near plane, straight
// out as 2D segments for `poly()`/`seg()`. No 3D chunk, no depth attachment,
// nothing to load.
//
// Axes: x RIGHT, y UP, z FORWARD. (The 3D convention, not the 2D layer's y-down
// screen space — the projection converts.) A camera at yaw 0 looks along +z;
// increasing `yaw` turns RIGHT, increasing `pitch` looks UP.
// ─────────────────────────────────────────────────────────────────────────────

/** A point in 3D world space (x right, y up, z forward). */
export interface Vec3 { x: number; y: number; z: number }

/** A wireframe model: shared points, plus the index pairs that join them. */
export interface WireModel {
  points: Vec3[];
  edges: Array<[number, number]>;
}

/** Where the camera is and which way it is looking. */
export interface WireCamera {
  x: number; y: number; z: number;
  /** Heading in radians — 0 looks along +z, increasing turns RIGHT. */
  yaw?: number;
  /** Tilt in radians — increasing looks UP. */
  pitch?: number;
  /** Vertical field of view in radians (default 1.05, about 60°). */
  fov?: number;
}

/** The screen rect to project into (world units — usually `game.view`). */
export interface WireView {
  w: number;
  h: number;
  /** Nothing closer than this is drawn (default 1). Keeps the divide sane. */
  near?: number;
}

/** One projected edge, with the depth at each end so width can taper. */
export interface WireEdge {
  a: { x: number; y: number };
  b: { x: number; y: number };
  /** Distance in front of the camera at each end, AFTER near-plane clipping. */
  za: number;
  zb: number;
}

/**
 * Pixels per world unit at one unit of depth. Divide by an edge's `za`/`zb` for
 * the scale at that end — the whole of perspective in one number.
 *
 * ```ts
 * const f = vectorKit.focalLength(view);
 * layer.seg(e.a.x, e.a.y, e.b.x, e.b.y, { width: Math.max(0.4, 3 * f / e.za / 40) });
 * ```
 */
export function focalLength(view: WireView, fov = 1.05): number {
  return (view.h / 2) / Math.tan(fov / 2);
}

/** @internal World point → camera space (x right, y up, z forward-of-camera). */
function toView(p: Vec3, cam: WireCamera): Vec3 {
  const dx = p.x - cam.x, dy = p.y - cam.y, dz = p.z - cam.z;
  const cy = Math.cos(cam.yaw ?? 0), sy = Math.sin(cam.yaw ?? 0);
  const vx = dx * cy - dz * sy;
  const vz = dx * sy + dz * cy;
  const cp = Math.cos(cam.pitch ?? 0), sp = Math.sin(cam.pitch ?? 0);
  return { x: vx, y: dy * cp - vz * sp, z: dy * sp + vz * cp };
}

/**
 * Project ONE world point to the screen, or `null` if it is behind the near
 * plane. Handy for placing 2D things (labels, a targeting box, a sprite) on a
 * 3D position without projecting a whole model.
 */
export function projectPoint(
  p: Vec3, cam: WireCamera, view: WireView,
): { x: number; y: number; z: number } | null {
  const v = toView(p, cam);
  const near = view.near ?? 1;
  if (v.z <= near) return null;
  const f = focalLength(view, cam.fov ?? 1.05);
  // Screen y is DOWN, world y is UP — hence the minus.
  return { x: view.w / 2 + (v.x * f) / v.z, y: view.h / 2 - (v.y * f) / v.z, z: v.z };
}

/**
 * Project a wireframe model to 2D segments, near-plane clipped.
 *
 * ```ts
 * for (const e of vectorKit.project(tank, cam, view)) {
 *   game.vector.seg(e.a.x, e.a.y, e.b.x, e.b.y, { color: '#41d6ff', width: 3 * f / e.za });
 * }
 * ```
 *
 * An edge straddling the near plane is CUT at it rather than dropped, so
 * geometry doesn't pop out of existence as you walk into it — the one thing a
 * naive projector always gets wrong (divide by a negative z and the edge
 * whips across the screen backwards).
 */
export function project(model: WireModel, cam: WireCamera, view: WireView): WireEdge[] {
  const near = view.near ?? 1;
  const f = focalLength(view, cam.fov ?? 1.05);
  const hw = view.w / 2, hh = view.h / 2;
  const vs = model.points.map((p) => toView(p, cam));
  const out: WireEdge[] = [];
  for (const [i, j] of model.edges) {
    let a = vs[i], b = vs[j];
    if (!a || !b) continue;
    if (a.z <= near && b.z <= near) continue;              // wholly behind
    if (a.z <= near || b.z <= near) {                      // straddling — cut it
      const t = (near - a.z) / (b.z - a.z);
      const cut = { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t, z: near };
      if (a.z <= near) a = cut; else b = cut;
    }
    out.push({
      a: { x: hw + (a.x * f) / a.z, y: hh - (a.y * f) / a.z },
      b: { x: hw + (b.x * f) / b.z, y: hh - (b.y * f) / b.z },
      za: a.z, zb: b.z,
    });
  }
  return out;
}

/**
 * The ground line — where a flat plane at infinite distance lands on screen.
 *
 * It depends only on `pitch` (yaw slides along it, and there is no roll), so it
 * is a horizontal line at `h/2 + f·tan(pitch)`. Draw it first and everything
 * else sits in a world.
 */
export function horizon(cam: WireCamera, view: WireView): [{ x: number; y: number }, { x: number; y: number }] {
  const f = focalLength(view, cam.fov ?? 1.05);
  const y = view.h / 2 + f * Math.tan(cam.pitch ?? 0);
  return [{ x: 0, y }, { x: view.w, y }];
}

/**
 * A wireframe box centred on `(cx, cy, cz)` — eight points and twelve edges of
 * pure boilerplate, and the staple obstacle of every first-person vector game.
 */
export function wireBox(w: number, h: number, d: number, cx = 0, cy = 0, cz = 0): WireModel {
  const x = w / 2, y = h / 2, z = d / 2;
  return {
    points: [
      { x: cx - x, y: cy - y, z: cz - z }, { x: cx + x, y: cy - y, z: cz - z },
      { x: cx + x, y: cy + y, z: cz - z }, { x: cx - x, y: cy + y, z: cz - z },
      { x: cx - x, y: cy - y, z: cz + z }, { x: cx + x, y: cy - y, z: cz + z },
      { x: cx + x, y: cy + y, z: cz + z }, { x: cx - x, y: cy + y, z: cz + z },
    ],
    edges: [
      [0, 1], [1, 2], [2, 3], [3, 0],
      [4, 5], [5, 6], [6, 7], [7, 4],
      [0, 4], [1, 5], [2, 6], [3, 7],
    ],
  };
}

/** A model's axis-aligned extent, and the size and centre it implies. */
export interface WireBounds {
  min: Vec3;
  max: Vec3;
  size: Vec3;
  center: Vec3;
}

/**
 * Measure a model: the corners of its axis-aligned box, and the size and centre
 * they imply. For a cheap distance cull, or for scaling something to fit.
 *
 * To stand a model on the ground use `placeModelOnGround`, which does the sum
 * for you.
 */
export function wireBounds(model: WireModel): WireBounds {
  const zero = { x: 0, y: 0, z: 0 };
  if (model.points.length === 0) {
    return { min: { ...zero }, max: { ...zero }, size: { ...zero }, center: { ...zero } };
  }
  const min = { x: Infinity, y: Infinity, z: Infinity };
  const max = { x: -Infinity, y: -Infinity, z: -Infinity };
  for (const p of model.points) {
    if (p.x < min.x) min.x = p.x;
    if (p.y < min.y) min.y = p.y;
    if (p.z < min.z) min.z = p.z;
    if (p.x > max.x) max.x = p.x;
    if (p.y > max.y) max.y = p.y;
    if (p.z > max.z) max.z = p.z;
  }
  return {
    min,
    max,
    size: { x: max.x - min.x, y: max.y - min.y, z: max.z - min.z },
    center: { x: (min.x + max.x) / 2, y: (min.y + max.y) / 2, z: (min.z + max.z) / 2 },
  };
}

/**
 * Move and turn a model without touching the original — the way you place many
 * copies of one shape, or drive a tank around. `yaw` turns it about its own
 * vertical axis first, then it is offset to `(x, y, z)`.
 *
 * `y` positions the model's OWN ORIGIN, wherever the model happens to keep it.
 * If what you want is for the thing to stand on the floor, reach for
 * `placeModelOnGround` and give it no `y` at all.
 */
export function placeModel(model: WireModel, x: number, y: number, z: number, yaw = 0): WireModel {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  return {
    points: model.points.map((p) => ({
      x: x + p.x * c + p.z * s,
      y: y + p.y,
      z: z - p.x * s + p.z * c,
    })),
    edges: model.edges,
  };
}

/**
 * Stand a model on the ground at `(x, z)` — the placement a first-person
 * wireframe scene actually wants.
 *
 * ```ts
 * const block = vectorKit.placeModelOnGround(vectorKit.wireBox(120, 280, 90), 900, -1400);
 * const tank  = vectorKit.placeModelOnGround(TANK, tx, tz, heading);
 * ```
 *
 * No height to work out and none to get wrong. Models keep their origin
 * wherever suits them — `wireBox` about its centre, a hand-built pyramid at its
 * base — so "put it at y = 0" means different things for different models and
 * silently buries the ones built about their middle. This asks each model where
 * its own floor is and drops it exactly there, so a box, a pyramid and a
 * multi-part tank all land flush without the caller knowing how any of them
 * were built.
 *
 * `groundY` moves the floor; `yaw` turns the model about its vertical axis,
 * which cannot change how tall it is, so it stays flush at any heading.
 */
export function placeModelOnGround(
  model: WireModel, x: number, z: number, yaw = 0, groundY = 0,
): WireModel {
  return placeModel(model, x, groundY - wireBounds(model).min.y, z, yaw);
}

/**
 * A ground grid as a wireframe model — `n` lines each way at `step` apart,
 * centred on `(cx, cz)` at height `y`. The cheapest way to make a first-person
 * scene feel like it has a floor.
 */
export function wireGrid(n: number, step: number, y = 0, cx = 0, cz = 0): WireModel {
  const points: Vec3[] = [];
  const edges: Array<[number, number]> = [];
  const half = (n * step) / 2;
  for (let i = 0; i <= n; i++) {
    const o = -half + i * step;
    const base = points.length;
    points.push({ x: cx + o, y, z: cz - half }, { x: cx + o, y, z: cz + half });
    points.push({ x: cx - half, y, z: cz + o }, { x: cx + half, y, z: cz + o });
    edges.push([base, base + 1], [base + 2, base + 3]);
  }
  return { points, edges };
}

// ─────────────────────────────────────────────────────────────────────────────
// CONVEXITY — what a physics engine needs and a vector outline never has.
//
// Box2D polygons are CONVEX and capped at 8 vertices. Vector silhouettes are
// neither: `generatePolygon` is jagged and 10+ points, `textOutline` strokes
// wander, a ship is a dart. Feeding an over-long point list straight to
// `b2ComputeHull` returns a hull of count 0 — a null shape, no error — so the
// reduction has to happen first, and deliberately.
// ─────────────────────────────────────────────────────────────────────────────

/** The most vertices a Box2D polygon shape can hold (B2_MAX_POLYGON_VERTICES). */
export const MAX_HULL_POINTS = 8;

/**
 * The convex hull of a point set (monotone chain), counter-clockwise in
 * standard axes — which is CLOCKWISE on screen, y being down.
 *
 * Fewer than three distinct points comes back as-is; collinear points are
 * dropped.
 */
export function convexHull(points: readonly VecPt[]): VecPt[] {
  const pts = points.map((p) => ({ x: p.x, y: p.y }))
    .sort((a, b) => (a.x - b.x) || (a.y - b.y));
  // Drop exact duplicates — they make the cross-product test degenerate.
  const uniq: VecPt[] = [];
  for (const p of pts) {
    const last = uniq[uniq.length - 1];
    if (!last || last.x !== p.x || last.y !== p.y) uniq.push(p);
  }
  if (uniq.length < 3) return uniq;
  const cross = (o: VecPt, a: VecPt, b: VecPt): number =>
    (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
  const half = (src: VecPt[]): VecPt[] => {
    const out: VecPt[] = [];
    for (const p of src) {
      while (out.length >= 2 && cross(out[out.length - 2], out[out.length - 1], p) <= 0) out.pop();
      out.push(p);
    }
    out.pop();
    return out;
  };
  return [...half(uniq), ...half([...uniq].reverse())];
}

/**
 * Reduce a CONVEX outline to at most `max` vertices, dropping the ones that
 * cost the least area — so the silhouette survives as well as it can.
 *
 * This is the step that stops an 11-point asteroid becoming a null Box2D
 * shape. Run `convexHull` first; on a concave input the areas are meaningless.
 */
export function simplifyHull(points: readonly VecPt[], max = MAX_HULL_POINTS): VecPt[] {
  const pts = points.map((p) => ({ x: p.x, y: p.y }));
  if (max < 3) return pts.slice(0, Math.max(0, max));
  while (pts.length > max) {
    // The triangle each vertex forms with its neighbours IS the area lost by
    // removing it.
    let worst = 0, worstArea = Infinity;
    for (let i = 0; i < pts.length; i++) {
      const a = pts[(i - 1 + pts.length) % pts.length], b = pts[i], c = pts[(i + 1) % pts.length];
      const area = Math.abs((b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x)) / 2;
      if (area < worstArea) { worstArea = area; worst = i; }
    }
    pts.splice(worst, 1);
  }
  return pts;
}

/**
 * Outline → a point list Box2D will actually accept: convex, at most
 * `MAX_HULL_POINTS` vertices, in the shape's own local frame.
 *
 * **Do not re-centre the result on its centroid.** Box2D computes centroid,
 * mass and inertia from the polygon in body-local space, so passing the raw
 * local points keeps the drawn outline and the collision shape registered.
 * Re-centring looks tidier and is the bug — a shape that spins about a point
 * it isn't drawn around.
 */
export function hullFor(points: readonly VecPt[], max = MAX_HULL_POINTS): VecPt[] {
  return simplifyHull(convexHull(points), max);
}

/**
 * Split a simple polygon into CONVEX pieces (ear clipping, then merging ears
 * back together while the join stays convex and within `max` vertices).
 *
 * The honest way to give a concave silhouette — a ship, a plus, a letter — real
 * collision instead of the hull's approximation: each piece becomes its own
 * Box2D polygon on ONE body, so the notch is a notch.
 *
 * Returns `[points]` unchanged when the outline is already convex and short
 * enough, so the cheap case stays cheap.
 */
export function convexPieces(points: readonly VecPt[], max = MAX_HULL_POINTS): VecPt[][] {
  const poly = points.map((p) => ({ x: p.x, y: p.y }));
  if (poly.length < 3) return [];
  if (poly.length <= max && isConvex(poly)) return [poly];

  // Ear clipping needs a known winding; normalise to counter-clockwise.
  if (signedArea(poly) < 0) poly.reverse();
  const ears: VecPt[][] = [];
  const work = poly.slice();
  let guard = work.length * work.length + 16;
  while (work.length > 3 && guard-- > 0) {
    let clipped = false;
    for (let i = 0; i < work.length; i++) {
      const a = work[(i - 1 + work.length) % work.length];
      const b = work[i];
      const c = work[(i + 1) % work.length];
      if (cross3(a, b, c) <= 0) continue;                 // reflex, not an ear
      let contains = false;
      for (let j = 0; j < work.length; j++) {
        const p = work[j];
        if (p === a || p === b || p === c) continue;
        if (inTriangle(p, a, b, c)) { contains = true; break; }
      }
      if (contains) continue;
      ears.push([a, b, c]);
      work.splice(i, 1);
      clipped = true;
      break;
    }
    if (!clipped) break;                                   // degenerate input
  }
  if (work.length === 3) ears.push(work);

  // Merge neighbouring triangles back up while the result stays convex — a
  // handful of quads and pentagons costs far less than a fan of triangles.
  const out: VecPt[][] = [];
  for (const ear of ears) {
    const last = out[out.length - 1];
    if (last) {
      const merged = mergeIfConvex(last, ear, max);
      if (merged) { out[out.length - 1] = merged; continue; }
    }
    out.push(ear);
  }
  return out;
}

function signedArea(p: readonly VecPt[]): number {
  let a = 0;
  for (let i = 0; i < p.length; i++) {
    const q = p[i], r = p[(i + 1) % p.length];
    a += q.x * r.y - r.x * q.y;
  }
  return a / 2;
}

function cross3(a: VecPt, b: VecPt, c: VecPt): number {
  return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

function inTriangle(p: VecPt, a: VecPt, b: VecPt, c: VecPt): boolean {
  const d1 = cross3(a, b, p), d2 = cross3(b, c, p), d3 = cross3(c, a, p);
  return (d1 >= 0 && d2 >= 0 && d3 >= 0) || (d1 <= 0 && d2 <= 0 && d3 <= 0);
}

/** True if every turn goes the same way (a convex simple polygon). */
export function isConvex(p: readonly VecPt[]): boolean {
  if (p.length < 3) return false;
  let sign = 0;
  for (let i = 0; i < p.length; i++) {
    const c = cross3(p[i], p[(i + 1) % p.length], p[(i + 2) % p.length]);
    if (Math.abs(c) < 1e-9) continue;
    const s = c > 0 ? 1 : -1;
    if (sign === 0) sign = s;
    else if (s !== sign) return false;
  }
  return true;
}

/** @internal Two pieces sharing an edge, joined — if the join stays convex. */
function mergeIfConvex(a: VecPt[], b: VecPt[], max: number): VecPt[] | null {
  if (a.length + b.length - 2 > max) return null;
  const same = (p: VecPt, q: VecPt): boolean => p.x === q.x && p.y === q.y;
  for (let i = 0; i < a.length; i++) {
    const a0 = a[i], a1 = a[(i + 1) % a.length];
    for (let j = 0; j < b.length; j++) {
      const b0 = b[j], b1 = b[(j + 1) % b.length];
      if (!(same(a0, b1) && same(a1, b0))) continue;       // shared edge, reversed
      const merged: VecPt[] = [];
      for (let k = 0; k < a.length; k++) merged.push(a[(i + 1 + k) % a.length]);
      for (let k = 1; k < b.length - 1; k++) merged.push(b[(j + 1 + k) % b.length]);
      return isConvex(merged) ? merged : null;
    }
  }
  return null;
}

/**
 * Ear-clipping triangulation of a simple polygon — index triples into
 * `points`. Handles concave outlines and either winding; no holes, no
 * self-intersection. Degenerate input fans the remainder rather than looping.
 *
 * This is what turns a vector OUTLINE into a filled face. It lives here rather
 * than being borrowed from the 3D geometry module because the vector layer
 * must never pull in the 3D chunk.
 */
export function triangulate(points: readonly VecPt[]): Array<[number, number, number]> {
  const n = points.length;
  if (n < 3) return [];
  const idx = points.map((_, i) => i);
  // Consistent winding, so the ear test below has one sign to look for.
  let area = 0;
  for (let i = 0; i < n; i++) {
    const a = points[i], b = points[(i + 1) % n];
    area += a.x * b.y - b.x * a.y;
  }
  if (area < 0) idx.reverse();

  const cross = (a: number, b: number, c: number): number =>
    (points[b].x - points[a].x) * (points[c].y - points[a].y)
    - (points[b].y - points[a].y) * (points[c].x - points[a].x);
  const inside = (a: number, b: number, c: number, p: number): boolean =>
    cross(a, b, p) >= -1e-12 && cross(b, c, p) >= -1e-12 && cross(c, a, p) >= -1e-12;

  const out: Array<[number, number, number]> = [];
  let guard = n * n + 8;
  while (idx.length > 3 && guard-- > 0) {
    let clipped = false;
    for (let i = 0; i < idx.length; i++) {
      const a = idx[(i + idx.length - 1) % idx.length], b = idx[i], c = idx[(i + 1) % idx.length];
      if (cross(a, b, c) <= 1e-12) continue;                 // reflex or degenerate
      let blocked = false;
      for (const p of idx) {
        if (p === a || p === b || p === c) continue;
        if (inside(a, b, c, p)) { blocked = true; break; }
      }
      if (blocked) continue;
      out.push([a, b, c]);
      idx.splice(i, 1);
      clipped = true;
      break;
    }
    if (!clipped) break;
  }
  for (let i = 1; i < idx.length - 1; i++) out.push([idx[0], idx[i], idx[i + 1]]);
  return out;
}
