// The post-effect chain: the world (2D + 3D + particles) renders into an
// offscreen target, each active effect runs as one full-screen pass
// (ping-ponging between two targets), and the last pass writes to the
// swapchain. The HUD is drawn AFTER the chain, so it stays crisp through
// pixelate/CRT/etc (set game.hudAboveFx = false to push it through too).
//
// Pipelines are compiled once per effect name and cached; params live in a
// per-instance uniform buffer, updatable every frame at zero pipeline cost.
// All GPU objects rebuild from CPU state (device-loss path).

import { BITS } from './gpu.js';
import { buildEffectWGSL, effectDefaults, effectParamIndex, EFFECTS, type EffectDef } from './effects.js';

/** A live effect in the chain — retune or remove it at any time. */
export class PostHandle {
  /** @internal */
  constructor(
    readonly def: EffectDef,
    /** @internal */ public data: Float32Array,
    private chain: PostChain,
  ) {}

  /** Update a parameter (by the name declared in the effect). */
  set(param: string, value: number): this {
    const i = effectParamIndex(this.def, param);
    if (i >= 0) this.data[4 + i] = value; // after the res vec4
    return this;
  }

  /** Remove this effect from the chain. */
  remove(): void {
    this.chain.drop(this);
  }
}

interface Pass {
  handle: PostHandle;
  pipeline: GPURenderPipeline;
  uniforms: GPUBuffer;
}

export class PostChain {
  private passes: Pass[] = [];
  private pipelines = new Map<string, GPURenderPipeline>();
  private layout!: GPUBindGroupLayout;
  private sampler!: GPUSampler;
  private device!: GPUDevice;
  private targets: [GPUTexture, GPUTexture] | null = null;

  constructor(device: GPUDevice, private format: GPUTextureFormat) {
    this.rebuild(device);
  }

  /** Any effects active? (Game skips the offscreen path entirely when not.) */
  get active(): boolean {
    return this.passes.length > 0;
  }

  /** Append an effect (built-in name or a custom EffectDef — the MCP-block path). */
  add(effect: string | EffectDef, params?: Record<string, number>): PostHandle {
    const def = typeof effect === 'string' ? EFFECTS[effect] : effect;
    if (!def) throw new Error(`unknown post effect '${String(effect)}' — built-ins: ${Object.keys(EFFECTS).join(', ')}`);
    const data = new Float32Array(12); // res vec4 + p0 + p1
    data.set(effectDefaults(def), 4);
    const handle = new PostHandle(def, data, this);
    for (const [k, v] of Object.entries(params ?? {})) handle.set(k, v);
    this.passes.push({
      handle,
      pipeline: this.pipelineFor(def),
      uniforms: this.device.createBuffer({ size: data.byteLength, usage: BITS.UNIFORM | BITS.COPY_DST }),
    });
    return handle;
  }

  /** @internal */
  drop(handle: PostHandle): void {
    const i = this.passes.findIndex((p) => p.handle === handle);
    if (i >= 0) {
      this.passes[i].uniforms.destroy();
      this.passes.splice(i, 1);
    }
  }

  /** Remove every effect. */
  clear(): void {
    for (const p of this.passes) p.uniforms.destroy();
    this.passes = [];
  }

  /** The offscreen view the world should render into this frame. */
  sceneView(width: number, height: number): GPUTextureView {
    if (!this.targets || this.targets[0].width !== width || this.targets[0].height !== height) {
      this.targets?.forEach((t) => t.destroy());
      const make = (): GPUTexture => this.device.createTexture({
        size: { width, height },
        format: this.format,
        usage: BITS.RENDER_ATTACHMENT | BITS.TEXTURE_BINDING,
      });
      this.targets = [make(), make()];
    }
    return this.targets[0].createView();
  }

  /** Run every pass; the last one lands on `dst` (the swapchain). */
  run(encoder: GPUCommandEncoder, dst: GPUTextureView, time: number): void {
    if (!this.targets) return;
    let src = 0;
    this.passes.forEach((p, i) => {
      const last = i === this.passes.length - 1;
      p.handle.data[0] = this.targets![src].width;
      p.handle.data[1] = this.targets![src].height;
      p.handle.data[2] = time;
      this.device.queue.writeBuffer(p.uniforms, 0, p.handle.data);
      const bind = this.device.createBindGroup({
        layout: this.layout,
        entries: [
          { binding: 0, resource: { buffer: p.uniforms } },
          { binding: 1, resource: this.sampler },
          { binding: 2, resource: this.targets![src].createView() },
        ],
      });
      const pass = encoder.beginRenderPass({
        colorAttachments: [{
          view: last ? dst : this.targets![1 - src].createView(),
          loadOp: 'clear',
          clearValue: { r: 0, g: 0, b: 0, a: 1 },
          storeOp: 'store',
        }],
      });
      pass.setPipeline(p.pipeline);
      pass.setBindGroup(0, bind);
      pass.draw(3);
      pass.end();
      src = 1 - src;
    });
  }

  /** (Re)create GPU objects — the device-loss recovery path. */
  rebuild(device: GPUDevice): void {
    this.device = device;
    this.pipelines.clear();
    this.targets = null;
    this.sampler = device.createSampler({ magFilter: 'linear', minFilter: 'linear' });
    this.layout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX | BITS.STAGE_FRAGMENT, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_FRAGMENT, sampler: {} },
        { binding: 2, visibility: BITS.STAGE_FRAGMENT, texture: {} },
      ],
    });
    this.passes = this.passes.map((p) => ({
      handle: p.handle,
      pipeline: this.pipelineFor(p.handle.def),
      uniforms: device.createBuffer({ size: p.handle.data.byteLength, usage: BITS.UNIFORM | BITS.COPY_DST }),
    }));
  }

  private pipelineFor(def: EffectDef): GPURenderPipeline {
    let pipeline = this.pipelines.get(def.name);
    if (pipeline) return pipeline;
    const module = this.device.createShaderModule({ code: buildEffectWGSL(def) });
    void module.getCompilationInfo().then((info) => {
      for (const m of info.messages) {
        if (m.type === 'error') console.error(`post '${def.name}' WGSL ${m.lineNum}:${m.linePos} ${m.message}`);
      }
    });
    pipeline = this.device.createRenderPipeline({
      layout: this.device.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: { module, entryPoint: 'vs' },
      fragment: { module, entryPoint: 'fs', targets: [{ format: this.format }] },
      primitive: { topology: 'triangle-list' },
    });
    this.pipelines.set(def.name, pipeline);
    return pipeline;
  }
}

/**
 * THE POST CHAIN — full-screen effects applied OVER the finished frame:
 * `game.post.add('bloom')`, `game.post.clear()`. Built-ins by name
 * ('pixelate', 'vignette', 'bloom', 'crt', 'scanlines', 'posterize',
 * 'grayscale', 'wave', 'chroma') or a custom EffectDef (the block path).
 *
 * NOT particles — a fire/smoke/spark EFFECT IN the world is `game.fx`.
 */
export class PostLayer {
  private readonly chain: () => PostChain;

  /** @internal Built by `Game` — reach it as `game.post`, never construct one. */
  constructor(chain: () => PostChain) {
    this.chain = chain;
  }

  /**
   * Add an effect to the chain (applied in add order). Returns a handle:
   * `.set(param, value)` to retune live, `.remove()` to drop just this one.
   */
  add(effect: string | EffectDef, params?: Record<string, number>): PostHandle {
    return this.chain().add(effect, params);
  }

  /** Remove every post effect. */
  clear(): void {
    this.chain().clear();
  }
}
