/**
 * 2D VISIBILITY / line-of-sight against real scenery — pure CPU geometry, zero
 * engine dependency. Import it directly (`import { Visibility2d } from
 * '../engine/webgpu.js'`); it is NOT wired into `Game`.
 *
 * The NON-grid counterpart to `FogGrid`: shadows thrown by actual line-segment
 * occluders (walls, crates, polygons), not tiles. From a light/eye point it
 * computes the **visibility polygon** — the exact lit area, with hard shadows
 * behind occluders (the classic top-down-2D "throw a light and it casts shadows
 * off the scenery" look). Feed that polygon to a renderer (fill it, one light
 * per colour, additive), or use the detection queries directly:
 * `canSee(a, b)` for "can the guard see the player?" and `raycast()` for the
 * first thing a ray hits.
 *
 * Algorithm (redblobgames.com/articles/visibility): cast rays to every occluder
 * corner (± a hair, to slip past edges), keep the nearest hit per ray, and sort
 * the hits by angle into a fan around the light. Add world `bounds` (or a
 * `maxDist`) so rays always terminate.
 */

import type { Vec2 } from './util.js';

/** An occluder edge — a line segment `(x1,y1)–(x2,y2)` that casts shadow. */
export interface Segment {
  /** Start X. */ x1: number;
  /** Start Y. */ y1: number;
  /** End X. */ x2: number;
  /** End Y. */ y2: number;
}

/** A ray hit: the point and the distance along the ray. */
export interface RayHit2d {
  /** Hit X. */ x: number;
  /** Hit Y. */ y: number;
  /** Distance from the ray origin to the hit. */ dist: number;
}

const EPS = 1e-9;

/**
 * A set of 2D occluders you query for visibility and line-of-sight. Add
 * scenery as segments / rects / polygons (and a world `bounds`), then call
 * `visibility(x, y)` for the lit polygon or `canSee` / `raycast` for detection.
 * Add/remove occluders freely between frames — there's no bake.
 *
 * ```ts
 * const vis = new Visibility2d();
 * vis.setBounds(0, 0, worldW, worldH);          // rays terminate at the edges
 * for (const c of crates) vis.addRect(c.x, c.y, c.w, c.h);
 * const poly = vis.visibility(light.x, light.y, light.radius);   // lit-area polygon → render it
 * if (vis.canSee(guard.x, guard.y, player.x, player.y)) alert();  // line-of-sight
 * ```
 */
export class Visibility2d {
  /** The occluder segments (excludes the world bounds — those live separately). */
  readonly segments: Segment[] = [];
  private bx = 0; private by = 0; private bw = 0; private bh = 0;
  private hasBounds = false;

  constructor(bounds?: { x: number; y: number; w: number; h: number }) {
    if (bounds) this.setBounds(bounds.x, bounds.y, bounds.w, bounds.h);
  }

  /** Set the world rectangle — rays that hit no occluder stop at these edges
   *  (so `visibility` always closes into a polygon). */
  setBounds(x: number, y: number, w: number, h: number): void {
    this.bx = x; this.by = y; this.bw = w; this.bh = h; this.hasBounds = true;
  }

  /** Add one occluder segment; returns it (mutate or keep a reference). */
  addSegment(x1: number, y1: number, x2: number, y2: number): Segment {
    const s = { x1, y1, x2, y2 };
    this.segments.push(s);
    return s;
  }

  /** Add a box occluder (its four edges). */
  addRect(x: number, y: number, w: number, h: number): void {
    this.addSegment(x, y, x + w, y);
    this.addSegment(x + w, y, x + w, y + h);
    this.addSegment(x + w, y + h, x, y + h);
    this.addSegment(x, y + h, x, y);
  }

  /** Add a polygon occluder from points (`[{x,y}…]` or flat `[x,y,…]`). Closed
   *  by default (the last point links back to the first). */
  addPoly(points: ReadonlyArray<Vec2> | ReadonlyArray<number>, closed = true): void {
    const pts: Vec2[] = typeof points[0] === 'number'
      ? Array.from({ length: (points as number[]).length / 2 }, (_, i) => ({ x: (points as number[])[i * 2], y: (points as number[])[i * 2 + 1] }))
      : (points as Vec2[]);
    for (let i = 0; i < pts.length - 1; i++) this.addSegment(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
    if (closed && pts.length > 2) this.addSegment(pts[pts.length - 1].x, pts[pts.length - 1].y, pts[0].x, pts[0].y);
  }

  /** Remove all occluders (bounds are kept). */
  clear(): void { this.segments.length = 0; }

  /** @internal Visit every occluder segment plus the four bounds edges. */
  private _forEach(cb: (x1: number, y1: number, x2: number, y2: number) => void): void {
    for (const s of this.segments) cb(s.x1, s.y1, s.x2, s.y2);
    if (this.hasBounds) {
      const { bx, by, bw, bh } = this;
      cb(bx, by, bx + bw, by); cb(bx + bw, by, bx + bw, by + bh);
      cb(bx + bw, by + bh, bx, by + bh); cb(bx, by + bh, bx, by);
    }
  }

  /**
   * The visibility polygon from `(lx, ly)` — the ordered fan of points bounding
   * the lit area, with hard shadows behind occluders. Clamped to `maxDist` (the
   * light radius) when given. Render it as a triangle fan from the light, or
   * read it for custom shading. Empty only if there's no geometry to hit.
   */
  visibility(lx: number, ly: number, maxDist = Infinity): Vec2[] {
    // Cull occluders to the light's reach box once (bounds always kept), so a
    // scene with thousands of segments only tests the handful near this light.
    const segs: number[] = []; // flat x1,y1,x2,y2
    const far = maxDist;
    for (const s of this.segments) {
      if (far < Infinity && (Math.max(s.x1, s.x2) < lx - far || Math.min(s.x1, s.x2) > lx + far ||
        Math.max(s.y1, s.y2) < ly - far || Math.min(s.y1, s.y2) > ly + far)) continue;
      segs.push(s.x1, s.y1, s.x2, s.y2);
    }
    if (this.hasBounds) {
      const { bx, by, bw, bh } = this;
      segs.push(bx, by, bx + bw, by, bx + bw, by, bx + bw, by + bh, bx + bw, by + bh, bx, by + bh, bx, by + bh, bx, by);
    }

    // Cast three rays near every corner angle (slip just past each edge).
    const angles: number[] = [];
    for (let i = 0; i < segs.length; i += 4) {
      const a1 = Math.atan2(segs[i + 1] - ly, segs[i] - lx);
      const a2 = Math.atan2(segs[i + 3] - ly, segs[i + 2] - lx);
      angles.push(a1 - 0.00005, a1, a1 + 0.00005, a2 - 0.00005, a2, a2 + 0.00005);
    }

    const hits: Array<{ a: number; x: number; y: number }> = [];
    for (const a of angles) {
      const dx = Math.cos(a), dy = Math.sin(a);
      let best = maxDist;
      let found = maxDist < Infinity;
      for (let i = 0; i < segs.length; i += 4) {
        const t = raySegT(lx, ly, dx, dy, segs[i], segs[i + 1], segs[i + 2], segs[i + 3]);
        if (t !== null && t < best) { best = t; found = true; }
      }
      if (found) hits.push({ a, x: lx + dx * best, y: ly + dy * best });
    }

    hits.sort((p, q) => p.a - q.a);
    return hits.map((h) => ({ x: h.x, y: h.y }));
  }

  /**
   * Direct line-of-sight — `true` if no occluder segment crosses the line from
   * `(ax,ay)` to `(bx,by)`. The AI "can the guard see the player?" test; pass
   * `maxDist` to cap the range. Ignores the world bounds (they enclose, not block).
   */
  canSee(ax: number, ay: number, bx: number, by: number, maxDist = Infinity): boolean {
    const dx = bx - ax, dy = by - ay;
    if (dx * dx + dy * dy > maxDist * maxDist) return false;
    for (const s of this.segments) {
      if (segCross(ax, ay, bx, by, s.x1, s.y1, s.x2, s.y2)) return false;
    }
    return true;
  }

  /**
   * The first occluder (or bounds) a ray hits from `(ox,oy)` heading
   * `(dirX,dirY)`. Returns `{x, y, dist}` or `null` if nothing is hit within
   * `maxDist`. Direction need not be normalised.
   */
  raycast(ox: number, oy: number, dirX: number, dirY: number, maxDist = Infinity): RayHit2d | null {
    const len = Math.hypot(dirX, dirY) || 1;
    const dx = dirX / len, dy = dirY / len;
    let best = maxDist;
    let hit = false;
    this._forEach((x1, y1, x2, y2) => {
      const t = raySegT(ox, oy, dx, dy, x1, y1, x2, y2);
      if (t !== null && t < best) { best = t; hit = true; }
    });
    return hit ? { x: ox + dx * best, y: oy + dy * best, dist: best } : null;
  }
}

/** Distance along a normalised ray `(ox,oy)+t·(dx,dy)` to segment `(x1,y1)-(x2,y2)`,
 *  or `null` if it misses. */
function raySegT(
  ox: number, oy: number, dx: number, dy: number,
  x1: number, y1: number, x2: number, y2: number,
): number | null {
  const sx = x2 - x1, sy = y2 - y1;
  const denom = dx * sy - dy * sx;
  if (Math.abs(denom) < EPS) return null;          // parallel
  const t2 = ((x1 - ox) * dy - (y1 - oy) * dx) / denom;   // along the segment, want 0..1
  if (t2 < 0 || t2 > 1) return null;
  const t1 = ((x1 - ox) * sy - (y1 - oy) * sx) / denom;   // along the ray (= distance)
  return t1 >= 0 ? t1 : null;
}

/** Do segments `a-b` and `c-d` cross? */
function segCross(
  ax: number, ay: number, bx: number, by: number,
  cx: number, cy: number, dx: number, dy: number,
): boolean {
  const r_px = bx - ax, r_py = by - ay;
  const s_px = dx - cx, s_py = dy - cy;
  const denom = r_px * s_py - r_py * s_px;
  if (Math.abs(denom) < EPS) return false;         // parallel / collinear
  const t = ((cx - ax) * s_py - (cy - ay) * s_px) / denom;
  const u = ((cx - ax) * r_py - (cy - ay) * r_px) / denom;
  return t > EPS && t < 1 - EPS && u > EPS && u < 1 - EPS;
}
